__CR('projects',{"ai":[{"lv":1,"em":"🧹","title":"데이터 정제 파이프라인","desc":"지저분한 원본 데이터를 분석 가능한 깨끗한 데이터로 만드는 정제 파이프라인","skills":["python","pandas"],"phases":[{"t":"요구사항 정리","type":"note","goal":"정제 대상 데이터의 <b>품질 기준</b>을 정의해보세요\n결측치, 중복, 이상치를 어떤 규칙으로 처리할지 적어보세요","ph":"예: 결측률 30% 초과 컬럼은 제외, 매출은 음수 불가, 주문ID로 중복 제거"},{"t":"결측치 처리 전략","type":"decide","goal":"매출 원본에 결측치가 섞여 있습니다","sit":"결측치를 어떻게 처리할까요?","opts":[{"label":"컬럼 특성별로 전략을 나눈다(수치는 중앙값, 범주는 최빈값)","fx":{"coding":5},"fb":"✅ 컬럼 의미를 살려 정보 손실을 최소화하는 표준 접근입니다","best":true},{"label":"결측이 하나라도 있는 행을 전부 삭제한다","fx":{"coding":-2},"fb":"❌ 표본이 급감하고 편향이 생깁니다","best":false},{"label":"모든 결측을 0으로 일괄 채운다","fx":{"coding":-1},"fb":"⚠️ 범주형/날짜에는 부적절하고 집계를 왜곡합니다","best":false}]},{"t":"정제 함수 구현","type":"build","goal":"컬럼명을 표준화하고 결측치를 타입별 전략으로 대치하는 함수를 만드세요","hint":"select_dtypes로 수치형/범주형을 나눠 median과 mode를 활용하세요","acc":"clean_sales가 결측치 없는 DataFrame을 반환한다","sol":"import pandas as pd\n\ndef clean_sales(df):\n    df = df.copy()\n    # 컬럼명 표준화\n    df.columns = [c.strip().lower() for c in df.columns]\n    # 수치형 결측치는 중앙값으로 대치\n    num_cols = df.select_dtypes(include=\"number\").columns\n    for c in num_cols:\n        df[c] = df[c].fillna(df[c].median())\n    # 범주형 결측치는 최빈값으로 대치\n    cat_cols = df.select_dtypes(include=\"object\").columns\n    for c in cat_cols:\n        mode = df[c].mode()\n        if not mode.empty:\n            df[c] = df[c].fillna(mode[0])\n    return df","lang":"python"},{"t":"중복 제거와 타입 변환","type":"build","goal":"중복 레코드를 제거하고 숫자/날짜 타입으로 변환하며 이상치를 걸러내세요","hint":"drop_duplicates의 keep 옵션과 to_numeric의 errors 인자를 활용하세요","acc":"키 컬럼 중복이 사라지고 amount가 0 이상만 남는다","sol":"def dedup_and_cast(df, key_cols):\n    df = df.copy()\n    # 최신 레코드 우선으로 정렬 후 중복 제거\n    df = df.sort_values(\"updated_at\")\n    df = df.drop_duplicates(subset=key_cols, keep=\"last\")\n    # 타입 변환(변환 실패는 결측 처리)\n    df[\"amount\"] = pd.to_numeric(df[\"amount\"], errors=\"coerce\")\n    df[\"order_date\"] = pd.to_datetime(df[\"order_date\"], errors=\"coerce\")\n    # 이상치 제거(음수 매출)\n    df = df[df[\"amount\"] >= 0]\n    return df.reset_index(drop=True)","lang":"python"},{"t":"검증 규칙 설계","type":"note","goal":"정제 결과를 어떻게 <b>검증</b>할지 적어보세요\n입력 대비 출력의 행 수, 합계, 결측률을 어떻게 비교할지 정의하세요","ph":"예: 출력 행 수는 입력 이하, 결측률 0%, 총 매출 편차 1% 이내"},{"t":"배치 스케줄 결정","type":"decide","goal":"정제 파이프라인을 매일 자동 실행하려 합니다","sit":"실행 방식을 어떻게 할까요?","opts":[{"label":"멱등하게 설계하고 새벽 스케줄러로 일 1회 실행한다","fx":{"system_design":5},"fb":"✅ 재실행해도 결과가 같아 안전하게 운영됩니다","best":true},{"label":"파일이 들어올 때마다 수동으로 실행한다","fx":{"system_design":-2},"fb":"❌ 누락과 사람 실수가 반복됩니다","best":false},{"label":"1분마다 전체를 재처리한다","fx":{"performance":-2},"fb":"⚠️ 자원 낭비가 크고 이득이 없습니다","best":false}]},{"t":"장애 발생: 인코딩 깨짐","type":"decide","goal":"새벽 배치 후 정제 결과에 한글이 깨지고 결측률이 급증했습니다","sit":"첫 대응을 어떻게 할까요?","opts":[{"label":"인코딩을 자동 감지해 재처리하고 실패 건은 원본을 격리한다","fx":{"debugging":5},"fb":"✅ 원인 계층에서 막고 오염 확산을 차단합니다","best":true},{"label":"깨진 행을 그냥 버리고 진행한다","fx":{"debugging":-2},"fb":"❌ 실제 데이터가 유실됩니다","best":false},{"label":"인코딩을 무시하고 파이프라인을 통과시킨다","fx":{"debugging":-3},"fb":"❌ 오염이 다운스트림으로 번집니다","best":false}]},{"t":"연쇄 2차: 중복 폭증","type":"decide","goal":"인코딩은 고쳤지만 재처리 과정에서 같은 데이터가 이중 적재되어 중복이 폭증했습니다","sit":"다음 대응은?","opts":[{"label":"멱등 키 기준으로 upsert 재적재해 중복을 제거한다","fx":{"database":5},"fb":"✅ 재처리에도 안전한 멱등 적재로 정리됩니다","best":true},{"label":"전체 테이블을 truncate하고 처음부터 다시 넣는다","fx":{"database":-2},"fb":"❌ 다운타임과 대량 재처리 비용이 큽니다","best":false},{"label":"중복은 나중에 보기로 하고 넘어간다","fx":{"database":-3},"fb":"❌ 집계 오류가 그대로 전파됩니다","best":false}]},{"t":"연쇄 3차: 집계 뻥튀기","type":"decide","goal":"중복 때문에 다운스트림 집계가 2배로 부풀어 대시보드에 이상치가 나타났습니다","sit":"어떻게 대응할까요?","opts":[{"label":"영향받은 날짜 파티션만 골라 재집계한다","fx":{"system_design":5},"fb":"✅ 범위를 좁혀 빠르고 저렴하게 복구합니다","best":true},{"label":"전체 기간을 통째로 재집계한다","fx":{"performance":-2},"fb":"⚠️ 시간과 비용이 과도합니다","best":false},{"label":"대시보드 캐시만 새로고침한다","fx":{"system_design":-3},"fb":"❌ 원본 집계가 여전히 틀립니다","best":false}]},{"t":"원인분석과 재발방지","type":"decide","goal":"장애가 마무리되었고 같은 사고를 막아야 합니다","sit":"재발방지 조치로 무엇을 도입할까요?","opts":[{"label":"소스 인코딩/스키마 검증과 멱등 적재를 파이프라인 게이트로 추가한다","fx":{"system_design":6},"fb":"✅ 원인과 확산 경로를 모두 구조적으로 차단합니다","best":true},{"label":"문제가 보이면 담당자가 수동 확인하도록 한다","fx":{"communication":-1},"fb":"⚠️ 사람 의존이라 재발합니다","best":false},{"label":"모니터링 지표만 하나 더 붙인다","fx":{"system_design":-2},"fb":"❌ 감지만 될 뿐 예방되지 않습니다","best":false}]},{"t":"Postmortem 작성","type":"note","goal":"이번 장애의 <b>타임라인과 근본 원인</b>을 정리해보세요\n인코딩 오염이 어떻게 중복과 집계 오류로 연쇄되었는지, 무엇을 표준화할지 기록하세요","ph":"예: 트리거(인코딩), 확산 경로(재처리 중복), 영향(집계 2배), 조치(스키마 검증+멱등 적재), 재발방지 항목"}]},{"lv":2,"em":"🔀","title":"ETL 배치 파이프라인","desc":"소스 DB에서 데이터를 추출해 변환하고 데이터 웨어하우스에 적재하는 배치 파이프라인","skills":["python","sql"],"phases":[{"t":"요구사항 정리","type":"note","goal":"ETL의 <b>소스와 타겟, 배치 주기, SLA</b>를 정의해보세요\n하루 처리량과 허용 지연을 적어보세요","ph":"예: 소스는 주문 DB, 타겟은 DW, 매시간 배치, 완료 SLA 30분 이내"},{"t":"적재 방식 결정","type":"decide","goal":"매 배치마다 소스 전체를 옮길지 변경분만 옮길지 정해야 합니다","sit":"적재 전략을 어떻게 할까요?","opts":[{"label":"updated_at 워터마크 기반 증분 적재를 한다","fx":{"system_design":5},"fb":"✅ 처리량과 비용을 크게 줄이는 표준 방식입니다","best":true},{"label":"매번 소스 전체를 다시 적재한다","fx":{"performance":-2},"fb":"❌ 데이터가 커질수록 비용이 폭증합니다","best":false},{"label":"변경 행마다 실시간 트리거로 밀어넣는다","fx":{"system_design":-1},"fb":"⚠️ 배치 요건에 과설계이고 운영이 복잡합니다","best":false}]},{"t":"증분 추출 구현","type":"build","goal":"워터마크 이후 변경된 행만 추출하고 새 워터마크를 계산하는 함수를 만드세요","hint":"updated_at 비교 조건과 마지막 워터마크 갱신 로직에 집중하세요","acc":"변경분만 반환하고 최신 워터마크가 함께 나온다","sol":"from datetime import datetime\n\ndef extract_incremental(conn, watermark):\n    # 워터마크 이후 변경분만 추출(증분)\n    query = \"\"\"\n        SELECT id, name, amount, updated_at\n        FROM source_orders\n        WHERE updated_at > %(wm)s\n        ORDER BY updated_at\n    \"\"\"\n    rows = conn.execute(query, {\"wm\": watermark}).fetchall()\n    records, new_wm = [], watermark\n    for r in rows:\n        rec = dict(r)\n        rec[\"amount\"] = float(rec[\"amount\"] or 0)\n        rec[\"ingested_at\"] = datetime.utcnow()\n        records.append(rec)\n        if rec[\"updated_at\"] > new_wm:\n            new_wm = rec[\"updated_at\"]\n    return records, new_wm","lang":"python"},{"t":"멱등 적재 쿼리","type":"build","goal":"스테이징 데이터를 타겟에 MERGE로 멱등하게 적재하는 SQL을 작성하세요","hint":"MATCHED 조건에 updated_at 비교를 넣어 최신만 갱신하세요","acc":"동일 배치를 재실행해도 중복 없이 최신 상태가 유지된다","sol":"-- 타겟에 멱등하게 적재(중복 방지)\nMERGE INTO dw_orders AS t\nUSING staging_orders AS s\nON t.id = s.id\nWHEN MATCHED AND s.updated_at > t.updated_at THEN\n    UPDATE SET\n        name = s.name,\n        amount = s.amount,\n        updated_at = s.updated_at\nWHEN NOT MATCHED THEN\n    INSERT (id, name, amount, updated_at)\n    VALUES (s.id, s.name, s.amount, s.updated_at);","lang":"sql"},{"t":"정합성 검증 설계","type":"note","goal":"적재 결과의 <b>데이터 정합성</b>을 어떻게 확인할지 적어보세요\n소스 대비 타겟의 행 수와 금액 합계 비교 방법을 정의하세요","ph":"예: 소스 변경 건수와 타겟 반영 건수 일치, 금액 합계 편차 0, 워터마크 단조 증가"},{"t":"배포 스케줄러 선택","type":"decide","goal":"배치를 안정적으로 자동 실행하려 합니다","sit":"실행 기반을 무엇으로 할까요?","opts":[{"label":"DAG 스케줄러로 의존성과 재시도 정책을 정의한다","fx":{"system_design":5},"fb":"✅ 실패 복구와 백필을 체계적으로 관리합니다","best":true},{"label":"cron 한 줄로 스크립트만 돌린다","fx":{"system_design":-2},"fb":"⚠️ 실패 추적과 재처리가 어렵습니다","best":false},{"label":"사람이 시간 맞춰 수동 실행한다","fx":{"system_design":-3},"fb":"❌ 누락과 실수가 반복됩니다","best":false}]},{"t":"장애 발생: 스키마 변경","type":"decide","goal":"소스에 컬럼이 추가되며 배치가 매 실행 실패하기 시작했습니다","sit":"첫 대응을 어떻게 할까요?","opts":[{"label":"스키마 변경을 감지해 신규 컬럼을 nullable로 안전 매핑한다","fx":{"debugging":5},"fb":"✅ 유연한 매핑으로 소스 변화를 흡수합니다","best":true},{"label":"컬럼 목록을 코드에 하드코딩한 채로 둔다","fx":{"debugging":-2},"fb":"❌ 소스가 바뀔 때마다 또 깨집니다","best":false},{"label":"배치를 그냥 꺼둔다","fx":{"system_design":-2},"fb":"❌ 데이터가 밀리고 SLA를 위반합니다","best":false}]},{"t":"연쇄 2차: 재시도 폭주","type":"decide","goal":"실패한 배치가 자동 재시도를 짧은 간격으로 반복하며 소스 DB에 부하를 줍니다","sit":"다음 대응은?","opts":[{"label":"지수 백오프와 최대 재시도 한도를 적용한다","fx":{"system_design":5},"fb":"✅ 재시도를 통제해 부하 폭주를 막습니다","best":true},{"label":"성공할 때까지 재시도를 무한 반복시킨다","fx":{"performance":-3},"fb":"❌ DB 부하가 눈덩이처럼 커집니다","best":false},{"label":"재시도를 아예 없앤다","fx":{"system_design":-1},"fb":"⚠️ 일시적 오류에도 복구가 안 됩니다","best":false}]},{"t":"연쇄 3차: 중복 적재","type":"decide","goal":"재시도 도중 일부만 성공해 타겟에 같은 주문이 중복 적재되었습니다","sit":"어떻게 대응할까요?","opts":[{"label":"MERGE 멱등 적재로 전환하고 중복분을 정리한다","fx":{"database":5},"fb":"✅ 재시도에도 안전한 멱등성을 확보합니다","best":true},{"label":"타겟을 DELETE한 뒤 다시 INSERT한다","fx":{"database":-2},"fb":"⚠️ 락과 다운타임이 발생합니다","best":false},{"label":"중복은 리포트 단에서 알아서 걸러지길 기대한다","fx":{"database":-3},"fb":"❌ 지표가 이중 집계됩니다","best":false}]},{"t":"원인분석과 재발방지","type":"decide","goal":"장애를 복구했고 같은 유형의 사고를 막아야 합니다","sit":"재발방지로 무엇을 표준화할까요?","opts":[{"label":"소스 스키마 컨트랙트 검증과 멱등 적재를 파이프라인 표준으로 넣는다","fx":{"system_design":6},"fb":"✅ 스키마 변화와 재시도 중복을 구조적으로 차단합니다","best":true},{"label":"배치 실패 알림만 추가한다","fx":{"communication":-1},"fb":"⚠️ 감지만 될 뿐 원인은 남습니다","best":false},{"label":"재시도 횟수만 조금 줄인다","fx":{"system_design":-2},"fb":"❌ 스키마 문제와 중복은 그대로입니다","best":false}]},{"t":"Postmortem 작성","type":"note","goal":"이번 배치 장애의 <b>연쇄 흐름</b>을 정리해보세요\n스키마 변경이 어떻게 재시도 폭주와 중복 적재로 이어졌는지, 무엇을 컨트랙트화할지 기록하세요","ph":"예: 트리거(컬럼 추가), 확산(무한 재시도), 영향(중복 적재/지표 오류), 조치(스키마 검증+멱등화), 재발방지"}]},{"lv":3,"em":"🤖","title":"ML 모델 서빙 API","desc":"학습된 머신러닝 모델을 실시간 추론 API로 제공하는 서빙 백엔드","skills":["ml","python","backend"],"phases":[{"t":"요구사항 정리","type":"note","goal":"서빙 API의 <b>지연/처리량 SLA와 입력 스키마</b>를 정의해보세요\np99 지연 목표와 초당 요청 수를 적어보세요","ph":"예: p99 200ms 이내, 초당 500건, 입력은 고정 차원 피처 벡터"},{"t":"추론 처리 방식 결정","type":"decide","goal":"요청을 단건으로 처리할지 묶어서 처리할지 정해야 합니다","sit":"추론 처리 방식을 어떻게 할까요?","opts":[{"label":"마이크로배치로 요청을 묶어 처리량을 확보한다","fx":{"performance":5},"fb":"✅ GPU 활용률과 처리량이 크게 올라갑니다","best":true},{"label":"요청마다 무조건 단건 추론한다","fx":{"performance":-2},"fb":"❌ 처리량이 낮고 자원 낭비가 큽니다","best":false},{"label":"모든 요청을 비동기 큐로만 처리한다","fx":{"system_design":-1},"fb":"⚠️ 실시간 요건에는 지연이 과합니다","best":false}]},{"t":"추론 엔드포인트 구현","type":"build","goal":"동시성 상한과 타임아웃을 갖춘 추론 API를 만드세요","hint":"Semaphore로 동시 추론을 제한하고 wait_for로 타임아웃을 거세요","acc":"정상 입력은 점수를, 지연 시 503을 반환한다","sol":"from fastapi import FastAPI, HTTPException\nimport asyncio, time\n\napp = FastAPI()\n_sem = asyncio.Semaphore(8)  # 동시 추론 상한\n\n@app.post(\"/predict\")\nasync def predict(req: dict):\n    features = req.get(\"features\")\n    if not features:\n        raise HTTPException(status_code=400, detail=\"features 필요\")\n    try:\n        async with _sem:\n            # 타임아웃으로 지연 폭주를 차단\n            score = await asyncio.wait_for(run_infer(features), timeout=1.5)\n    except asyncio.TimeoutError:\n        raise HTTPException(status_code=503, detail=\"추론 타임아웃\")\n    return {\"score\": score, \"ts\": time.time()}","lang":"python"},{"t":"마이크로배칭 구현","type":"build","goal":"짧은 시간 동안 요청을 모아 배치로 추론하는 배처를 만드세요","hint":"Future로 개별 응답을 돌려주고 배치가 차면 flush하세요","acc":"여러 요청이 한 번의 predict 호출로 처리된다","sol":"import asyncio\n\nclass MicroBatcher:\n    def __init__(self, max_size=16, max_wait=0.02):\n        self.max_size = max_size\n        self.max_wait = max_wait\n        self.queue = []\n\n    async def submit(self, x):\n        fut = asyncio.get_event_loop().create_future()\n        self.queue.append((x, fut))\n        # 배치가 차면 즉시 flush\n        if len(self.queue) >= self.max_size:\n            await self._flush()\n        return await fut\n\n    async def _flush(self):\n        batch, self.queue = self.queue, []\n        xs = [x for x, _ in batch]\n        preds = model.predict(xs)  # 묶어서 한 번에 추론\n        for (_, fut), p in zip(batch, preds):\n            fut.set_result(p)","lang":"python"},{"t":"부하 테스트 설계","type":"note","goal":"배포 전 <b>부하 테스트</b> 계획을 적어보세요\n목표 처리량에서 p99 지연과 오류율을 어떻게 측정할지 정의하세요","ph":"예: 초당 500건 램프업, p99 200ms 유지, 오류율 0.1% 미만, 포화점 탐색"},{"t":"배포 방식 결정","type":"decide","goal":"새 모델 버전을 프로덕션에 올리려 합니다","sit":"배포 전략을 어떻게 할까요?","opts":[{"label":"카나리로 소량 트래픽에 먼저 태우고 지표를 본다","fx":{"system_design":5},"fb":"✅ 위험을 국소화하고 안전하게 롤아웃합니다","best":true},{"label":"전체 트래픽을 한 번에 새 버전으로 전환한다","fx":{"system_design":-2},"fb":"❌ 문제 시 전면 장애가 됩니다","best":false},{"label":"검증 없이 바로 배포한다","fx":{"system_design":-3},"fb":"❌ 회귀를 감지할 방법이 없습니다","best":false}]},{"t":"장애 발생: 트래픽 급증","type":"decide","goal":"프로모션으로 트래픽이 5배로 늘며 p99 추론 지연이 급등했습니다","sit":"첫 대응을 어떻게 할까요?","opts":[{"label":"동적 배칭과 오토스케일로 처리량을 확대한다","fx":{"performance":5},"fb":"✅ 병목을 늘려 급증 트래픽을 흡수합니다","best":true},{"label":"인스턴스를 그대로 두고 상황을 지켜본다","fx":{"performance":-2},"fb":"❌ 지연이 계속 쌓여 악화됩니다","best":false},{"label":"모든 요청을 즉시 거절한다","fx":{"system_design":-2},"fb":"❌ 서비스가 사실상 중단됩니다","best":false}]},{"t":"연쇄 2차: 재시도 폭주","type":"decide","goal":"지연으로 클라이언트 타임아웃이 발생하고 자동 재시도가 폭주하기 시작했습니다","sit":"다음 대응은?","opts":[{"label":"서버 타임아웃과 백프레셔로 초과 요청을 빠르게 차단한다","fx":{"system_design":5},"fb":"✅ 재시도 증폭을 끊어 시스템을 보호합니다","best":true},{"label":"클라이언트 재시도를 무제한 허용한다","fx":{"performance":-3},"fb":"❌ 부하가 기하급수로 증폭됩니다","best":false},{"label":"타임아웃 값을 사실상 무한대로 늘린다","fx":{"system_design":-2},"fb":"❌ 자원이 묶여 더 빨리 무너집니다","best":false}]},{"t":"연쇄 3차: GPU 메모리 부족","type":"decide","goal":"재시도 폭주로 동시 추론이 몰려 GPU 메모리가 부족해지고 일부 파드가 크래시했습니다","sit":"어떻게 대응할까요?","opts":[{"label":"동시 추론 수를 세마포어로 제한하고 요청 큐에 상한을 둔다","fx":{"system_design":5},"fb":"✅ 메모리 상한을 지켜 OOM 크래시를 막습니다","best":true},{"label":"처리량을 위해 배치 크기를 더 키운다","fx":{"performance":-3},"fb":"❌ 메모리 사용이 커져 OOM이 심해집니다","best":false},{"label":"GPU 메모리 로그만 계속 관찰한다","fx":{"debugging":-1},"fb":"⚠️ 관찰만으로는 크래시가 멈추지 않습니다","best":false}]},{"t":"원인분석과 재발방지","type":"decide","goal":"장애를 복구했고 트래픽 급증에 견디도록 만들어야 합니다","sit":"재발방지로 무엇을 도입할까요?","opts":[{"label":"오토스케일 정책, 동시성 상한, 서킷브레이커를 함께 도입한다","fx":{"system_design":6},"fb":"✅ 급증부터 증폭까지 전 구간을 구조적으로 방어합니다","best":true},{"label":"GPU만 더 증설한다","fx":{"performance":-1},"fb":"⚠️ 증폭 구조가 남아 다시 포화됩니다","best":false},{"label":"타임아웃 값만 다시 조정한다","fx":{"system_design":-2},"fb":"❌ 근본 원인이 남습니다","best":false}]},{"t":"Postmortem 작성","type":"note","goal":"이번 서빙 장애의 <b>연쇄 사슬</b>을 정리해보세요\n트래픽 급증이 어떻게 지연, 재시도 폭주, GPU OOM으로 번졌는지와 방어 계층을 기록하세요","ph":"예: 트리거(트래픽 5배), 증폭(재시도), 붕괴(GPU OOM), 조치(백프레셔+동시성 상한+서킷브레이커), 재발방지"}]},{"lv":4,"em":"🎯","title":"실시간 추천 시스템","desc":"사용자 행동에 기반해 실시간으로 후보를 생성하고 랭킹하는 추천 시스템","skills":["ml","system_design","database"],"phases":[{"t":"요구사항 정리","type":"note","goal":"추천 시스템의 <b>대상, 지연 SLA, 피처 종류</b>를 정의해보세요\n어떤 지표로 성공을 판단할지 적어보세요","ph":"예: 홈 화면 추천, 응답 100ms 이내, 행동/인기/개인화 피처, 성공 지표는 CTR"},{"t":"피처 저장소 설계","type":"decide","goal":"학습과 서빙에서 같은 피처를 일관되게 쓰려고 합니다","sit":"피처 관리 방식을 어떻게 할까요?","opts":[{"label":"온/오프라인 피처스토어를 분리하되 정의를 공유한다","fx":{"system_design":5},"fb":"✅ 학습-서빙 일관성을 보장하는 표준 구조입니다","best":true},{"label":"서빙 시점에 매번 실시간으로 피처를 계산한다","fx":{"performance":-2},"fb":"❌ 지연이 커지고 계산이 불일치합니다","best":false},{"label":"오프라인 피처만 쓰고 서빙엔 캐시된 값만 쓴다","fx":{"system_design":-1},"fb":"⚠️ 신선도가 떨어져 품질이 낮아집니다","best":false}]},{"t":"추천 파이프라인 구현","type":"build","goal":"후보 생성과 피처 조회, 랭킹을 묶은 추천 함수를 만드세요","hint":"협업필터와 인기 후보를 합치고 신선도 초과 시 폴백하세요","acc":"정상 시 랭킹 상위 k개를, 신선도 초과 시 인기 아이템을 반환한다","sol":"def recommend(user_id, k=10):\n    # 1) 후보 생성(협업필터 + 인기 아이템)\n    cands = set(cf_candidates(user_id, n=200))\n    cands |= set(popular_items(n=100))\n    # 2) 온라인 피처 스토어에서 피처 조회\n    feats = feature_store.get_online(user_id, list(cands))\n    # 신선도 초과 시 안전 폴백\n    if feats.max_staleness() > 900:\n        return popular_items(n=k)\n    # 3) 랭킹 모델로 점수화\n    scored = []\n    for item in cands:\n        x = feats.vector(user_id, item)\n        scored.append((item, ranker.predict(x)))\n    scored.sort(key=lambda t: t[1], reverse=True)\n    return [i for i, _ in scored[:k]]","lang":"python"},{"t":"피처 집계 쿼리","type":"build","goal":"최근 30일 사용자 행동을 집계해 피처 테이블에 upsert하는 SQL을 작성하세요","hint":"집계 함수와 ON CONFLICT를 이용해 멱등 갱신하세요","acc":"사용자별 최신 행동 피처가 중복 없이 유지된다","sol":"-- 사용자별 최근 30일 행동 피처 집계\nINSERT INTO user_features\nSELECT\n    user_id,\n    COUNT(*) AS event_cnt_30d,\n    COUNT(DISTINCT item_id) AS uniq_item_30d,\n    SUM(CASE WHEN action = 'purchase' THEN 1 ELSE 0 END) AS purchase_30d,\n    MAX(event_time) AS last_event_at\nFROM events\nWHERE event_time >= NOW() - INTERVAL '30 days'\nGROUP BY user_id\nON CONFLICT (user_id) DO UPDATE\nSET event_cnt_30d = EXCLUDED.event_cnt_30d,\n    uniq_item_30d = EXCLUDED.uniq_item_30d,\n    purchase_30d = EXCLUDED.purchase_30d,\n    last_event_at = EXCLUDED.last_event_at;","lang":"sql"},{"t":"오프라인 평가 설계","type":"note","goal":"배포 전 <b>추천 품질</b>을 어떻게 평가할지 적어보세요\nNDCG나 recall 같은 지표와 기준선을 정의하세요","ph":"예: NDCG@10을 기준선 대비 비교, 최소 개선폭 정의, 세그먼트별 검증"},{"t":"배포 방식 결정","type":"decide","goal":"새 랭킹 모델의 효과를 검증하며 올리려 합니다","sit":"배포 전략을 어떻게 할까요?","opts":[{"label":"A/B 테스트로 트래픽을 나눠 온라인 지표를 비교한다","fx":{"system_design":5},"fb":"✅ 실제 사용자 지표로 인과적 효과를 검증합니다","best":true},{"label":"오프라인 지표만 보고 전량 배포한다","fx":{"system_design":-2},"fb":"⚠️ 온라인에서 역효과일 위험이 큽니다","best":false},{"label":"검증 없이 새 모델로 전환한다","fx":{"system_design":-3},"fb":"❌ 품질 회귀를 감지할 수 없습니다","best":false}]},{"t":"장애 발생: 피처 파이프라인 지연","type":"decide","goal":"피처 배치가 2시간 지연되어 서빙 피처가 최신이 아닌 상태가 되었습니다","sit":"첫 대응을 어떻게 할까요?","opts":[{"label":"신선도 임계 초과 시 폴백 피처로 서빙하고 알림을 울린다","fx":{"system_design":5},"fb":"✅ 오염된 피처 대신 안전한 경로로 품질을 지킵니다","best":true},{"label":"지연된 낡은 피처를 그대로 서빙한다","fx":{"system_design":-2},"fb":"❌ 품질이 저하되고 사용자가 이탈합니다","best":false},{"label":"추천을 랜덤 결과로 대체한다","fx":{"performance":-3},"fb":"❌ 사용자 경험이 크게 나빠집니다","best":false}]},{"t":"연쇄 2차: 학습-서빙 스큐","type":"decide","goal":"학습은 신선 피처로, 서빙은 낡은 피처로 이뤄져 학습-서빙 스큐가 발생했습니다","sit":"다음 대응은?","opts":[{"label":"서빙과 동일한 피처로 재학습하고 스큐 모니터를 추가한다","fx":{"database":5},"fb":"✅ 분포 불일치를 바로잡고 재발을 감시합니다","best":true},{"label":"증상이 보일 때마다 모델을 롤백만 반복한다","fx":{"system_design":-2},"fb":"⚠️ 근본 원인이 남아 계속 반복됩니다","best":false},{"label":"스큐는 무시하고 그대로 둔다","fx":{"database":-3},"fb":"❌ 예측 품질이 지속적으로 나빠집니다","best":false}]},{"t":"연쇄 3차: 지표 하락","type":"decide","goal":"스큐로 인해 CTR 등 추천 품질 지표가 눈에 띄게 하락했습니다","sit":"어떻게 대응할까요?","opts":[{"label":"안정적인 이전 모델로 롤백한 뒤 원인을 격리한다","fx":{"system_design":5},"fb":"✅ 사용자 영향을 먼저 멈추고 안전하게 조사합니다","best":true},{"label":"랭킹 가중치를 감으로 임의 조정한다","fx":{"performance":-2},"fb":"❌ 검증 없는 조정은 상황을 악화시킵니다","best":false},{"label":"트래픽 전량을 신모델에 계속 유지한다","fx":{"system_design":-3},"fb":"❌ 지표 하락이 확대됩니다","best":false}]},{"t":"원인분석과 재발방지","type":"decide","goal":"장애를 복구했고 피처 지연이 품질로 번지지 않게 해야 합니다","sit":"재발방지로 무엇을 도입할까요?","opts":[{"label":"피처 신선도 SLA와 학습-서빙 스큐 검증을 파이프라인 게이트로 넣는다","fx":{"system_design":6},"fb":"✅ 지연 감지와 스큐 차단을 자동화합니다","best":true},{"label":"지표 대시보드만 하나 더 만든다","fx":{"communication":-1},"fb":"⚠️ 감지만 될 뿐 예방되지 않습니다","best":false},{"label":"피처 파이프라인을 그때그때 수동 재실행한다","fx":{"system_design":-2},"fb":"❌ 사람 의존이라 또 지연됩니다","best":false}]},{"t":"Postmortem 작성","type":"note","goal":"이번 추천 품질 장애의 <b>연쇄 흐름</b>을 정리해보세요\n피처 지연이 어떻게 학습-서빙 스큐와 지표 하락으로 이어졌는지, 어떤 게이트를 세울지 기록하세요","ph":"예: 트리거(피처 2시간 지연), 확산(스큐), 영향(CTR 하락), 조치(신선도 폴백+스큐 검증), 재발방지"}]},{"lv":5,"em":"🔎","title":"RAG 문서 검색 시스템","desc":"문서를 임베딩해 벡터DB에 색인하고 질의에 맞는 근거를 검색해 답변 컨텍스트를 만드는 RAG 시스템","skills":["ml","system_design","backend"],"phases":[{"t":"요구사항 정리","type":"note","goal":"RAG 시스템의 <b>문서 규모, 검색 정확도, 지연 목표</b>를 정의해보세요\n무엇을 근거로 답을 구성할지 적어보세요","ph":"예: 문서 10만 건, recall@5 0.9 목표, 검색 300ms 이내, 답변엔 출처 포함"},{"t":"청킹 전략 결정","type":"decide","goal":"문서를 어떤 단위로 잘라 색인할지 정해야 합니다","sit":"청킹 전략을 어떻게 할까요?","opts":[{"label":"의미 단위로 나누고 오버랩을 둬 문맥을 보존한다","fx":{"system_design":5},"fb":"✅ 경계에서 문맥 단절을 줄여 검색 품질이 오릅니다","best":true},{"label":"무조건 고정 길이로 자른다","fx":{"system_design":-2},"fb":"❌ 문장 중간이 끊겨 근거가 훼손됩니다","best":false},{"label":"문서 전체를 한 청크로 넣는다","fx":{"performance":-2},"fb":"❌ 검색 정밀도와 토큰 효율이 나빠집니다","best":false}]},{"t":"문서 색인 구현","type":"build","goal":"문서를 청킹해 배치 임베딩으로 벡터DB에 색인하는 함수를 만드세요","hint":"오버랩 청킹과 batch_size 단위 upsert에 집중하세요","acc":"모든 청크가 출처 메타데이터와 함께 색인된다","sol":"from vectordb import Client\n\nclient = Client()\n\ndef index_documents(docs, batch_size=64):\n    buffer = []\n    for doc in docs:\n        # 의미 단위 청킹 + 오버랩으로 문맥 보존\n        chunks = chunk_text(doc[\"text\"], size=512, overlap=64)\n        for i, ch in enumerate(chunks):\n            buffer.append({\n                \"id\": f\"{doc['id']}-{i}\",\n                \"text\": ch,\n                \"meta\": {\"source\": doc[\"id\"]},\n            })\n        if len(buffer) >= batch_size:\n            vecs = embed([b[\"text\"] for b in buffer])  # 배치 임베딩\n            client.upsert(buffer, vecs)\n            buffer = []\n    if buffer:\n        vecs = embed([b[\"text\"] for b in buffer])\n        client.upsert(buffer, vecs)","lang":"python"},{"t":"검색과 컨텍스트 구성","type":"build","goal":"벡터 검색 후 리랭크하고 토큰 예산 안에서 컨텍스트를 조립하세요","hint":"top_k를 넉넉히 뽑아 리랭크하고 토큰 예산을 초과하면 멈추세요","acc":"관련도 높은 근거가 토큰 한도 안에서 반환된다","sol":"def search(query, k=5):\n    q_vec = embed([query])[0]\n    # 1차 벡터 검색(넉넉히 회수)\n    hits = client.query(q_vec, top_k=30)\n    # 2차 리랭크로 정밀도 향상\n    reranked = reranker.rank(query, [h[\"text\"] for h in hits])\n    top = reranked[:k]\n    # 토큰 예산 안에서 컨텍스트 구성\n    context, budget = [], 3000\n    for h in top:\n        tokens = count_tokens(h[\"text\"])\n        if budget - tokens < 0:\n            break\n        context.append(h[\"text\"])\n        budget -= tokens\n    return \"\\n\\n\".join(context)","lang":"python"},{"t":"검색 품질 평가 설계","type":"note","goal":"배포 전 <b>검색 품질</b>을 어떻게 평가할지 적어보세요\nrecall@k 같은 지표와 정답 셋 구성 방법을 정의하세요","ph":"예: 질문-근거 정답 셋으로 recall@5 측정, 리랭크 유무 비교, 지연도 함께 기록"},{"t":"인덱스 롤아웃 결정","type":"decide","goal":"새 임베딩 모델로 만든 인덱스를 프로덕션에 반영하려 합니다","sit":"롤아웃 방식을 어떻게 할까요?","opts":[{"label":"새 인덱스를 병행 구축한 뒤 별칭 스위칭으로 무중단 전환한다","fx":{"system_design":5},"fb":"✅ 다운타임 없이 안전하게 교체하고 롤백도 쉽습니다","best":true},{"label":"운영 인덱스를 그 자리에서 덮어쓴다","fx":{"system_design":-2},"fb":"❌ 재색인 동안 검색이 망가집니다","best":false},{"label":"검증 없이 새 인덱스로 바로 전환한다","fx":{"system_design":-3},"fb":"❌ 품질 회귀를 놓칩니다","best":false}]},{"t":"장애 발생: 임베딩 큐 적체","type":"decide","goal":"대량 문서 업로드로 임베딩 큐가 급격히 적체되기 시작했습니다","sit":"첫 대응을 어떻게 할까요?","opts":[{"label":"인덱싱 처리량을 제한하고 우선순위 큐로 온라인 검색을 보호한다","fx":{"system_design":5},"fb":"✅ 배치 작업이 실시간 검색을 잠식하지 못하게 격리합니다","best":true},{"label":"인덱싱을 무제한 병렬로 밀어붙인다","fx":{"performance":-3},"fb":"❌ 자원을 독점해 검색까지 마비됩니다","best":false},{"label":"검색 트래픽까지 함께 중단한다","fx":{"system_design":-2},"fb":"❌ 사용자 서비스가 멈춥니다","best":false}]},{"t":"연쇄 2차: 검색 지연 상승","type":"decide","goal":"적체로 인덱스 갱신이 밀리고 검색 p99 지연이 크게 올랐습니다","sit":"다음 대응은?","opts":[{"label":"읽기 레플리카로 검색을 분리하고 캐시를 도입한다","fx":{"performance":5},"fb":"✅ 색인 부하와 검색 부하를 분리해 지연을 낮춥니다","best":true},{"label":"모든 부하를 벡터DB 단일 노드에 몰아둔다","fx":{"system_design":-2},"fb":"❌ 병목이 심해져 지연이 악화됩니다","best":false},{"label":"top_k를 크게 늘려 결과를 더 뽑는다","fx":{"performance":-2},"fb":"❌ 계산량이 늘어 더 느려집니다","best":false}]},{"t":"연쇄 3차: 벡터DB 메모리 부족","type":"decide","goal":"대용량 색인으로 벡터DB 메모리가 부족해져 노드가 다운되었습니다","sit":"어떻게 대응할까요?","opts":[{"label":"인덱스를 샤딩하고 배치 색인으로 메모리 상한을 지키며 검색은 BM25로 폴백한다","fx":{"system_design":5},"fb":"✅ 메모리를 통제하고 폴백 경로로 가용성을 유지합니다","best":true},{"label":"인덱스를 통째로 처음부터 재구축한다","fx":{"performance":-3},"fb":"❌ 오래 걸리고 그동안 검색이 끊깁니다","best":false},{"label":"임베딩 차원만 줄여서 넘긴다","fx":{"system_design":-1},"fb":"⚠️ 품질이 떨어지고 근본 문제도 남습니다","best":false}]},{"t":"원인분석과 재발방지","type":"decide","goal":"장애를 복구했고 대량 인덱싱이 검색을 무너뜨리지 않게 해야 합니다","sit":"재발방지로 무엇을 도입할까요?","opts":[{"label":"인덱싱과 검색 자원을 격리하고 백프레셔와 폴백 검색 경로를 표준화한다","fx":{"system_design":6},"fb":"✅ 적체부터 붕괴까지 전 구간을 구조적으로 방어합니다","best":true},{"label":"벡터DB 노드만 증설한다","fx":{"performance":-1},"fb":"⚠️ 자원 격리가 없어 다시 잠식됩니다","best":false},{"label":"업로드 파일 크기만 제한한다","fx":{"system_design":-2},"fb":"❌ 부하 격리 문제는 그대로입니다","best":false}]},{"t":"Postmortem 작성","type":"note","goal":"이번 RAG 장애의 <b>연쇄 사슬</b>을 정리해보세요\n임베딩 큐 적체가 어떻게 검색 지연과 벡터DB OOM으로 번졌는지와 방어 계층을 기록하세요","ph":"예: 트리거(대량 업로드), 확산(큐 적체/지연), 붕괴(벡터DB OOM), 조치(자원 격리+백프레셔+BM25 폴백), 재발방지"}]},{"lv":1,"em":"🧮","title":"통계 계산기 (CLI)","skills":["python","stat"],"kind":"guide","goal":"숫자 목록을 입력받아 평균·중앙값·표준편차 같은 기초 통계를 계산해 출력하는 커맨드라인 프로그램을 만듭니다.","steps":[{"t":"숫자 입력 파싱","goal":"사용자가 콤마나 공백으로 구분해 입력한 문자열을 실수(float) 리스트로 변환하는 함수를 만듭니다. 잘못된 값이 섞여 있으면 건너뛰거나 안내하도록 처리합니다.","hint":"str.replace, str.split, 그리고 try/except로 float() 변환 실패를 걸러내면 됩니다.","acc":"'1, 2, 3 4' 같은 혼합 구분자 입력이 [1.0, 2.0, 3.0, 4.0]으로 변환되고, 'a' 같은 잘못된 토큰은 무시되면 완료입니다.","sol":"def parse_numbers(text):\n    \"\"\"콤마/공백 혼합 입력을 float 리스트로 변환한다.\"\"\"\n    # 콤마를 공백으로 통일한 뒤 토큰 분리\n    tokens = text.replace(\",\", \" \").split()\n    numbers = []\n    for tok in tokens:\n        try:\n            numbers.append(float(tok))\n        except ValueError:\n            # 숫자가 아닌 토큰은 건너뛴다\n            print(f\"무시된 값: {tok!r}\")\n    return numbers\n\n\nif __name__ == \"__main__\":\n    raw = input(\"숫자를 입력하세요: \")\n    print(parse_numbers(raw))"},{"t":"기초 통계 계산","goal":"평균, 중앙값, 표준편차를 직접 계산하는 함수를 작성합니다. statistics 모듈에 의존하기 전에 공식을 이해하도록 구현하되, 표준편차는 표본 표준편차(n-1)를 사용합니다.","hint":"정렬 후 가운데 값으로 중앙값을 구하고, 분산은 편차 제곱의 평균으로 계산합니다. 제곱근은 math.sqrt를 씁니다.","acc":"[1,2,3,4] 입력에 대해 평균 2.5, 중앙값 2.5, 표본표준편차 약 1.29가 나오면 완료입니다.","sol":"import math\n\ndef describe(nums):\n    \"\"\"평균/중앙값/표본표준편차를 딕셔너리로 반환한다.\"\"\"\n    n = len(nums)\n    mean = sum(nums) / n\n    # 중앙값: 정렬 후 가운데 (짝수면 두 값 평균)\n    s = sorted(nums)\n    mid = n // 2\n    median = s[mid] if n % 2 else (s[mid - 1] + s[mid]) / 2\n    # 표본분산: 편차 제곱합 / (n-1)\n    variance = sum((x - mean) ** 2 for x in nums) / (n - 1) if n > 1 else 0.0\n    return {\"mean\": mean, \"median\": median, \"std\": math.sqrt(variance)}\n\n\nprint(describe([1, 2, 3, 4]))"},{"t":"예외 상황 처리","goal":"빈 리스트나 값이 하나뿐인 경우에 프로그램이 죽지 않도록 방어 로직을 추가합니다. 사용자에게 어떤 상황인지 친절히 안내하는 것이 목표입니다.","hint":"함수 시작부에서 len(nums)를 확인하고, 조건에 맞지 않으면 None을 반환하거나 안내 메시지를 출력합니다.","acc":"빈 리스트를 넘겨도 ZeroDivisionError 대신 '데이터가 없습니다' 같은 안내가 출력되면 완료입니다.","sol":"import math\n\ndef safe_describe(nums):\n    \"\"\"비어 있거나 표본이 부족한 경우를 안전하게 처리한다.\"\"\"\n    if not nums:\n        print(\"데이터가 없습니다. 숫자를 하나 이상 입력하세요.\")\n        return None\n    mean = sum(nums) / len(nums)\n    if len(nums) == 1:\n        # 표준편차는 표본이 2개 이상이어야 의미가 있다\n        print(\"값이 하나뿐이라 표준편차는 계산할 수 없습니다.\")\n        return {\"mean\": mean, \"std\": None}\n    variance = sum((x - mean) ** 2 for x in nums) / (len(nums) - 1)\n    return {\"mean\": mean, \"std\": math.sqrt(variance)}\n\n\nprint(safe_describe([]))\nprint(safe_describe([42]))"},{"t":"CLI 루프 완성","goal":"앞서 만든 함수들을 묶어, 사용자가 quit을 입력할 때까지 반복해서 통계를 계산해 주는 대화형 CLI를 완성합니다. 결과는 소수점 자릿수를 정리해 보기 좋게 출력합니다.","hint":"while True 루프 안에서 input을 받고, 'q'나 'quit'이면 break 합니다. 출력은 f-string의 :.2f 포맷을 활용하세요.","acc":"실행 후 여러 번 입력을 받아 통계를 출력하고, quit 입력 시 깔끔하게 종료되면 완료입니다.","sol":"import math\n\ndef stats(nums):\n    mean = sum(nums) / len(nums)\n    var = sum((x - mean) ** 2 for x in nums) / (len(nums) - 1) if len(nums) > 1 else 0.0\n    s = sorted(nums)\n    median = s[len(s) // 2] if len(s) % 2 else (s[len(s)//2 - 1] + s[len(s)//2]) / 2\n    return mean, median, math.sqrt(var)\n\ndef main():\n    print(\"통계 계산기 (종료: q)\")\n    while True:\n        raw = input(\"> \").strip()\n        if raw.lower() in {\"q\", \"quit\"}:\n            print(\"종료합니다.\")\n            break\n        nums = [float(t) for t in raw.replace(\",\", \" \").split()]\n        if not nums:\n            print(\"숫자를 입력하세요.\")\n            continue\n        m, md, sd = stats(nums)\n        print(f\"평균={m:.2f} 중앙값={md:.2f} 표준편차={sd:.2f}\")\n\nif __name__ == \"__main__\":\n    main()"}]},{"lv":2,"em":"📄","title":"CSV 데이터 분석기","skills":["python","pandas"],"kind":"guide","goal":"pandas로 CSV 파일을 읽어 결측치를 정리하고, 그룹별로 집계한 결과를 새로운 CSV로 저장하는 간단한 데이터 분석 파이프라인을 만듭니다.","steps":[{"t":"CSV 읽고 살펴보기","goal":"pandas로 CSV를 DataFrame으로 읽고, 데이터의 형태를 파악합니다. 행/열 개수, 컬럼별 자료형, 상위 몇 행을 확인해 데이터가 제대로 로드됐는지 검증합니다.","hint":"pd.read_csv로 불러오고 df.shape, df.dtypes, df.head(), df.info()로 구조를 확인하세요.","acc":"파일이 DataFrame으로 로드되고 shape와 각 컬럼의 dtype이 출력되면 완료입니다.","sol":"import pandas as pd\n\ndef load_csv(path):\n    \"\"\"CSV를 읽고 기본 구조를 출력한다.\"\"\"\n    df = pd.read_csv(path)\n    print(f\"행/열: {df.shape}\")\n    print(\"컬럼별 자료형:\")\n    print(df.dtypes)\n    print(\"미리보기:\")\n    print(df.head())\n    return df\n\n\nif __name__ == \"__main__\":\n    df = load_csv(\"sales.csv\")"},{"t":"결측치 확인과 처리","goal":"각 컬럼의 결측치 개수를 세고, 수치형은 중앙값으로, 범주형은 최빈값으로 채우는 정리 로직을 만듭니다. 결측이 너무 많은 컬럼은 그대로 두거나 경고를 남깁니다.","hint":"df.isna().sum()으로 결측을 세고, select_dtypes로 수치/범주형을 나눈 뒤 fillna와 median()/mode()를 사용하세요.","acc":"처리 후 df.isna().sum()이 대부분 0이 되고, 어떤 컬럼을 무엇으로 채웠는지 로그가 남으면 완료입니다.","sol":"import pandas as pd\n\ndef clean_missing(df):\n    \"\"\"수치형은 중앙값, 범주형은 최빈값으로 결측치를 채운다.\"\"\"\n    print(\"결측치 개수:\")\n    print(df.isna().sum())\n    for col in df.columns:\n        if df[col].isna().sum() == 0:\n            continue\n        if pd.api.types.is_numeric_dtype(df[col]):\n            fill = df[col].median()\n        else:\n            fill = df[col].mode().iloc[0]  # 최빈값의 첫 값\n        df[col] = df[col].fillna(fill)\n        print(f\"{col}: {fill!r} 로 채움\")\n    return df\n\n\nif __name__ == \"__main__\":\n    df = pd.read_csv(\"sales.csv\")\n    df = clean_missing(df)\n    print(df.isna().sum().sum(), \"개 결측 남음\")"},{"t":"그룹별 집계","goal":"특정 범주 컬럼을 기준으로 그룹을 나누고, 수치 컬럼의 합계·평균·건수를 한 번에 집계합니다. 결과를 보기 좋게 정렬해 상위 그룹을 파악합니다.","hint":"df.groupby('컬럼').agg({...})로 여러 통계를 동시에 구하고, sort_values로 정렬하세요.","acc":"그룹별 합계/평균/건수가 담긴 요약 테이블이 매출 합계 내림차순으로 출력되면 완료입니다.","sol":"import pandas as pd\n\ndef summarize(df, group_col=\"region\", value_col=\"amount\"):\n    \"\"\"그룹별 합계/평균/건수를 집계해 정렬한다.\"\"\"\n    summary = (\n        df.groupby(group_col)[value_col]\n        .agg(total=\"sum\", average=\"mean\", count=\"count\")\n        .reset_index()\n        .sort_values(\"total\", ascending=False)\n    )\n    # 평균은 소수 둘째 자리로 반올림\n    summary[\"average\"] = summary[\"average\"].round(2)\n    return summary\n\n\nif __name__ == \"__main__\":\n    df = pd.read_csv(\"sales.csv\")\n    print(summarize(df))"},{"t":"결과 저장 파이프라인","goal":"읽기→정리→집계 과정을 하나의 함수로 연결하고, 최종 요약을 CSV 파일로 저장합니다. 한글이 깨지지 않도록 인코딩을 지정하는 것이 실무 포인트입니다.","hint":"함수들을 순서대로 호출한 뒤 to_csv(path, index=False, encoding='utf-8-sig')로 저장하세요.","acc":"실행 시 output.csv가 생성되고, 엑셀에서 열어도 한글이 깨지지 않으면 완료입니다.","sol":"import pandas as pd\n\ndef run_pipeline(in_path, out_path, group_col=\"region\", value_col=\"amount\"):\n    \"\"\"CSV 로드 -> 결측 처리 -> 집계 -> 저장.\"\"\"\n    df = pd.read_csv(in_path)\n    # 수치 컬럼 결측은 중앙값으로 채움\n    df[value_col] = df[value_col].fillna(df[value_col].median())\n    summary = (\n        df.groupby(group_col)[value_col]\n        .agg(total=\"sum\", average=\"mean\", count=\"count\")\n        .reset_index()\n        .sort_values(\"total\", ascending=False)\n    )\n    # utf-8-sig: 엑셀에서 한글 깨짐 방지\n    summary.to_csv(out_path, index=False, encoding=\"utf-8-sig\")\n    print(f\"저장 완료: {out_path} ({len(summary)}개 그룹)\")\n    return summary\n\n\nif __name__ == \"__main__\":\n    run_pipeline(\"sales.csv\", \"output.csv\")"}]},{"lv":3,"em":"📊","title":"데이터 EDA 리포트","skills":["pandas","numpy","stat"],"kind":"guide","goal":"데이터셋을 자동으로 분석해 기초 통계, 상관관계, 이상치를 정리한 탐색적 데이터 분석(EDA) 리포트를 생성하는 도구를 만듭니다.","steps":[{"t":"기초 통계 프로파일","goal":"수치형 컬럼마다 개수·평균·표준편차·최소/최대와 왜도(skewness)를 계산해 한 테이블로 요약합니다. describe만으로는 부족한 분포 특성까지 담는 것이 목표입니다.","hint":"df.describe()를 기반으로 df.skew()를 추가로 붙이거나 concat 하세요. select_dtypes(np.number)로 수치형만 고릅니다.","acc":"각 수치 컬럼의 요약 통계와 왜도가 한 DataFrame에 나오면 완료입니다.","sol":"import numpy as np\nimport pandas as pd\n\ndef profile(df):\n    \"\"\"수치형 컬럼의 기초 통계 + 왜도를 요약한다.\"\"\"\n    num = df.select_dtypes(include=np.number)\n    desc = num.describe().T  # count, mean, std, min, 25%, 50%, 75%, max\n    desc[\"skew\"] = num.skew()          # 분포의 비대칭도\n    desc[\"missing\"] = df[num.columns].isna().sum()\n    return desc.round(3)\n\n\nif __name__ == \"__main__\":\n    df = pd.read_csv(\"data.csv\")\n    print(profile(df))"},{"t":"상관관계 분석","goal":"수치 컬럼 간 피어슨 상관계수를 계산하고, 절댓값이 큰 상위 상관 쌍을 뽑아냅니다. 자기 자신과의 상관(1.0)과 중복 쌍은 제외해야 합니다.","hint":"df.corr()로 상관행렬을 구하고, np.triu로 상삼각만 남긴 뒤 unstack해서 정렬하면 상위 쌍을 얻습니다.","acc":"상관계수 절댓값 기준 상위 몇 개의 컬럼 쌍이 값과 함께 출력되면 완료입니다.","sol":"import numpy as np\nimport pandas as pd\n\ndef top_correlations(df, k=5):\n    \"\"\"절댓값이 큰 상위 k개의 상관 쌍을 반환한다.\"\"\"\n    corr = df.select_dtypes(include=np.number).corr()\n    # 상삼각(대각선 제외)만 남겨 중복/자기상관 제거\n    mask = np.triu(np.ones(corr.shape, dtype=bool), k=1)\n    pairs = corr.where(mask).stack()\n    pairs = pairs.reindex(pairs.abs().sort_values(ascending=False).index)\n    return pairs.head(k)\n\n\nif __name__ == \"__main__\":\n    df = pd.read_csv(\"data.csv\")\n    print(top_correlations(df))"},{"t":"이상치 탐지 (IQR)","goal":"각 수치 컬럼에서 IQR(사분위 범위) 규칙으로 이상치를 탐지하고, 컬럼별 이상치 개수와 경계값을 정리합니다. 흔히 쓰는 1.5*IQR 기준을 적용합니다.","hint":"quantile(0.25), quantile(0.75)로 Q1, Q3을 구하고 lower=Q1-1.5*IQR, upper=Q3+1.5*IQR 밖의 값을 셉니다.","acc":"컬럼별 이상치 개수와 하한/상한 경계가 담긴 표가 출력되면 완료입니다.","sol":"import numpy as np\nimport pandas as pd\n\ndef detect_outliers(df):\n    \"\"\"IQR 1.5배 규칙으로 컬럼별 이상치를 집계한다.\"\"\"\n    rows = []\n    for col in df.select_dtypes(include=np.number).columns:\n        q1, q3 = df[col].quantile(0.25), df[col].quantile(0.75)\n        iqr = q3 - q1\n        lower, upper = q1 - 1.5 * iqr, q3 + 1.5 * iqr\n        n_out = ((df[col] < lower) | (df[col] > upper)).sum()\n        rows.append({\"column\": col, \"lower\": lower, \"upper\": upper,\n                     \"outliers\": int(n_out)})\n    return pd.DataFrame(rows)\n\n\nif __name__ == \"__main__\":\n    df = pd.read_csv(\"data.csv\")\n    print(detect_outliers(df))"},{"t":"리포트 조립","goal":"앞 단계 결과들을 모아 텍스트 리포트로 조립하고 파일로 저장합니다. 데이터 규모, 주요 상관, 이상치 요약을 사람이 읽기 좋은 형태로 정리하는 것이 목표입니다.","hint":"각 분석 함수의 결과를 문자열로 만들어 리스트에 모으고 '\n'.join으로 합친 뒤 open(...,'w')로 저장하세요.","acc":"실행 시 report.txt가 생성되고, 데이터 개요·상관 상위·이상치 요약 섹션이 순서대로 담기면 완료입니다.","sol":"import numpy as np\nimport pandas as pd\n\ndef build_report(df, out_path=\"report.txt\"):\n    \"\"\"EDA 결과를 텍스트 리포트로 저장한다.\"\"\"\n    lines = [\"=== EDA 리포트 ===\",\n             f\"행 {df.shape[0]}, 열 {df.shape[1]}\", \"\"]\n    num = df.select_dtypes(include=np.number)\n    lines.append(\"[기초 통계]\")\n    lines.append(num.describe().round(2).to_string())\n    # 상위 상관 쌍\n    corr = num.corr()\n    mask = np.triu(np.ones(corr.shape, dtype=bool), k=1)\n    pairs = corr.where(mask).stack().abs().sort_values(ascending=False)\n    lines += [\"\", \"[상위 상관]\", pairs.head(3).to_string()]\n    with open(out_path, \"w\", encoding=\"utf-8\") as f:\n        f.write(\"\\n\".join(lines))\n    print(f\"리포트 저장: {out_path}\")\n\n\nif __name__ == \"__main__\":\n    build_report(pd.read_csv(\"data.csv\"))"}]},{"lv":4,"em":"🤖","title":"당뇨 예측 모델","skills":["ml","mleval"],"kind":"guide","goal":"환자 건강 지표 데이터로 당뇨 발병 여부를 예측하는 이진 분류 모델을 scikit-learn으로 학습하고, 정밀도·재현율·F1로 성능을 평가합니다.","steps":[{"t":"데이터 분할","goal":"특징(X)과 정답(y)을 나누고 학습/테스트 세트로 분리합니다. 클래스 비율이 유지되도록 stratify를 적용하고, 재현성을 위해 random_state를 고정합니다.","hint":"train_test_split을 사용하고 test_size=0.2, stratify=y, random_state=42를 넘기세요.","acc":"X_train/X_test 크기가 8:2로 나뉘고, 학습·테스트 세트의 양성 비율이 비슷하면 완료입니다.","sol":"import pandas as pd\nfrom sklearn.model_selection import train_test_split\n\ndef split_data(df, target=\"Outcome\"):\n    \"\"\"특징/정답 분리 후 층화 8:2 분할.\"\"\"\n    X = df.drop(columns=[target])\n    y = df[target]\n    X_train, X_test, y_train, y_test = train_test_split(\n        X, y, test_size=0.2, stratify=y, random_state=42\n    )\n    print(\"train:\", X_train.shape, \"test:\", X_test.shape)\n    print(\"train 양성비:\", round(y_train.mean(), 3),\n          \"test 양성비:\", round(y_test.mean(), 3))\n    return X_train, X_test, y_train, y_test\n\n\nif __name__ == \"__main__\":\n    df = pd.read_csv(\"diabetes.csv\")\n    split_data(df)"},{"t":"스케일링 파이프라인","goal":"로지스틱 회귀는 특징 스케일에 민감하므로 StandardScaler로 표준화합니다. 데이터 누수를 막기 위해 스케일러는 학습 세트에만 fit 해야 한다는 점이 핵심입니다.","hint":"StandardScaler().fit_transform(X_train)과 transform(X_test)를 구분해 쓰거나, Pipeline으로 묶으세요.","acc":"학습 세트만으로 스케일러를 fit 하고, 테스트 세트는 transform만 적용했다면 완료입니다.","sol":"from sklearn.preprocessing import StandardScaler\n\ndef scale_features(X_train, X_test):\n    \"\"\"학습 세트로만 fit -> 데이터 누수 방지.\"\"\"\n    scaler = StandardScaler()\n    # fit은 train에서만! test에는 transform만 적용\n    X_train_s = scaler.fit_transform(X_train)\n    X_test_s = scaler.transform(X_test)\n    print(\"학습 세트 평균(스케일 후) ~= 0:\",\n          round(float(X_train_s.mean()), 6))\n    return X_train_s, X_test_s, scaler"},{"t":"모델 학습","goal":"로지스틱 회귀와 랜덤 포레스트를 각각 학습해 비교합니다. 두 모델을 같은 데이터로 fit 하고, 학습 정확도를 간단히 확인해 과적합 여부의 힌트를 얻습니다.","hint":"LogisticRegression(max_iter=1000)과 RandomForestClassifier(random_state=42)를 각각 fit 하세요.","acc":"두 모델이 오류 없이 학습되고 각각의 학습 정확도가 출력되면 완료입니다.","sol":"from sklearn.linear_model import LogisticRegression\nfrom sklearn.ensemble import RandomForestClassifier\n\ndef train_models(X_train, y_train):\n    \"\"\"두 분류기를 학습해 딕셔너리로 반환한다.\"\"\"\n    models = {\n        \"logreg\": LogisticRegression(max_iter=1000),\n        \"rf\": RandomForestClassifier(n_estimators=200, random_state=42),\n    }\n    for name, model in models.items():\n        model.fit(X_train, y_train)\n        acc = model.score(X_train, y_train)\n        print(f\"{name} 학습 정확도: {acc:.3f}\")\n    return models"},{"t":"성능 평가","goal":"테스트 세트로 정밀도·재현율·F1과 혼동행렬을 계산합니다. 당뇨 예측처럼 양성 놓침이 치명적인 문제에서는 재현율이 왜 중요한지 해석까지 남깁니다.","hint":"precision_score, recall_score, f1_score, confusion_matrix 또는 classification_report를 사용하세요.","acc":"각 모델의 precision/recall/f1과 혼동행렬이 출력되고, 재현율 관점의 해석이 담기면 완료입니다.","sol":"from sklearn.metrics import (precision_score, recall_score,\n                             f1_score, confusion_matrix)\n\ndef evaluate(models, X_test, y_test):\n    \"\"\"테스트 세트 기준 분류 지표를 출력한다.\"\"\"\n    for name, model in models.items():\n        pred = model.predict(X_test)\n        p = precision_score(y_test, pred)\n        r = recall_score(y_test, pred)\n        f = f1_score(y_test, pred)\n        print(f\"[{name}] precision={p:.3f} recall={r:.3f} f1={f:.3f}\")\n        print(\"혼동행렬:\\n\", confusion_matrix(y_test, pred))\n    # 재현율이 낮으면 실제 당뇨 환자를 놓치는 것이므로 의료 문제에서 특히 중요\n    print(\"의료 예측에서는 재현율(놓친 환자 최소화)을 우선 고려한다.\")"}]},{"lv":5,"em":"🚀","title":"ML 추론 API 설계","skills":["python","sql"],"kind":"guide","goal":"학습된 ML 모델을 FastAPI로 감싸 실시간 예측 API를 만들고, 요청 검증과 예측 로그의 DB 저장까지 포함한 프로덕션 수준의 추론 서비스를 설계합니다.","steps":[{"t":"모델 로딩 & 추론 함수","goal":"학습 때 저장한 모델 아티팩트를 서버 기동 시 한 번만 로드하고, 입력 특징 리스트를 받아 예측 확률을 돌려주는 순수 함수를 만듭니다. 매 요청마다 모델을 다시 읽지 않는 것이 성능의 핵심입니다.","hint":"joblib.load로 모델을 모듈 전역에 한 번 로드하고, predict_proba로 양성 확률을 반환하세요.","acc":"모델이 프로세스 시작 시 1회 로드되고, 특징 배열 입력에 대해 0~1 확률이 반환되면 완료입니다.","sol":"import joblib\nimport numpy as np\n\n# 설계 노트: 모델은 임포트 시점에 1회만 로드 -> 요청마다 재로딩 금지\nMODEL = joblib.load(\"model.joblib\")  # scaler+classifier 파이프라인 가정\n\ndef predict_one(features: list[float]) -> dict:\n    \"\"\"특징 리스트 -> 양성 확률과 라벨.\"\"\"\n    x = np.asarray(features, dtype=float).reshape(1, -1)\n    proba = float(MODEL.predict_proba(x)[0, 1])  # 양성 클래스 확률\n    return {\"probability\": round(proba, 4),\n            \"label\": int(proba >= 0.5)}\n\n\nif __name__ == \"__main__\":\n    print(predict_one([6, 148, 72, 35, 0, 33.6, 0.627, 50]))"},{"t":"요청 스키마 & 검증","goal":"Pydantic 모델로 입력 스키마를 정의해 특징 개수와 타입을 자동 검증합니다. 잘못된 요청은 API 코드에 도달하기 전에 422로 거절되도록 설계하는 것이 목표입니다.","hint":"BaseModel을 상속하고 features: list[float]에 Field(min_length=8, max_length=8) 같은 제약을 겁니다.","acc":"특징이 8개가 아닌 요청이 자동으로 검증 오류를 내고, 올바른 요청만 통과하면 완료입니다.","sol":"from pydantic import BaseModel, Field\n\nclass PredictRequest(BaseModel):\n    \"\"\"입력 검증: 정확히 8개의 수치 특징을 요구.\"\"\"\n    features: list[float] = Field(..., min_length=8, max_length=8)\n\nclass PredictResponse(BaseModel):\n    probability: float\n    label: int\n\n\nif __name__ == \"__main__\":\n    # 유효한 요청은 통과\n    ok = PredictRequest(features=[6, 148, 72, 35, 0, 33.6, 0.627, 50])\n    print(\"검증 통과:\", ok.features)\n    # 개수가 틀리면 ValidationError 발생\n    try:\n        PredictRequest(features=[1, 2, 3])\n    except Exception as e:\n        print(\"검증 실패(의도된 동작):\", type(e).__name__)"},{"t":"예측 로그 DB 저장","goal":"모든 예측 요청과 결과를 SQLite 테이블에 기록해 나중에 모니터링·재학습에 활용합니다. 입력 특징, 예측 확률, 타임스탬프를 저장하는 스키마와 삽입 함수를 만듭니다.","hint":"sqlite3로 CREATE TABLE IF NOT EXISTS 하고, INSERT는 파라미터 바인딩(?)으로 SQL 인젝션을 예방하세요.","acc":"예측이 일어날 때마다 한 행이 추가되고, 테이블에서 최근 로그를 조회할 수 있으면 완료입니다.","sol":"import json\nimport sqlite3\nfrom datetime import datetime\n\ndef init_db(path=\"logs.db\"):\n    conn = sqlite3.connect(path)\n    conn.execute(\"\"\"\n        CREATE TABLE IF NOT EXISTS predictions (\n            id        INTEGER PRIMARY KEY AUTOINCREMENT,\n            features  TEXT NOT NULL,\n            probability REAL NOT NULL,\n            created_at TEXT NOT NULL\n        )\"\"\")\n    conn.commit()\n    return conn\n\ndef log_prediction(conn, features, probability):\n    \"\"\"파라미터 바인딩(?)으로 인젝션 없이 저장.\"\"\"\n    conn.execute(\n        \"INSERT INTO predictions (features, probability, created_at) VALUES (?, ?, ?)\",\n        (json.dumps(features), probability, datetime.utcnow().isoformat()),\n    )\n    conn.commit()\n\n\nif __name__ == \"__main__\":\n    conn = init_db()\n    log_prediction(conn, [6, 148, 72], 0.83)\n    print(list(conn.execute(\"SELECT * FROM predictions ORDER BY id DESC LIMIT 3\")))"},{"t":"FastAPI 엔드포인트 통합","goal":"앞 단계들을 묶어 POST /predict 엔드포인트를 완성합니다. 요청 검증→추론→로그 저장→응답 반환 흐름을 연결하고, 헬스체크 엔드포인트까지 두어 배포 준비를 마칩니다.","hint":"FastAPI 인스턴스에 @app.post('/predict')를 붙이고, 요청 바디를 PredictRequest로 받아 예측 후 응답 모델로 반환하세요. uvicorn으로 실행합니다.","acc":"uvicorn 실행 후 /predict에 올바른 JSON을 보내면 확률/라벨이 오고, 잘못된 입력은 422를 반환하며, /health가 200을 주면 완료입니다.","sol":"from fastapi import FastAPI\nfrom pydantic import BaseModel, Field\nimport joblib, numpy as np\n\napp = FastAPI(title=\"Diabetes Inference API\")\nMODEL = joblib.load(\"model.joblib\")  # 기동 시 1회 로드\n\nclass PredictRequest(BaseModel):\n    features: list[float] = Field(..., min_length=8, max_length=8)\n\nclass PredictResponse(BaseModel):\n    probability: float\n    label: int\n\n@app.get(\"/health\")   # 배포 모니터링용 헬스체크\ndef health():\n    return {\"status\": \"ok\"}\n\n@app.post(\"/predict\", response_model=PredictResponse)\ndef predict(req: PredictRequest):\n    x = np.asarray(req.features).reshape(1, -1)\n    proba = float(MODEL.predict_proba(x)[0, 1])\n    return PredictResponse(probability=round(proba, 4), label=int(proba >= 0.5))\n\n# 실행: uvicorn main:app --reload"}]}],"backend":[{"lv":1,"em":"🔗","title":"URL 단축기 서비스","desc":"긴 URL을 짧은 코드로 변환하고 리다이렉트하는 서비스를 처음부터 만들어봅니다.","skills":["python","backend"],"phases":[{"t":"요구사항 정의","type":"note","goal":"이 서비스의 <b>핵심 요구사항</b>과 비기능 요구사항을 적어보세요. 긴 URL을 짧은 코드로 바꾸고, 코드로 접속하면 원본으로 리다이렉트합니다.\n예상 트래픽, 코드 길이, 만료 정책을 정의하세요.","ph":"예: 하루 10만 건 생성, 코드 7자 이내, 조회는 쓰기의 100배, 만료 없음..."},{"t":"설계 결정","type":"decide","goal":"단축 코드를 어떻게 생성할지 결정해야 합니다. 짧고 충돌이 적어야 하며 대량 생성에도 견뎌야 합니다.","sit":"단축 코드 생성 전략으로 무엇을 선택하시겠습니까?","opts":[{"label":"자동 증가 ID를 Base62로 인코딩","fx":{"system_design":5,"database":4},"fb":"✅ 순차 ID라 충돌이 없고 코드가 짧으며 디코딩만으로 원본을 찾을 수 있어 대량 생성에 가장 안정적입니다.","best":true},{"label":"매번 랜덤 6자리 문자열을 생성","fx":{"performance":1},"fb":"⚠️ 구현은 쉽지만 데이터가 쌓이면 충돌 확률이 올라가 재시도 비용이 커집니다.","best":false},{"label":"원본 URL을 해시해 앞 8자를 사용","fx":{"database":-2,"security":-1},"fb":"❌ 같은 URL이 같은 코드가 되고 해시 앞자리 충돌 위험이 있으며 만료·소유자 관리가 어렵습니다.","best":false}]},{"t":"개발","type":"build","goal":"정수 ID를 짧은 코드로 바꾸는 Base62 인코더와 디코더를 구현하세요.","hint":"숫자를 62진법으로 바꾸며 나머지를 문자표에 매핑하면 됩니다.","acc":"encode와 decode가 서로 역함수로 동작해 같은 값이 왕복 변환된다.","sol":"import string\n\nALPHABET = string.digits + string.ascii_letters  # 62 chars\n\ndef encode(num):\n    if num == 0:\n        return ALPHABET[0]\n    base = len(ALPHABET)\n    chars = []\n    while num > 0:\n        num, rem = divmod(num, base)\n        chars.append(ALPHABET[rem])\n    return ''.join(reversed(chars))\n\ndef decode(code):\n    base = len(ALPHABET)\n    num = 0\n    for ch in code:\n        num = num * base + ALPHABET.index(ch)\n    return num","lang":"python"},{"t":"개발","type":"build","goal":"URL을 단축하는 엔드포인트와 코드로 원본에 리다이렉트하는 엔드포인트를 구현하세요.","hint":"카운터를 증가시켜 코드를 만들고, 조회 시 없으면 404를 반환하세요.","acc":"단축 코드를 받고 그 코드로 접속하면 원본으로 302 리다이렉트된다.","sol":"from flask import Flask, request, redirect, jsonify\n\napp = Flask(__name__)\nstore = {}\ncounter = {'n': 0}\n\n@app.post('/shorten')\ndef shorten():\n    url = request.json['url']\n    counter['n'] += 1\n    code = encode(counter['n'])\n    store[code] = url\n    return jsonify({'code': code, 'short': '/' + code})\n\n@app.get('/<code>')\ndef go(code):\n    url = store.get(code)\n    if not url:\n        return jsonify({'error': 'not found'}), 404\n    return redirect(url, code=302)","lang":"python"},{"t":"테스트","type":"note","goal":"작성한 API의 <b>테스트 시나리오</b>를 정리하세요. 정상 단축·리다이렉트, 존재하지 않는 코드 404, 잘못된 URL 형식 검증, 같은 URL 재요청 동작을 포함하세요.","ph":"예: 정상 단축 → 302 / 없는 코드 → 404 / 빈 url → 400..."},{"t":"장애 대응","type":"decide","goal":"랜덤 코드 방식으로 급하게 배포했더니, 서로 다른 두 URL이 같은 코드로 저장돼 <b>기존 링크가 다른 사이트로 연결</b>되는 사고가 발생했습니다.","sit":"코드 충돌 사고에 어떻게 대응하시겠습니까?","opts":[{"label":"코드 컬럼에 유일 제약을 걸고 충돌 시 코드를 재생성","fx":{"database":5,"system_design":4},"fb":"✅ DB가 유일성을 보장하므로 애플리케이션 버그와 무관하게 덮어쓰기 사고를 원천 차단합니다.","best":true},{"label":"코드 길이를 6자에서 8자로 늘려 충돌 확률만 낮춤","fx":{"performance":1},"fb":"⚠️ 확률은 줄지만 근본적으로 충돌 가능성이 남아 언젠가 같은 사고가 재발합니다.","best":false},{"label":"충돌이 드무니 그냥 나중 값으로 덮어쓰기 허용","fx":{"database":-3,"communication":-1},"fb":"❌ 이미 배포된 링크가 조용히 깨져 사용자 신뢰를 잃는 최악의 선택입니다.","best":false}]},{"t":"장애 연쇄","type":"decide","goal":"유일 제약과 충돌 시 재생성을 넣었더니, 트래픽이 몰리는 시간대에 <b>충돌과 재시도가 반복</b>되며 생성 API 응답이 급격히 느려졌습니다.","sit":"재시도 폭주로 인한 지연에 어떻게 대응하시겠습니까?","opts":[{"label":"자동 증가 ID와 Base62로 전환하고 재시도 상한과 백오프를 둠","fx":{"system_design":5,"performance":4},"fb":"✅ 충돌 자체를 없애 재시도 루프를 제거하고, 남은 예외에는 상한을 둬 폭주를 막습니다.","best":true},{"label":"재시도 횟수 제한 없이 성공할 때까지 반복","fx":{"performance":-3},"fb":"❌ 부하가 높을수록 재시도가 재시도를 부르며 응답 지연이 눈덩이처럼 커집니다.","best":false},{"label":"충돌이 나면 즉시 500 에러로 실패 처리","fx":{"communication":-2,"system_design":-1},"fb":"⚠️ 폭주는 막지만 정상 요청까지 실패해 사용자 경험이 나빠집니다.","best":false}]},{"t":"장애 연쇄","type":"decide","goal":"생성은 안정됐지만, 특정 단축 링크가 SNS에서 <b>바이럴</b>되며 초당 수천 건 조회가 몰려 DB 읽기 부하로 전체 리다이렉트가 느려졌습니다.","sit":"인기 링크 조회 폭주에 어떻게 대응하시겠습니까?","opts":[{"label":"코드에서 원본으로의 매핑을 캐시에 저장하고 짧은 TTL로 서빙","fx":{"performance":5,"system_design":4},"fb":"✅ 읽기 대부분을 캐시가 흡수해 DB 부하를 없애고 리다이렉트 지연을 즉시 해소합니다.","best":true},{"label":"DB 인스턴스 사양만 수직 확장","fx":{"performance":1},"fb":"⚠️ 일시적으로 버티지만 비용이 크고 다음 바이럴에 또 한계에 부딪힙니다.","best":false},{"label":"조회는 원래 빠르니 별도 조치를 하지 않음","fx":{"performance":-3},"fb":"❌ 핫키 부하를 방치해 인기 링크일수록 더 느려지는 악순환을 방치합니다.","best":false}]},{"t":"Postmortem","type":"note","goal":"이번 <b>장애 연쇄</b>(코드 충돌, 재시도 폭주, 핫키 조회 폭주)를 돌아보며 타임라인, 근본 원인, 재발 방지책을 정리하세요.\n왜 랜덤 코드 선택이 연쇄의 시작이었는지 적어보세요.","ph":"타임라인: 14:00 충돌 발생 / 근본 원인: ... / 재발 방지: 순차 ID, 캐시, 재시도 상한..."}]},{"lv":2,"em":"📝","title":"게시판 REST API","desc":"게시글과 댓글을 다루는 REST API를 설계하고 효율적인 목록 조회까지 구현합니다.","skills":["python","backend","sql"],"phases":[{"t":"요구사항 정의","type":"note","goal":"게시판 API의 <b>기능 요구사항</b>을 적어보세요. 글 작성·조회·목록, 댓글, 최신순 정렬이 필요합니다.\n리소스 설계(URL, 메서드)와 응답 형식, 목록 조회량을 정의하세요.","ph":"예: 목록 조회, 글 작성, 목록은 페이지당 20건 최신순, 댓글 수 함께 표시..."},{"t":"설계 결정","type":"decide","goal":"게시판 목록은 최신순으로 자주 조회됩니다. 데이터가 많아져도 빠른 페이지네이션 방식을 정해야 합니다.","sit":"목록 페이지네이션 방식을 무엇으로 하시겠습니까?","opts":[{"label":"created_at, id 기준 커서(키셋) 페이지네이션","fx":{"database":5,"performance":4},"fb":"✅ 인덱스를 그대로 타고 뒤쪽 페이지에서도 일정한 성능을 내 대량 데이터에 가장 적합합니다.","best":true},{"label":"건너뛰기와 개수 기반 오프셋 페이지네이션","fx":{"performance":-1},"fb":"⚠️ 구현은 쉽지만 뒤 페이지로 갈수록 건너뛰는 행이 많아져 점점 느려집니다.","best":false},{"label":"전체를 메모리에 올려 애플리케이션에서 잘라 반환","fx":{"performance":-3,"database":-2},"fb":"❌ 데이터가 커지면 메모리와 조회 비용이 폭발하는 최악의 방식입니다.","best":false}]},{"t":"개발","type":"build","goal":"게시글과 댓글 테이블을 설계하고 최신순 조회에 맞는 인덱스를 만드세요.","hint":"정렬 컬럼과 동점 처리용 id를 함께 인덱스에 포함하면 커서 페이지네이션이 빨라집니다.","acc":"posts와 comments 테이블, 그리고 created_at 내림차순 복합 인덱스가 생성된다.","sol":"CREATE TABLE posts (\n    id BIGINT PRIMARY KEY AUTO_INCREMENT,\n    title VARCHAR(200) NOT NULL,\n    content TEXT NOT NULL,\n    author_id BIGINT NOT NULL,\n    view_count INT NOT NULL DEFAULT 0,\n    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX idx_posts_created ON posts (created_at DESC, id DESC);\n\nCREATE TABLE comments (\n    id BIGINT PRIMARY KEY AUTO_INCREMENT,\n    post_id BIGINT NOT NULL,\n    content TEXT NOT NULL,\n    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (post_id) REFERENCES posts (id)\n);","lang":"sql"},{"t":"개발","type":"build","goal":"게시글 생성과 단건 조회 REST 엔드포인트를 구현하세요.","hint":"파라미터 바인딩(물음표 플레이스홀더)으로 SQL 인젝션을 막으세요.","acc":"글을 생성하면 id가 반환되고, 그 id로 조회하면 JSON이, 없으면 404가 반환된다.","sol":"from flask import Flask, request, jsonify\nimport sqlite3\n\napp = Flask(__name__)\n\ndef db():\n    conn = sqlite3.connect('board.db')\n    conn.row_factory = sqlite3.Row\n    return conn\n\n@app.post('/posts')\ndef create_post():\n    data = request.json\n    conn = db()\n    cur = conn.execute(\n        'INSERT INTO posts(title, content, author_id) VALUES (?, ?, ?)',\n        (data['title'], data['content'], data['author_id']))\n    conn.commit()\n    return jsonify({'id': cur.lastrowid}), 201\n\n@app.get('/posts/<int:pid>')\ndef get_post(pid):\n    row = db().execute('SELECT * FROM posts WHERE id = ?', (pid,)).fetchone()\n    if row is None:\n        return jsonify({'error': 'not found'}), 404\n    return jsonify(dict(row))","lang":"python"},{"t":"개발","type":"build","goal":"커서 기반으로 게시글 목록과 각 글의 댓글 수를 함께 조회하는 쿼리를 작성하세요.","hint":"마지막으로 본 created_at, id 튜플을 커서로 받아 그 이전 행만 가져오세요.","acc":"20건씩 최신순으로 반환되며, 마지막 행의 커서를 넘기면 이어서 조회된다.","sol":"-- 커서 기반 페이지네이션: 마지막으로 본 created_at, id 이후 20건\nSELECT p.id, p.title, p.author_id, p.created_at,\n       COUNT(c.id) AS comment_count\nFROM posts p\nLEFT JOIN comments c ON c.post_id = p.id\nWHERE (p.created_at, p.id) < (:last_created_at, :last_id)\nGROUP BY p.id, p.title, p.author_id, p.created_at\nORDER BY p.created_at DESC, p.id DESC\nLIMIT 20;","lang":"sql"},{"t":"테스트","type":"note","goal":"작성한 API의 <b>테스트 시나리오</b>를 정리하세요. 정상 생성·조회, 빈 제목 검증, 존재하지 않는 글 404, 페이지네이션 경계(첫 페이지와 마지막 페이지)를 포함하세요.","ph":"예: 제목 없이 작성 → 400 / 없는 글 조회 → 404 / 커서 끝 → 빈 배열..."},{"t":"장애 대응","type":"decide","goal":"출시 후 목록 화면이 느리다는 제보가 왔습니다. 프로파일링해보니 글 20개를 불러오며 <b>각 글마다 댓글 수를 개별 쿼리</b>로 조회하는 N+1 문제가 있었습니다.","sit":"N+1 쿼리 문제를 어떻게 해결하시겠습니까?","opts":[{"label":"JOIN과 GROUP BY로 댓글 수를 한 번에 집계","fx":{"database":5,"performance":4},"fb":"✅ 목록 조회를 단일 쿼리로 줄여 DB 왕복 횟수를 없애는 정석 해결책입니다.","best":true},{"label":"댓글 수를 매 요청 실시간 집계하되 캐시는 쓰지 않음","fx":{"performance":-1},"fb":"⚠️ 여전히 매 요청 집계 부하가 남아 트래픽이 늘면 다시 느려집니다.","best":false},{"label":"글마다 개별 쿼리를 유지하되 커넥션 풀만 키움","fx":{"database":-2,"performance":-2},"fb":"❌ 근본 원인은 그대로 두고 DB 부하만 키워 상황을 악화시킵니다.","best":false}]},{"t":"장애 연쇄","type":"decide","goal":"JOIN으로 바꿨지만 여전히 느립니다. 실행 계획을 보니 정렬에 쓰는 컬럼에 <b>인덱스가 없어 풀 테이블 스캔</b>이 일어나며 DB CPU가 90퍼센트를 넘겼습니다.","sit":"정렬 풀스캔으로 인한 DB CPU 폭주에 어떻게 대응하시겠습니까?","opts":[{"label":"정렬과 필터 컬럼에 맞는 복합 인덱스를 추가","fx":{"database":5,"performance":4},"fb":"✅ 인덱스로 정렬을 대체해 스캔 범위를 줄이고 CPU 사용률을 정상으로 되돌립니다.","best":true},{"label":"읽기 레플리카를 늘려 부하 분산만 함","fx":{"performance":1},"fb":"⚠️ 급한 불은 끄지만 비효율 쿼리가 그대로라 레플리카도 함께 느려집니다.","best":false},{"label":"애플리케이션에서 정렬하도록 전량을 조회","fx":{"performance":-3,"database":-2},"fb":"❌ 더 많은 데이터를 퍼올려 DB와 앱 양쪽 부하를 키우는 최악입니다.","best":false}]},{"t":"장애 연쇄","type":"decide","goal":"느린 쿼리들이 오래 실행되며 커넥션을 붙잡아, 결국 <b>커넥션 풀이 고갈</b>되고 신규 요청이 커넥션을 얻지 못해 5xx가 쏟아졌습니다.","sit":"커넥션 풀 고갈로 인한 5xx 폭증에 어떻게 대응하시겠습니까?","opts":[{"label":"쿼리 타임아웃과 풀 대기 상한을 설정하고 느린 쿼리를 격리","fx":{"system_design":5,"performance":4},"fb":"✅ 느린 쿼리가 풀을 독점하지 못하게 막고 빠르게 실패시켜 전체 장애 확산을 끊습니다.","best":true},{"label":"커넥션 풀 최대치를 무한에 가깝게 늘림","fx":{"database":-2,"performance":-1},"fb":"❌ DB가 감당 못 할 커넥션이 몰려 오히려 DB 자체가 다운될 위험이 커집니다.","best":false},{"label":"서버를 재시작해 커넥션을 초기화","fx":{"communication":-1},"fb":"⚠️ 잠깐 회복되지만 근본 원인이 남아 몇 분 뒤 같은 고갈이 반복됩니다.","best":false}]},{"t":"Postmortem","type":"note","goal":"N+1, 인덱스 부재로 인한 풀스캔, 커넥션 풀 고갈로 이어진 <b>장애 연쇄</b>를 정리하세요.\n각 단계가 어떻게 다음을 촉발했는지, 배포 전 어떤 점검(실행 계획 리뷰, 부하 테스트)으로 막을 수 있었는지 적어보세요.","ph":"타임라인 / 근본 원인: 인덱스·쿼리 리뷰 누락 / 재발 방지: 실행 계획 리뷰 의무화, 슬로우 쿼리 알람..."}]},{"lv":3,"em":"🛒","title":"쇼핑몰 주문·결제 시스템","desc":"중복 없는 주문과 안전한 결제를 보장하는 커머스 백엔드를 만들고 장애에 대응합니다.","skills":["backend","sql","security"],"phases":[{"t":"요구사항 정의","type":"note","goal":"주문·결제 시스템의 <b>핵심 요구사항</b>을 적어보세요. 재시도나 중복 클릭에도 <b>한 번만</b> 주문·결제돼야 합니다.\n주문 상태 흐름, 결제 실패 처리, 멱등성 요구를 정의하세요.","ph":"예: 주문 상태 대기→결제완료→배송, 결제 실패 시 주문 실패 처리, 멱등성 키 필수..."},{"t":"설계 결정","type":"decide","goal":"결제는 네트워크 재시도나 중복 클릭으로 같은 주문이 두 번 처리될 수 있습니다. 안전한 주문·결제 흐름을 설계해야 합니다.","sit":"주문 중복 생성을 막기 위한 설계로 무엇을 선택하시겠습니까?","opts":[{"label":"클라이언트가 보낸 멱등성 키를 유일 제약으로 저장해 중복 요청을 흡수","fx":{"system_design":5,"security":4},"fb":"✅ 재시도가 와도 같은 키면 같은 결과를 돌려주어 중복 주문과 중복 결제를 근본적으로 막습니다.","best":true},{"label":"제출 버튼을 프론트에서 비활성화해 중복 클릭만 방지","fx":{"security":-1},"fb":"⚠️ 화면상 중복은 줄지만 네트워크 재시도나 API 직접 호출에는 무력합니다.","best":false},{"label":"주문 생성 후 목록을 조회해 중복이면 삭제","fx":{"database":-2,"security":-2},"fb":"❌ 경쟁 조건에서 중복을 놓치기 쉽고 이미 결제된 건을 지우면 정합성이 깨집니다.","best":false}]},{"t":"개발","type":"build","goal":"주문과 결제 테이블을 설계하고 멱등성 키에 유일 제약을 거세요.","hint":"멱등성 키 컬럼에 유일 제약을 두면 DB가 중복 주문을 거절합니다.","acc":"orders와 payments 테이블, 그리고 멱등성 키 유일 제약이 생성된다.","sol":"CREATE TABLE orders (\n    id BIGINT PRIMARY KEY AUTO_INCREMENT,\n    user_id BIGINT NOT NULL,\n    status VARCHAR(20) NOT NULL DEFAULT 'PENDING',\n    total_amount INT NOT NULL,\n    idempotency_key VARCHAR(64) NOT NULL,\n    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    UNIQUE KEY uk_idem (idempotency_key)\n);\n\nCREATE TABLE payments (\n    id BIGINT PRIMARY KEY AUTO_INCREMENT,\n    order_id BIGINT NOT NULL,\n    status VARCHAR(20) NOT NULL,\n    pg_tid VARCHAR(64),\n    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (order_id) REFERENCES orders (id)\n);","lang":"sql"},{"t":"개발","type":"build","goal":"멱등성 키를 검사해 중복이면 기존 주문을 반환하고, 아니면 새 주문을 생성하는 API를 구현하세요.","hint":"먼저 키로 조회하고 없을 때만 삽입하되, 트랜잭션과 유일 제약으로 경쟁을 방어하세요.","acc":"같은 멱등성 키로 두 번 호출해도 주문이 하나만 생성된다.","sol":"from flask import Flask, request, jsonify\nimport pymysql\n\napp = Flask(__name__)\n\n@app.post('/orders')\ndef create_order():\n    data = request.json\n    idem = request.headers.get('Idempotency-Key')\n    if not idem:\n        return jsonify({'error': 'missing idempotency key'}), 400\n    conn = pymysql.connect(db='shop', autocommit=False)\n    try:\n        with conn.cursor() as cur:\n            cur.execute('SELECT id FROM orders WHERE idempotency_key=%s', (idem,))\n            row = cur.fetchone()\n            if row:\n                return jsonify({'order_id': row[0], 'reused': True})\n            cur.execute(\n                'INSERT INTO orders(user_id,total_amount,idempotency_key) '\n                'VALUES(%s,%s,%s)',\n                (data['user_id'], data['amount'], idem))\n            conn.commit()\n            return jsonify({'order_id': cur.lastrowid}), 201\n    except Exception:\n        conn.rollback()\n        raise","lang":"python"},{"t":"개발","type":"build","goal":"결제 처리에 분산 락과 결과 캐싱을 적용해 동시 중복 결제를 막으세요.","hint":"SET NX로 락을 잡고, 이미 처리된 키는 캐시된 결과를 반환하세요.","acc":"동일 키로 동시에 결제를 호출해도 실제 승인은 한 번만 일어난다.","sol":"import redis, json\n\nr = redis.Redis()\n\ndef process_payment(order_id, idem_key, amount, pg_client):\n    lock_key = 'pay:lock:' + idem_key\n    # SET NX로 동시 중복 결제 방지, 30초 TTL\n    if not r.set(lock_key, '1', nx=True, ex=30):\n        return {'status': 'IN_PROGRESS'}\n    cached = r.get('pay:result:' + idem_key)\n    if cached:\n        return json.loads(cached)\n    try:\n        tid = pg_client.charge(order_id, amount)\n        result = {'status': 'PAID', 'pg_tid': tid}\n        r.set('pay:result:' + idem_key, json.dumps(result), ex=3600)\n        return result\n    finally:\n        r.delete(lock_key)","lang":"python"},{"t":"테스트","type":"note","goal":"결제 흐름의 <b>테스트 시나리오</b>를 정리하세요. 정상 결제, 같은 멱등키 재시도, 동시 중복 요청, 결제 실패 시 주문 상태 처리, 락 만료 상황을 포함하세요.","ph":"예: 같은 키 2회 → 주문 1건 / 동시 결제 → 승인 1회 / 결제 실패 → 주문 실패..."},{"t":"장애 대응","type":"decide","goal":"대규모 세일이 시작되자 외부 <b>PG 결제 API 응답이 지연</b>되기 시작했습니다. 결제 요청들이 응답을 기다리며 애플리케이션 스레드를 점점 오래 점유합니다.","sit":"외부 결제 API 지연에 어떻게 대응하시겠습니까?","opts":[{"label":"결제 호출에 타임아웃과 서킷 브레이커를 적용","fx":{"system_design":5,"performance":4},"fb":"✅ 느린 외부 의존성을 빠르게 끊어내 스레드 고갈과 장애 전파를 막는 핵심 방어입니다.","best":true},{"label":"타임아웃 없이 응답을 끝까지 기다림","fx":{"performance":-3},"fb":"❌ 느린 결제 하나가 스레드를 계속 잡아 서버 전체가 함께 멈추는 원인이 됩니다.","best":false},{"label":"실패한 결제를 즉시 무한 재시도","fx":{"performance":-2,"system_design":-1},"fb":"⚠️ 이미 힘든 PG에 요청을 더 퍼부어 지연을 오히려 악화시킵니다.","best":false}]},{"t":"장애 연쇄","type":"decide","goal":"결제 지연으로 트래픽이 몰리자 세션과 재고 캐시로 쓰던 <b>Redis가 메모리 초과로 다운</b>됐습니다. 모든 조회가 DB로 몰리며 커넥션이 폭증하고 Lock 대기가 쌓입니다.","sit":"캐시 다운으로 인한 DB 커넥션 폭주와 Lock 경합에 어떻게 대응하시겠습니까?","opts":[{"label":"DB 커넥션 풀 상한과 쿼리 타임아웃을 두고 캐시 미스에 부하 차단을 적용","fx":{"system_design":5,"database":4},"fb":"✅ 캐시가 죽어도 DB로 가는 부하를 상한으로 막아 커넥션 폭주와 Lock 연쇄를 끊습니다.","best":true},{"label":"모든 요청을 DB로 그대로 흘려보냄","fx":{"database":-3,"performance":-1},"fb":"❌ 캐시가 흡수하던 부하가 통째로 DB를 덮쳐 DB까지 다운시키는 최악입니다.","best":false},{"label":"Redis를 재시작만 하고 앱은 그대로 둠","fx":{"system_design":-1},"fb":"⚠️ 재시작 사이에도 부하가 계속 DB로 몰려 캐시가 다시 뜨기 전에 DB가 무너질 수 있습니다.","best":false}]},{"t":"장애 연쇄","type":"decide","goal":"DB Lock 대기와 타임아웃으로 주문 API가 실패하자 클라이언트들이 재시도했고, 일부 경로에서 <b>같은 결제가 두 개의 주문</b>으로 기록되는 중복이 발생했습니다.","sit":"장애 중 발생한 주문 중복 생성에 어떻게 대응하시겠습니까?","opts":[{"label":"멱등성 키로 중복 주문을 탐지·병합하고 미승인 중복은 취소 처리","fx":{"database":5,"security":4},"fb":"✅ 이미 설계한 멱등 키를 근거로 중복을 안전하게 정리해 고객 이중 청구를 막습니다.","best":true},{"label":"중복으로 보이는 최신 주문을 무조건 삭제","fx":{"database":-2,"communication":-1},"fb":"❌ 판단 없이 지우면 정상 주문까지 날아가 정합성과 신뢰를 함께 잃습니다.","best":false},{"label":"고객이 문의하면 그때 수동으로 환불","fx":{"communication":-2},"fb":"⚠️ 대응이 늦어 컴플레인이 폭증하고 브랜드 신뢰가 크게 훼손됩니다.","best":false}]},{"t":"장애 연쇄","type":"decide","goal":"이중 청구를 인지한 고객들의 <b>문의가 폭주</b>합니다. CS팀과 함께 신속한 보상과 커뮤니케이션이 필요합니다.","sit":"고객 컴플레인과 보상을 어떻게 처리하시겠습니까?","opts":[{"label":"영향받은 주문을 자동 식별해 선제적으로 환불·안내하고 상태 페이지를 갱신","fx":{"communication":5,"leadership":4},"fb":"✅ 고객이 문의하기 전에 먼저 바로잡고 투명하게 알려 신뢰 손상을 최소화합니다.","best":true},{"label":"문의한 고객에게만 개별적으로 환불","fx":{"communication":-1},"fb":"⚠️ 문의하지 않은 피해자가 방치돼 뒤늦게 더 큰 불만으로 번집니다.","best":false},{"label":"내부 조사가 끝날 때까지 공지 없이 침묵","fx":{"communication":-3,"leadership":-2},"fb":"❌ 침묵은 불안과 추측을 키워 사고보다 대응 자체가 더 큰 비난을 부릅니다.","best":false}]},{"t":"Postmortem","type":"note","goal":"결제 API 지연, Redis 다운, DB 커넥션 폭주와 Lock, 주문 중복, 고객 컴플레인으로 번진 <b>장애 연쇄</b>를 정리하세요.\n각 방어선(타임아웃, 서킷 브레이커, 부하 차단, 멱등성)이 어디서 뚫렸는지와 재발 방지책을 적어보세요.","ph":"타임라인 / 근본 원인: 외부 의존성 격리 부재 / 재발 방지: 서킷 브레이커, 캐시 장애 대비 부하 차단, 멱등 강제..."}]},{"lv":4,"em":"🎟️","title":"콘서트 예매 시스템","desc":"오픈런 트래픽 속에서 초과 판매 없이 좌석을 파는 동시성 시스템을 설계합니다.","skills":["backend","sql","system_design"],"phases":[{"t":"요구사항 정의","type":"note","goal":"콘서트 예매의 <b>동시성 요구사항</b>을 적어보세요. 오픈 순간 수만 명이 같은 좌석을 노리며, <b>초과 판매는 절대 없어야</b> 합니다.\n피크 동시 요청, 좌석 홀드 시간, 대기열 정책을 정의하세요.","ph":"예: 오픈 직후 초당 3만 요청, 좌석 홀드 5분, 대기열 순번제, 초과 판매 0..."},{"t":"설계 결정","type":"decide","goal":"티켓 오픈 순간 수만 명이 동시에 같은 좌석을 노립니다. <b>초과 판매 없이</b> 정확히 재고만큼만 팔 동시성 제어 방식을 정해야 합니다.","sit":"좌석 재고 동시성 제어 방식을 무엇으로 하시겠습니까?","opts":[{"label":"남은 재고가 0보다 클 때만 차감하는 원자적 조건부 갱신","fx":{"database":5,"system_design":4},"fb":"✅ 단일 원자 연산으로 재고를 차감해 별도 락 없이도 초과 판매를 막는 가장 견고한 방식입니다.","best":true},{"label":"조회한 뒤 애플리케이션에서 재고를 확인하고 차감","fx":{"database":-2,"performance":-1},"fb":"❌ 조회와 차감 사이 경쟁 조건으로 여러 요청이 동시에 통과해 초과 판매가 납니다.","best":false},{"label":"전 좌석에 테이블 단위 잠금을 걸고 순차 처리","fx":{"performance":-3},"fb":"⚠️ 정확하지만 모든 예매가 직렬화돼 오픈런 트래픽을 전혀 감당하지 못합니다.","best":false}]},{"t":"개발","type":"build","goal":"좌석과 재고 테이블을 설계하고 재고가 음수가 되지 않도록 제약을 거세요.","hint":"재고 컬럼에 검증 제약을 두고 좌석에 status와 held_until 컬럼을 두세요.","acc":"seats와 inventory 테이블이 만들어지고 재고가 음수가 될 수 없다.","sol":"CREATE TABLE seats (\n    id BIGINT PRIMARY KEY,\n    concert_id BIGINT NOT NULL,\n    seat_no VARCHAR(10) NOT NULL,\n    status VARCHAR(12) NOT NULL DEFAULT 'AVAILABLE',\n    held_until DATETIME NULL,\n    version INT NOT NULL DEFAULT 0,\n    UNIQUE KEY uk_seat (concert_id, seat_no)\n);\n\nCREATE TABLE inventory (\n    concert_id BIGINT PRIMARY KEY,\n    remaining INT NOT NULL,\n    CHECK (remaining >= 0)\n);","lang":"sql"},{"t":"개발","type":"build","goal":"낙관적 락으로 좌석을 점유하고 재고를 원자적으로 차감하는 쿼리를 작성하세요.","hint":"버전과 상태 조건이 맞을 때만 갱신하고 영향 행수가 0이면 실패로 처리하세요.","acc":"동시에 같은 좌석을 노려도 한 요청만 성공하고 재고가 정확히 줄어든다.","sol":"-- 낙관적 락: version 일치할 때만 좌석 점유, 영향 행수 0이면 재시도\nUPDATE seats\nSET status = 'HELD',\n    held_until = DATE_ADD(NOW(), INTERVAL 5 MINUTE),\n    version = version + 1\nWHERE id = :seat_id\n  AND status = 'AVAILABLE'\n  AND version = :expected_version;\n\nUPDATE inventory\nSET remaining = remaining - 1\nWHERE concert_id = :concert_id\n  AND remaining > 0;","lang":"sql"},{"t":"개발","type":"build","goal":"오픈런 트래픽을 흡수할 대기열과 좌석 홀드 로직을 구현하세요.","hint":"정렬 셋으로 대기 순번을 매기고, 홀드 성공 시에만 재고를 줄이세요.","acc":"대기 순번이 매겨지고, 좌석 홀드가 성공한 요청만 재고를 차감한다.","sol":"import redis, time\n\nr = redis.Redis()\n\ndef enqueue(user_id, concert_id):\n    score = time.time()\n    r.zadd('queue:' + str(concert_id), {str(user_id): score})\n    return r.zrank('queue:' + str(concert_id), str(user_id))\n\ndef try_hold_seat(db, seat_id, expected_version):\n    rows = db.execute(\n        \"UPDATE seats SET status='HELD', version=version+1 \"\n        \"WHERE id=%s AND status='AVAILABLE' AND version=%s\",\n        (seat_id, expected_version))\n    if rows == 0:\n        return False\n    db.execute(\"UPDATE inventory SET remaining=remaining-1 \"\n               \"WHERE concert_id=(SELECT concert_id FROM seats WHERE id=%s) \"\n               \"AND remaining>0\", (seat_id,))\n    db.commit()\n    return True","lang":"python"},{"t":"테스트","type":"note","goal":"예매 시스템의 <b>부하와 동시성 테스트 시나리오</b>를 정리하세요. 재고 1석에 동시 100요청, 대기열 순번 정확성, 홀드 만료 후 재고 복구, 결제 실패 시 좌석 반환을 포함하세요.","ph":"예: 1석 동시 100요청 → 성공 1건 / 홀드 5분 만료 → 재고 +1 / 결제 실패 → 좌석 반환..."},{"t":"장애 대응","type":"decide","goal":"티켓 오픈 직후 트래픽이 예상의 10배로 몰렸고, 일부 인기 좌석 구간에서 <b>재고보다 많은 예매가 확정</b>되는 초과 판매가 발생했습니다.","sit":"초과 판매 사고에 어떻게 대응하시겠습니까?","opts":[{"label":"재고 차감을 조건부 원자 갱신으로 강제하고 확정 전 재고를 재검증","fx":{"database":5,"system_design":4},"fb":"✅ 차감을 단일 원자 연산으로 모아 경쟁 조건을 없애고 초과 판매를 근본 차단합니다.","best":true},{"label":"응답을 느리게 만들어 요청 유입 속도만 늦춤","fx":{"performance":-1},"fb":"⚠️ 잠깐 완화되지만 경쟁 조건 자체가 남아 초과 판매가 다시 발생합니다.","best":false},{"label":"일단 팔고 초과분은 나중에 취소 통보","fx":{"communication":-3,"leadership":-2},"fb":"❌ 확정된 티켓을 취소하는 것은 최악의 고객 경험이며 분쟁까지 부릅니다.","best":false}]},{"t":"장애 연쇄","type":"decide","goal":"급하게 <b>비관적 락</b>으로 좌석을 잠그자 초과 판매는 멈췄지만, 인기 좌석에 요청이 몰려 Lock 대기가 폭증하고 트랜잭션 타임아웃이 쏟아졌습니다.","sit":"비관적 락으로 인한 Lock 대기 폭증에 어떻게 대응하시겠습니까?","opts":[{"label":"핫한 재고를 Redis 원자 연산으로 선차감하고 DB는 확정만 담당","fx":{"system_design":5,"performance":4},"fb":"✅ 경합을 인메모리 원자 연산으로 옮겨 DB Lock 대기를 없애고 처리량을 끌어올립니다.","best":true},{"label":"Lock 타임아웃을 아주 길게 늘려 대기하게 함","fx":{"performance":-3},"fb":"❌ 대기 행렬이 더 길어져 커넥션을 오래 붙잡고 전체 지연을 키웁니다.","best":false},{"label":"DB 사양만 키워 버팀","fx":{"performance":1},"fb":"⚠️ 일시적 완화일 뿐 직렬화 병목은 그대로라 트래픽이 더 오면 재발합니다.","best":false}]},{"t":"장애 연쇄","type":"decide","goal":"Redis 선차감으로 처리량은 올랐지만, 순간 <b>Redis 노드 장애</b>로 재고 상태가 유실되며 같은 좌석이 두 명에게 배정되는 중복이 발생했습니다.","sit":"캐시 장애로 인한 좌석 중복 배정에 어떻게 대응하시겠습니까?","opts":[{"label":"최종 확정 시 DB 유일 제약으로 이중 검증하고 Redis 장애 시 DB 원자 차감으로 폴백","fx":{"system_design":5,"database":4},"fb":"✅ 빠른 경로는 Redis로, 정합성 최후 보루는 DB 제약으로 삼아 중복 배정을 막습니다.","best":true},{"label":"Redis 상태만 믿고 DB 검증은 생략","fx":{"database":-3},"fb":"❌ 캐시가 흔들리는 순간 정합성이 통째로 깨지는 단일 장애점을 만듭니다.","best":false},{"label":"장애가 나면 예매를 전면 중단만 함","fx":{"communication":-1,"system_design":-1},"fb":"⚠️ 중복은 막지만 짧은 캐시 장애마다 서비스가 멈춰 가용성이 크게 떨어집니다.","best":false}]},{"t":"장애 연쇄","type":"decide","goal":"결제까지 이어지지 않은 좌석들이 <b>홀드 상태로 반환되지 않고</b> 쌓이면서, 실제로는 빈 좌석인데 재고가 0으로 표시돼 판매가 멈췄습니다.","sit":"홀드 누수로 인한 재고 고갈에 어떻게 대응하시겠습니까?","opts":[{"label":"홀드에 만료 시간을 두고 배치와 TTL로 미결제 좌석을 자동 반환","fx":{"system_design":5,"database":4},"fb":"✅ 만료된 홀드를 주기적으로 회수해 유령 재고를 없애고 좌석을 다시 판매합니다.","best":true},{"label":"운영자가 수동으로 홀드를 풀어줌","fx":{"communication":-1},"fb":"⚠️ 순간 해결되지만 사람이 놓치는 홀드가 계속 쌓여 같은 문제가 반복됩니다.","best":false},{"label":"홀드 만료 없이 결제 완료만 기다림","fx":{"system_design":-2,"database":-1},"fb":"❌ 이탈한 사용자의 좌석이 영영 잠겨 재고가 마르는 구조적 결함을 방치합니다.","best":false}]},{"t":"Postmortem","type":"note","goal":"초과 판매, 비관적 락으로 인한 Lock 폭증, Redis 장애로 인한 중복 배정, 홀드 누수로 이어진 <b>장애 연쇄</b>를 정리하세요.\n정확성과 처리량을 동시에 만족시키는 설계(원자 연산과 DB 최종 제약, 홀드 TTL)를 왜 처음부터 갖췄어야 했는지 적어보세요.","ph":"타임라인 / 근본 원인: 동시성 설계 미흡 / 재발 방지: Redis와 DB 이중 방어, 홀드 TTL, 부하 테스트..."}]},{"lv":5,"em":"🌐","title":"대규모 이커머스 백엔드","desc":"이벤트 기반으로 확장되는 대규모 이커머스 백엔드를 설계하고 운영 장애를 다룹니다.","skills":["backend","sql","devops"],"phases":[{"t":"요구사항 정의","type":"note","goal":"대규모 이커머스 백엔드의 <b>비기능 요구사항</b>을 정의하세요. 목표 가용성, 피크 트래픽, 서비스 경계(주문·재고·배송 분리), 데이터 일관성 수준을 적어보세요.","ph":"예: 가용성 99.95퍼센트, 피크 5000 TPS, 주문·재고·결제 서비스 분리, 결제는 강한 일관성..."},{"t":"설계 결정","type":"decide","goal":"트래픽과 팀 규모가 커지며 하나의 거대한 애플리케이션이 배포와 확장의 병목이 됐습니다. <b>서비스 경계</b>를 어떻게 나눌지 결정해야 합니다.","sit":"아키텍처 전략을 무엇으로 하시겠습니까?","opts":[{"label":"도메인별 서비스로 분리하고 이벤트 기반으로 느슨하게 연결","fx":{"system_design":6,"leadership":4},"fb":"✅ 서비스별 독립 배포와 확장이 가능해지고 이벤트로 결합도를 낮춰 대규모 트래픽에 유연하게 대응합니다.","best":true},{"label":"모든 기능을 하나의 애플리케이션으로 유지하며 서버만 증설","fx":{"system_design":-2},"fb":"⚠️ 초기엔 단순하지만 배포 충돌과 확장 병목이 커져 조직 규모에 맞지 않게 됩니다.","best":false},{"label":"기능을 잘게 수십 개 마이크로서비스로 즉시 쪼갬","fx":{"system_design":-1,"communication":-2},"fb":"❌ 경계가 불명확한 채 과분할하면 분산 트랜잭션과 운영 복잡도가 폭발합니다.","best":false}]},{"t":"개발","type":"build","goal":"주문 데이터를 사용자 기준으로 샤딩하고, 이벤트 발행을 위한 아웃박스 테이블을 설계하세요.","hint":"사용자 ID로 샤드 키를 만들고, 아웃박스에 미발행 이벤트 조회용 인덱스를 두세요.","acc":"샤딩된 주문 테이블과 아웃박스 테이블, 미발행 인덱스가 생성된다.","sol":"-- user_id 기준 샤딩 키, 주문은 사용자 샤드에 co-locate\nCREATE TABLE orders_shard (\n    id BIGINT NOT NULL,\n    user_id BIGINT NOT NULL,\n    shard_key INT AS (user_id % 16) VIRTUAL,\n    status VARCHAR(20) NOT NULL,\n    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    PRIMARY KEY (id, user_id)\n);\n\nCREATE TABLE outbox (\n    id BIGINT PRIMARY KEY AUTO_INCREMENT,\n    aggregate_id BIGINT NOT NULL,\n    event_type VARCHAR(40) NOT NULL,\n    payload JSON NOT NULL,\n    published TINYINT NOT NULL DEFAULT 0,\n    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX idx_outbox_unpub ON outbox (published, id);","lang":"sql"},{"t":"개발","type":"build","goal":"상품 검색 API에 캐시를 적용해 반복 조회 부하를 줄이세요.","hint":"검색어와 페이지로 캐시 키를 만들고 짧은 TTL로 저장하세요.","acc":"같은 검색어를 반복 조회하면 캐시에서 응답하고 원본 조회가 줄어든다.","sol":"from flask import Flask, request, jsonify\nimport redis, json\n\napp = Flask(__name__)\ncache = redis.Redis()\n\n@app.get('/products')\ndef search():\n    q = request.args.get('q', '')\n    page = int(request.args.get('page', 1))\n    key = 'search:' + q + ':' + str(page)\n    hit = cache.get(key)\n    if hit:\n        return jsonify(json.loads(hit))\n    rows = query_search_index(q, page)  # ES/DB 조회\n    result = {'items': rows, 'page': page}\n    cache.set(key, json.dumps(result), ex=60)\n    return jsonify(result)","lang":"python"},{"t":"개발","type":"build","goal":"아웃박스 패턴으로 주문 이벤트를 안전하게 발행하고, 재고 서비스가 멱등하게 소비하도록 구현하세요.","hint":"DB 트랜잭션으로 아웃박스에 기록한 뒤 별도 퍼블리셔가 발행하고, 소비 측은 이벤트 ID로 중복을 거르세요.","acc":"주문 커밋과 이벤트 발행이 유실 없이 이어지고, 같은 이벤트를 두 번 받아도 재고가 한 번만 줄어든다.","sol":"import json, time\n\ndef publish_outbox(db, kafka):\n    while True:\n        rows = db.query(\n            \"SELECT id, event_type, payload FROM outbox \"\n            \"WHERE published=0 ORDER BY id LIMIT 100\")\n        if not rows:\n            time.sleep(0.5)\n            continue\n        for row in rows:\n            kafka.send(row['event_type'], json.loads(row['payload']))\n            db.execute(\"UPDATE outbox SET published=1 WHERE id=%s\", (row['id'],))\n        db.commit()\n\ndef on_order_paid(event, inventory_svc):\n    # 멱등 소비: event_id 기록 후 재고 차감\n    if inventory_svc.already_processed(event['event_id']):\n        return\n    inventory_svc.decrease(event['product_id'], event['qty'])\n    inventory_svc.mark_processed(event['event_id'])","lang":"python"},{"t":"테스트","type":"note","goal":"대규모 백엔드의 <b>부하와 신뢰성 테스트 시나리오</b>를 정리하세요. 피크 TPS 부하 테스트, 이벤트 소비 지연 주입, 서비스 하나 장애 시 격리(부분 실패), 캐시 미스 폭주를 포함하세요.","ph":"예: 5000 TPS 부하 / 재고 서비스 다운 시 주문은 유지 / 이벤트 1분 지연 주입..."},{"t":"배포 결정","type":"decide","goal":"새 버전을 무중단으로 내보내야 합니다. 문제가 생겨도 <b>영향 범위를 최소화</b>할 배포 전략을 정해야 합니다.","sit":"배포 전략을 무엇으로 하시겠습니까?","opts":[{"label":"소량 트래픽에 먼저 배포하는 카나리 배포 후 지표를 보며 점진 확대","fx":{"system_design":5,"performance":4},"fb":"✅ 문제를 소수 트래픽에서 조기에 잡아 전체 확산 전에 롤백할 수 있어 위험을 최소화합니다.","best":true},{"label":"전 서버에 한 번에 새 버전을 배포","fx":{"system_design":-2,"performance":-1},"fb":"❌ 결함이 있으면 즉시 전체 사용자에게 퍼져 대형 장애로 번집니다.","best":false},{"label":"트래픽이 적은 새벽에 몰아서 전면 교체","fx":{"communication":-1},"fb":"⚠️ 영향은 줄지만 여전히 한 번에 전량 교체라 문제 시 롤백 범위가 큽니다.","best":false}]},{"t":"장애 대응","type":"decide","goal":"카나리로 신버전을 5퍼센트 트래픽에 배포했는데, 새 코드의 <b>메모리 누수</b>로 카나리 인스턴스들이 시간이 지나며 OOM으로 재시작을 반복했습니다.","sit":"카나리에서 발견된 메모리 누수와 OOM에 어떻게 대응하시겠습니까?","opts":[{"label":"카나리를 즉시 롤백하고 지표와 힙 덤프로 누수를 분석","fx":{"system_design":5,"debugging":4},"fb":"✅ 확산 전에 되돌려 피해를 카나리로 가두고, 근본 원인을 데이터로 규명하는 정석 대응입니다.","best":true},{"label":"메모리가 부족하니 인스턴스 사양만 키워 그대로 확대","fx":{"performance":-2,"system_design":-1},"fb":"❌ 누수는 시간이 지나면 어떤 크기든 채우므로 전면 배포 시 대형 장애가 됩니다.","best":false},{"label":"자동 재시작에 맡기고 배포를 계속 진행","fx":{"debugging":-2,"system_design":-2},"fb":"⚠️ 재시작 사이 요청이 끊기고 누수가 전체로 퍼져 상황을 키웁니다.","best":false}]},{"t":"장애 연쇄","type":"decide","goal":"롤백으로 급증한 재시도와 세일 트래픽이 겹쳤는데 <b>오토스케일링이 늦게 반응</b>해, 처리 용량이 부족한 사이 주문 처리 큐가 빠르게 쌓였습니다.","sit":"오토스케일 지연으로 인한 큐 적체에 어떻게 대응하시겠습니까?","opts":[{"label":"선제적 스케일아웃과 부하 차단으로 유입을 다듬고 큐를 소화","fx":{"system_design":5,"performance":4},"fb":"✅ 용량을 미리 늘리고 초과 유입은 완만히 제한해 큐 폭주와 도미노 실패를 막습니다.","best":true},{"label":"큐 용량을 무제한으로 늘려 다 받음","fx":{"performance":-2,"system_design":-1},"fb":"❌ 처리 속도는 그대로라 지연만 무한정 길어지고 메시지가 오래돼 무의미해집니다.","best":false},{"label":"오토스케일이 따라올 때까지 그냥 기다림","fx":{"performance":-2},"fb":"⚠️ 스케일이 붙기 전 큐가 임계치를 넘겨 소비자까지 무너질 위험이 큽니다.","best":false}]},{"t":"장애 연쇄","type":"decide","goal":"큐 적체로 재고 차감 <b>이벤트 소비가 지연</b>되면서, 실제 재고와 주문 서비스가 보는 재고가 어긋나 품절 상품이 계속 주문되는 데이터 불일치가 발생했습니다.","sit":"이벤트 지연으로 인한 재고 데이터 불일치에 어떻게 대응하시겠습니까?","opts":[{"label":"소비자를 확장해 밀린 이벤트를 소화하고 정합성 대사 배치로 어긋난 재고를 바로잡음","fx":{"system_design":5,"database":4},"fb":"✅ 처리량을 늘려 지연을 해소하고 주기적 대사로 최종 일관성을 회복하는 견고한 대응입니다.","best":true},{"label":"불일치는 결국 맞춰지니 그대로 둠","fx":{"database":-3,"communication":-1},"fb":"❌ 품절 상품 주문이 계속 확정돼 취소·환불과 고객 불만이 눈덩이처럼 커집니다.","best":false},{"label":"이벤트 큐를 비우고 재고를 수동으로 덮어씀","fx":{"database":-2},"fb":"⚠️ 밀린 이벤트를 버리면 처리 안 된 주문의 재고 변화가 유실돼 더 큰 불일치를 만듭니다.","best":false}]},{"t":"Postmortem","type":"note","goal":"카나리 메모리 누수로 인한 OOM, 오토스케일 지연으로 인한 큐 적체, 이벤트 소비 지연으로 인한 데이터 불일치로 번진 <b>장애 연쇄</b>를 정리하세요.\n배포 안전장치, 용량 계획, 이벤트 처리 백프레셔와 정합성 대사가 각각 어디서 필요했는지 적어보세요.","ph":"타임라인 / 근본 원인: 배포 검증·용량 여유 부족 / 재발 방지: 카나리 자동 지표 롤백, 예측 스케일링, 정합성 대사 배치..."}]},{"lv":1,"em":"🧮","title":"CLI 유틸리티","skills":["python"],"kind":"guide","goal":"argparse로 서브커맨드를 갖춘 파일 처리용 CLI 유틸리티를 만듭니다. 파일의 줄/단어/글자 수를 세고, 올바른 종료 코드와 에러 메시지를 반환하는 실전형 명령줄 도구를 완성합니다.","steps":[{"t":"argparse 파서 구조 설계","goal":"argparse.ArgumentParser로 프로그램의 뼈대를 만들고 서브커맨드(wc)를 등록합니다. 위치 인자(path)와 옵션 플래그(-l/--lines)를 정의해 확장 가능한 CLI 구조를 잡습니다.","hint":"add_subparsers(dest=..., required=True)로 서브커맨드를 강제하고, add_argument에 action=\"store_true\"로 불리언 플래그를 만드세요.","acc":"python myutil.py wc sample.txt -l 을 실행하면 파싱된 Namespace가 출력되고, 서브커맨드 없이 실행하면 사용법 에러가 뜬다.","sol":"import argparse\n\ndef build_parser():\n    parser = argparse.ArgumentParser(prog=\"myutil\", description=\"파일 유틸리티\")\n    # 서브커맨드를 강제해 명확한 CLI 구조를 만든다\n    sub = parser.add_subparsers(dest=\"command\", required=True)\n\n    p_wc = sub.add_parser(\"wc\", help=\"줄/단어/글자 수 세기\")\n    p_wc.add_argument(\"path\", help=\"대상 파일 경로\")\n    p_wc.add_argument(\"-l\", \"--lines\", action=\"store_true\", help=\"줄 수만 출력\")\n    return parser\n\nif __name__ == \"__main__\":\n    args = build_parser().parse_args()\n    print(args)  # 파싱 결과 확인용"},{"t":"파일 카운트 로직 구현","goal":"지정한 파일을 읽어 줄 수, 단어 수, 글자 수를 계산하는 함수를 만듭니다. -l 플래그가 있으면 줄 수만, 없으면 wc 형식으로 탭 구분 출력합니다.","hint":"pathlib.Path의 read_text로 파일을 읽고, str.splitlines()와 str.split()으로 줄/단어를 나누세요.","acc":"두 줄짜리 파일에 대해 줄=2, 단어 수가 정확히 출력되고, -l 옵션이면 숫자 하나만 나온다.","sol":"from pathlib import Path\n\ndef count_file(path):\n    text = Path(path).read_text(encoding=\"utf-8\")\n    lines = text.splitlines()\n    words = text.split()\n    return len(lines), len(words), len(text)\n\ndef run_wc(args):\n    n_lines, n_words, n_chars = count_file(args.path)\n    if args.lines:\n        print(n_lines)          # -l 이면 줄 수만\n    else:\n        # wc 형식: 줄  단어  글자  파일명\n        print(f\"{n_lines}\\t{n_words}\\t{n_chars}\\t{args.path}\")"},{"t":"에러 처리와 종료 코드","goal":"존재하지 않는 파일이나 권한 없는 파일을 다룰 때 예외를 잡아 stderr로 메시지를 내보내고 적절한 종료 코드로 종료합니다. 정상 처리 시 0으로 종료합니다.","hint":"try/except로 FileNotFoundError, PermissionError를 잡고 sys.exit(코드)와 print(..., file=sys.stderr)를 사용하세요.","acc":"없는 파일을 주면 stderr에 오류 메시지가 뜨고 echo $? 가 2를 반환하며, 정상 파일은 0을 반환한다.","sol":"import sys\n\ndef main():\n    args = build_parser().parse_args()\n    try:\n        if args.command == \"wc\":\n            run_wc(args)\n    except FileNotFoundError:\n        print(f\"오류: 파일을 찾을 수 없습니다 - {args.path}\", file=sys.stderr)\n        sys.exit(2)             # 관례상 파일 없음은 종료코드 2\n    except PermissionError:\n        print(f\"오류: 읽기 권한이 없습니다 - {args.path}\", file=sys.stderr)\n        sys.exit(13)\n    sys.exit(0)                 # 정상 종료\n\nif __name__ == \"__main__\":\n    main()"},{"t":"서브프로세스 테스트 작성","goal":"CLI를 실제 프로세스로 실행해 출력과 종료 코드를 검증하는 테스트를 작성합니다. 임시 파일을 만들어 통합 테스트 형태로 동작을 보증합니다.","hint":"tempfile.NamedTemporaryFile로 입력 파일을 만들고 subprocess.run(..., capture_output=True, text=True)로 결과를 확인하세요.","acc":"테스트를 실행하면 returncode가 0이고 stdout이 기대한 카운트로 시작함을 assert가 통과하며 '통과'가 출력된다.","sol":"import subprocess, sys, tempfile, os\n\ndef test_wc_counts():\n    # 임시 파일을 만들어 CLI를 실제 프로세스로 실행해 검증\n    with tempfile.NamedTemporaryFile(\"w\", suffix=\".txt\",\n                                     delete=False, encoding=\"utf-8\") as f:\n        f.write(\"hello world\\nsecond line\\n\")\n        path = f.name\n    try:\n        result = subprocess.run(\n            [sys.executable, \"myutil.py\", \"wc\", path],\n            capture_output=True, text=True,\n        )\n        assert result.returncode == 0\n        assert result.stdout.startswith(\"2\\t4\\t\")  # 줄2 단어4\n    finally:\n        os.remove(path)\n    print(\"통과\")\n\nif __name__ == \"__main__\":\n    test_wc_counts()"}]},{"lv":2,"em":"🗄️","title":"SQL 리포트 스크립트","skills":["sql","python"],"kind":"guide","goal":"sqlite3를 쓰는 파이썬 스크립트로 매출 데이터를 집계하는 리포트를 만듭니다. GROUP BY 집계와 윈도우 함수(RANK, 누적합, LAG)를 활용해 카테고리별·월별 분석 리포트를 자동 생성합니다.","steps":[{"t":"스키마와 샘플 데이터 준비","goal":"sqlite3 인메모리 DB에 sales 테이블을 만들고 샘플 매출 데이터를 넣습니다. 이후 모든 리포트 쿼리의 기반이 되는 재현 가능한 데이터셋을 구성합니다.","hint":"sqlite3.connect(\":memory:\")로 임시 DB를 만들고, executemany와 물음표 플레이스홀더로 여러 행을 안전하게 삽입하세요.","acc":"SELECT COUNT(*) FROM sales가 5를 반환하고, 스크립트가 오류 없이 커밋까지 마친다.","sol":"import sqlite3\n\nconn = sqlite3.connect(\":memory:\")\ncur = conn.cursor()\ncur.executescript(\n    \"CREATE TABLE sales (\"\n    \" id INTEGER PRIMARY KEY,\"\n    \" category TEXT NOT NULL,\"\n    \" product TEXT NOT NULL,\"\n    \" amount INTEGER NOT NULL,\"\n    \" sold_at TEXT NOT NULL);\"  # 'YYYY-MM-DD'\n)\nrows = [\n    (\"가전\", \"TV\", 1200, \"2026-01-05\"),\n    (\"가전\", \"냉장고\", 900, \"2026-01-11\"),\n    (\"도서\", \"파이썬\", 30, \"2026-01-07\"),\n    (\"도서\", \"SQL\", 25, \"2026-02-02\"),\n    (\"가전\", \"TV\", 1200, \"2026-02-15\"),\n]\ncur.executemany(\n    \"INSERT INTO sales(category, product, amount, sold_at) VALUES (?,?,?,?)\",\n    rows,\n)\nconn.commit()"},{"t":"GROUP BY 집계 리포트","goal":"카테고리별 판매 건수, 총매출, 평균 금액을 집계하는 쿼리를 작성합니다. HAVING으로 소액 카테고리를 걸러내고 총매출 내림차순으로 정렬합니다.","hint":"GROUP BY category와 함께 COUNT(*), SUM(amount), AVG(amount)를 쓰고, 집계 결과 필터는 WHERE가 아니라 HAVING을 사용하세요.","acc":"카테고리별 한 행씩 출력되고 총매출이 큰 카테고리가 먼저 나오며, 합계 100 이하 그룹은 제외된다.","sol":"# 카테고리별 집계 리포트: 건수/합계/평균, HAVING으로 소액 제외\nquery = \"\"\"\nSELECT category,\n       COUNT(*)              AS cnt,\n       SUM(amount)           AS total,\n       ROUND(AVG(amount), 1) AS avg_amount\nFROM sales\nGROUP BY category\nHAVING SUM(amount) > 100\nORDER BY total DESC;\n\"\"\"\nprint(\"카테고리\\t건수\\t합계\\t평균\")\nfor category, cnt, total, avg in cur.execute(query):\n    print(f\"{category}\\t{cnt}\\t{total}\\t{avg}\")"},{"t":"윈도우 함수로 순위·누적","goal":"PARTITION BY로 카테고리 안에서 매출 순위(RANK)를 매기고, 시간순 누적합(SUM OVER)을 계산합니다. 원본 행을 유지하면서 분석 컬럼을 덧붙이는 윈도우 함수를 익힙니다.","hint":"RANK() OVER (PARTITION BY ... ORDER BY ...)와 SUM(amount) OVER (... ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)를 사용하세요.","acc":"각 카테고리 안에서 금액이 큰 행이 순위 1이고, running_total이 시간순으로 누적되어 증가한다.","sol":"# 윈도우 함수: 카테고리 내 순위(RANK) + 시간순 누적합\nquery = \"\"\"\nSELECT category,\n       product,\n       amount,\n       RANK() OVER (\n           PARTITION BY category ORDER BY amount DESC\n       ) AS rank_in_cat,\n       SUM(amount) OVER (\n           PARTITION BY category ORDER BY sold_at\n           ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW\n       ) AS running_total\nFROM sales\nORDER BY category, rank_in_cat;\n\"\"\"\nfor cat, product, amount, rnk, running in cur.execute(query):\n    print(f\"{cat} {product} {amount}원  순위{rnk}  누적{running}\")"},{"t":"전월 대비 증감 리포트","goal":"CTE로 월별 매출을 집계한 뒤 LAG로 직전 달 매출을 끌어와 증감액을 계산합니다. 시계열 비교가 들어간 최종 리포트를 완성하고 커넥션을 닫습니다.","hint":"WITH monthly AS (...)로 월별 합계를 만들고, total - LAG(total) OVER (ORDER BY ym)로 전월 대비 차이를 구하세요. 첫 달은 NULL 처리를 잊지 마세요.","acc":"월별로 매출과 전월대비 증감이 출력되고, 첫 달은 '-'로, 이후는 부호가 붙은 숫자로 표시된다.","sol":"# 월별 매출과 전월 대비 증감(LAG) 리포트\nquery = \"\"\"\nWITH monthly AS (\n    SELECT substr(sold_at, 1, 7) AS ym,\n           SUM(amount)           AS total\n    FROM sales\n    GROUP BY ym\n)\nSELECT ym,\n       total,\n       total - LAG(total) OVER (ORDER BY ym) AS diff_prev\nFROM monthly\nORDER BY ym;\n\"\"\"\nprint(\"월\\t매출\\t전월대비\")\nfor ym, total, diff in cur.execute(query):\n    d = \"-\" if diff is None else f\"{diff:+d}\"\n    print(f\"{ym}\\t{total}\\t{d}\")\nconn.close()"}]},{"lv":3,"em":"🔌","title":"REST API 서버","skills":["python","backend"],"kind":"guide","goal":"FastAPI로 메모를 관리하는 REST API 서버를 만듭니다. Pydantic 스키마 기반 검증, 생성·조회 CRUD, 그리고 깊은 페이지에서도 안정적인 키셋 페이지네이션까지 갖춘 실전형 백엔드를 구현합니다.","steps":[{"t":"앱과 Pydantic 스키마 정의","goal":"FastAPI 앱을 만들고 입력용(MemoIn)과 출력용(MemoOut) Pydantic 모델을 정의합니다. Field로 길이 제약을 걸어 요청/응답 구조를 명확히 분리합니다.","hint":"BaseModel을 상속하고 Field(min_length=..., max_length=...)로 제약을 겁니다. 출력 모델은 입력 모델을 상속해 id, created_at을 추가하세요.","acc":"앱을 uvicorn으로 띄우면 /docs에 MemoIn, MemoOut 스키마가 노출되고 서버가 오류 없이 기동된다.","sol":"from fastapi import FastAPI\nfrom pydantic import BaseModel, Field\nfrom datetime import datetime\n\napp = FastAPI(title=\"메모 API\")\n\n# 입력용 스키마\nclass MemoIn(BaseModel):\n    title: str = Field(min_length=1, max_length=100)\n    body: str = Field(default=\"\", max_length=2000)\n\n# 출력용 스키마 (id, 생성시각 포함)\nclass MemoOut(MemoIn):\n    id: int\n    created_at: datetime\n\n# 간단한 인메모리 저장소 (실무에선 DB로 교체)\n_db: dict[int, MemoOut] = {}\n_seq = 0"},{"t":"생성·조회 CRUD 구현","goal":"POST /memos로 메모를 생성하고 GET /memos/{id}로 단건 조회하는 엔드포인트를 만듭니다. 없는 id를 조회하면 404를 반환하도록 처리합니다.","hint":"@app.post에 response_model과 status_code=201을 지정하고, 조회 실패 시 HTTPException(status_code=404)를 raise하세요.","acc":"POST로 만든 메모가 201과 함께 id/created_at을 포함해 반환되고, 없는 id 조회 시 404가 온다.","sol":"from fastapi import HTTPException\n\n@app.post(\"/memos\", response_model=MemoOut, status_code=201)\ndef create_memo(payload: MemoIn):\n    global _seq\n    _seq += 1\n    memo = MemoOut(id=_seq, created_at=datetime.utcnow(),\n                   **payload.model_dump())\n    _db[memo.id] = memo\n    return memo\n\n@app.get(\"/memos/{memo_id}\", response_model=MemoOut)\ndef get_memo(memo_id: int):\n    memo = _db.get(memo_id)\n    if memo is None:\n        raise HTTPException(status_code=404, detail=\"메모를 찾을 수 없습니다\")\n    return memo"},{"t":"입력 검증 강화","goal":"field_validator로 공백만 있는 제목을 거부하고 앞뒤 공백을 정리하는 커스텀 검증을 추가합니다. 필드 제약을 넘어서는 비즈니스 규칙 검증을 익힙니다.","hint":"@field_validator(\"title\")와 @classmethod를 붙인 메서드에서 v.strip()이 비면 ValueError를 던지세요. FastAPI가 이를 422로 변환합니다.","acc":"제목에 공백만 보내면 422와 함께 에러 메시지가 오고, 앞뒤 공백은 저장 시 제거된다.","sol":"from pydantic import field_validator\n\nclass MemoIn(BaseModel):\n    title: str = Field(min_length=1, max_length=100)\n    body: str = Field(default=\"\", max_length=2000)\n\n    @field_validator(\"title\")\n    @classmethod\n    def title_not_blank(cls, v: str) -> str:\n        # 공백만 있는 제목 거부. 실패 시 FastAPI가 자동 422 반환\n        if not v.strip():\n            raise ValueError(\"제목은 공백일 수 없습니다\")\n        return v.strip()\n\n    @field_validator(\"body\")\n    @classmethod\n    def strip_body(cls, v: str) -> str:\n        return v.strip()"},{"t":"키셋 페이지네이션","goal":"GET /memos에 after_id 커서와 limit을 받아 키셋 페이지네이션으로 목록을 반환합니다. OFFSET 대신 마지막 id를 기준으로 잘라 깊은 페이지에서도 성능이 안정적이게 만듭니다.","hint":"Query로 after_id(선택), limit(ge=1, le=100)을 받고, id > after_id 조건으로 필터한 뒤 limit개를 반환하세요. 실 DB에선 WHERE id > :after_id ORDER BY id LIMIT :limit 입니다.","acc":"after_id 없이 호출하면 처음부터, 마지막 id를 after_id로 넘기면 그 다음 페이지가 반환되고 limit 개수를 넘지 않는다.","sol":"from fastapi import Query\n\n@app.get(\"/memos\", response_model=list[MemoOut])\ndef list_memos(\n    after_id: int | None = Query(default=None, description=\"이 id 이후부터\"),\n    limit: int = Query(default=20, ge=1, le=100),\n):\n    # 키셋 페이지네이션: OFFSET 대신 마지막 id를 커서로 사용 → 깊은 페이지도 안정\n    # 실 DB에선: WHERE id > :after_id ORDER BY id ASC LIMIT :limit\n    rows = sorted(_db.values(), key=lambda m: m.id)\n    if after_id is not None:\n        rows = [m for m in rows if m.id > after_id]\n    page = rows[:limit]\n    return page"}]},{"lv":4,"em":"🔐","title":"인증·권한 시스템","skills":["security","sql"],"kind":"guide","goal":"안전한 비밀번호 저장과 토큰 기반 인증을 갖춘 인증·권한 시스템을 만듭니다. bcrypt salt 해싱, 파라미터라이즈드 쿼리로 SQL 인젝션 방어, HMAC 서명 토큰 발급·검증, 그리고 최소 권한 원칙의 DB 권한 설정까지 다룹니다.","steps":[{"t":"비밀번호 해싱과 salt","goal":"bcrypt로 비밀번호를 salt와 함께 해싱하고 검증하는 함수를 만듭니다. 평문을 절대 저장하지 않고, 같은 비밀번호도 매번 다른 해시가 나오는 원리를 익힙니다.","hint":"bcrypt.gensalt(rounds=12)로 salt를 만들고 bcrypt.hashpw로 해싱, 검증은 bcrypt.checkpw로 상수시간 비교하세요.","acc":"같은 비밀번호를 두 번 해싱하면 결과가 다르지만 둘 다 verify를 통과하고, 틀린 비밀번호는 실패한다.","sol":"import bcrypt\n\ndef hash_password(plain: str) -> bytes:\n    # gensalt()가 랜덤 salt를 만들어 해시에 함께 저장한다 (cost=12)\n    salt = bcrypt.gensalt(rounds=12)\n    return bcrypt.hashpw(plain.encode(\"utf-8\"), salt)\n\ndef verify_password(plain: str, hashed: bytes) -> bool:\n    # 저장된 해시에서 salt를 추출해 상수시간 비교\n    return bcrypt.checkpw(plain.encode(\"utf-8\"), hashed)\n\nif __name__ == \"__main__\":\n    h = hash_password(\"s3cret!\")\n    print(h.decode())                     # $2b$12$... 형태\n    assert verify_password(\"s3cret!\", h)\n    assert not verify_password(\"wrong\", h)\n    print(\"OK\")"},{"t":"회원가입·로그인과 인젝션 방어","goal":"해시를 DB에 저장하는 회원가입과, 저장된 해시로 비밀번호를 검증하는 로그인을 구현합니다. 모든 쿼리를 플레이스홀더로 바인딩해 SQL 인젝션을 원천 차단합니다.","hint":"conn.execute(\"... WHERE username = ?\", (username,))처럼 값은 반드시 튜플로 전달하고, 문자열 연결(f-string)로 쿼리를 만들지 마세요.","acc":"정상 계정은 로그인에 성공하고, 사용자명에 ' OR '1'='1 같은 문자열을 넣어도 인젝션이 통하지 않는다.","sol":"import sqlite3\n\ndef register(conn, username: str, password: str):\n    hashed = hash_password(password)\n    # 플레이스홀더(?)로 값 바인딩 → SQL 인젝션 방지 (문자열 연결 금지)\n    conn.execute(\n        \"INSERT INTO users(username, pw_hash) VALUES (?, ?)\",\n        (username, hashed),\n    )\n    conn.commit()\n\ndef login(conn, username: str, password: str) -> bool:\n    cur = conn.execute(\n        \"SELECT pw_hash FROM users WHERE username = ?\",  # 파라미터 바인딩\n        (username,),\n    )\n    row = cur.fetchone()\n    if row is None:\n        return False                 # 유저 없음\n    return verify_password(password, row[0])"},{"t":"토큰 발급과 검증","goal":"로그인 성공 시 HMAC-SHA256으로 서명한 만료시간 포함 토큰을 발급하고, 요청마다 서명과 만료를 검증하는 함수를 만듭니다. 위조와 만료를 모두 걸러냅니다.","hint":"payload를 base64로 인코딩하고 hmac.new(SECRET, body, sha256)로 서명, 검증 시 hmac.compare_digest로 상수시간 비교하고 exp를 확인하세요.","acc":"발급한 토큰은 verify에서 payload를 돌려주고, 서명을 한 글자라도 바꾸거나 만료되면 None이 반환된다.","sol":"import hmac, hashlib, time, base64, json\n\nSECRET = b\"replace-with-env-secret\"    # 실제로는 환경변수에서 주입\n\ndef issue_token(user_id: int, ttl: int = 3600) -> str:\n    payload = {\"uid\": user_id, \"exp\": int(time.time()) + ttl}\n    body = base64.urlsafe_b64encode(json.dumps(payload).encode()).rstrip(b\"=\")\n    sig = hmac.new(SECRET, body, hashlib.sha256).hexdigest()\n    return f\"{body.decode()}.{sig}\"\n\ndef verify_token(token: str) -> dict | None:\n    try:\n        body, sig = token.split(\".\")\n    except ValueError:\n        return None\n    expected = hmac.new(SECRET, body.encode(), hashlib.sha256).hexdigest()\n    if not hmac.compare_digest(sig, expected):   # 상수시간 비교\n        return None\n    payload = json.loads(base64.urlsafe_b64decode(body + \"=\" * (-len(body) % 4)))\n    if payload[\"exp\"] < int(time.time()):\n        return None                               # 만료됨\n    return payload"},{"t":"최소 권한 DB 계정","goal":"애플리케이션 전용 DB 역할을 만들고 필요한 최소 권한만 부여합니다. 읽기·쓰기는 허용하되 DELETE와 스키마 변경은 막아 사고 시 피해 범위를 줄입니다.","hint":"CREATE ROLE ... LOGIN 후 GRANT SELECT, INSERT, UPDATE만 주고 REVOKE DELETE로 삭제를 회수하세요. 시퀀스 USAGE도 잊지 마세요.","acc":"app_user로 SELECT/INSERT/UPDATE는 되지만 DELETE나 DROP은 권한 거부되고, 새 테이블 기본 권한도 읽기로 제한된다.","sol":"-- 애플리케이션 전용 역할: 최소 권한(least privilege) 원칙\nCREATE ROLE app_user LOGIN PASSWORD 'change-me';\n\n-- 스키마 사용은 허용하되 객체 생성은 금지\nGRANT USAGE ON SCHEMA public TO app_user;\n\n-- users 테이블: 읽기/쓰기만 허용, DROP/ALTER 불가\nGRANT SELECT, INSERT, UPDATE ON users TO app_user;\n\n-- INSERT 시 id 발급을 위한 시퀀스 권한\nGRANT USAGE ON SEQUENCE users_id_seq TO app_user;\n\n-- 삭제는 관리자만: DELETE 권한은 명시적으로 회수\nREVOKE DELETE ON users FROM app_user;\n\n-- 앞으로 생성될 테이블 기본 권한도 읽기로 제한 (과다 권한 방지)\nALTER DEFAULT PRIVILEGES IN SCHEMA public\n    GRANT SELECT ON TABLES TO app_user;"}]},{"lv":5,"em":"🌐","title":"대규모 서비스 설계","skills":["sql","backend","devops"],"kind":"guide","goal":"트래픽이 급증하는 서비스를 견디도록 확장 전략을 설계합니다. 읽기 복제본 라우팅, 캐시 계층(cache-aside), 시계열 테이블 파티셔닝, 그리고 샤딩까지 이어지는 확장 사다리를 코드와 아키텍처 노트로 정리합니다.","steps":[{"t":"읽기 복제본 라우팅","goal":"쓰기는 Primary로, 읽기는 여러 Replica로 분산하는 커넥션 라우터를 설계합니다. 복제 지연에 민감한 조회만 Primary로 보내는 예외 처리도 포함합니다.","hint":"write 플래그와 read_your_writes 플래그로 분기하고, 일반 조회는 random.choice(REPLICAS)로 분산하세요. 아키텍처 의도를 주석으로 남기세요.","acc":"쓰기와 '쓰기 직후 읽기'는 Primary DSN을, 일반 조회는 Replica DSN 중 하나를 반환함을 설명할 수 있다.","sol":"# 읽기/쓰기 분리 라우터\n# 아키텍처: 쓰기는 Primary 1대, 읽기는 Replica N대로 분산.\n# 복제 지연(replication lag)이 민감한 조회만 Primary로 강제한다.\nimport random\n\nPRIMARY = \"postgresql://primary:5432/app\"\nREPLICAS = [\n    \"postgresql://replica1:5432/app\",\n    \"postgresql://replica2:5432/app\",\n]\n\ndef get_dsn(write: bool, read_your_writes: bool = False) -> str:\n    if write or read_your_writes:\n        return PRIMARY               # 쓰기 직후 조회는 지연 회피 위해 Primary\n    return random.choice(REPLICAS)   # 일반 조회는 Replica로 분산\n\n# 효과: SELECT 트래픽 대부분을 Replica로 보내 Primary CPU를 확보"},{"t":"캐시 계층 (cache-aside)","goal":"자주 조회되는 사용자 데이터에 cache-aside 패턴을 적용합니다. 미스 시 DB에서 읽어 캐시를 채우고, 쓰기 시 해당 키를 삭제해 정합성을 유지합니다.","hint":"캐시 조회 → 미스면 DB 조회 후 cache.set(key, ..., ex=TTL) 순서로 짜고, 업데이트 함수에서는 cache.delete로 무효화하세요.","acc":"두 번째 조회는 캐시 히트로 DB를 건드리지 않고, 이름을 수정하면 캐시가 지워져 다음 조회가 최신 값을 가져온다.","sol":"import json\n\n# Cache-aside 패턴: 미스 시 DB 조회 후 채우고, 쓰기 시 키를 삭제해 무효화\ndef get_user(cache, db, user_id: int):\n    key = f\"user:{user_id}\"\n    cached = cache.get(key)\n    if cached is not None:\n        return json.loads(cached)              # 캐시 히트\n    row = db.execute(\n        \"SELECT id, name FROM users WHERE id = ?\", (user_id,)\n    ).fetchone()\n    if row is None:\n        return None\n    user = {\"id\": row[0], \"name\": row[1]}\n    cache.set(key, json.dumps(user), ex=300)   # TTL 300초로 DB 부하 감소\n    return user\n\ndef update_user_name(cache, db, user_id: int, name: str):\n    db.execute(\"UPDATE users SET name = ? WHERE id = ?\", (name, user_id))\n    db.commit()\n    cache.delete(f\"user:{user_id}\")            # 쓰기 후 캐시 무효화"},{"t":"시계열 테이블 파티셔닝","goal":"대량으로 쌓이는 이벤트 로그 테이블을 월 단위 RANGE 파티셔닝으로 설계합니다. 오래된 데이터는 파티션 DROP으로 빠르게 지우고, 조회는 파티션 프루닝으로 가속합니다.","hint":"PARTITION BY RANGE (created_at)로 부모 테이블을 만들고, 월별로 CREATE TABLE ... PARTITION OF ... FOR VALUES FROM ... TO ...를 정의하세요. 조회 컬럼에 인덱스도 거세요.","acc":"created_at 범위 조건이 있는 쿼리가 해당 월 파티션만 스캔하고, 지난달 데이터를 파티션 단위로 즉시 제거할 수 있음을 설명할 수 있다.","sol":"-- 시계열 이벤트 테이블을 월 단위 RANGE 파티셔닝\n-- 목적: 오래된 파티션은 DROP으로 즉시 삭제, 조회는 파티션 프루닝으로 가속\nCREATE TABLE events (\n    id         BIGINT GENERATED ALWAYS AS IDENTITY,\n    user_id    BIGINT NOT NULL,\n    kind       TEXT   NOT NULL,\n    created_at TIMESTAMPTZ NOT NULL\n) PARTITION BY RANGE (created_at);\n\n-- 월별 파티션 (실무에선 pg_partman 등으로 자동 생성)\nCREATE TABLE events_2026_07 PARTITION OF events\n    FOR VALUES FROM ('2026-07-01') TO ('2026-08-01');\nCREATE TABLE events_2026_08 PARTITION OF events\n    FOR VALUES FROM ('2026-08-01') TO ('2026-09-01');\n\n-- 조회 패턴에 맞춘 인덱스 (파티션마다 생성)\nCREATE INDEX ON events_2026_07 (user_id, created_at DESC);\n\n-- created_at 조건이 있으면 해당 파티션만 스캔:\n--   WHERE created_at >= '2026-07-10' AND user_id = 42"},{"t":"샤딩과 확장 아키텍처","goal":"단일 DB 한계를 넘어설 때를 대비해 user_id 기반 수평 샤딩 라우터를 설계하고, 수직 확장부터 샤딩까지 이어지는 확장 사다리와 가용성 전략을 아키텍처 노트로 정리합니다.","hint":"user_id % SHARD_COUNT로 샤드를 결정하고 샤드별 DSN을 반환하세요. 실무의 일관성 해시·failover는 주석으로 남기고, 크로스 샤드 조인을 피하는 이유를 적으세요.","acc":"임의의 user_id가 항상 같은 샤드로 매핑되고, 확장 단계(수직→Replica→캐시→파티셔닝→샤딩)와 각 샤드 이중화를 설명할 수 있다.","sol":"# 샤딩: 단일 DB 용량 한계 초과 시 user_id로 수평 분할\n# 아키텍처 노트:\n#   [LB] -> [App x N] -> [Shard Router] -> [DB Shard 0..K-1]\n#                     -> [Redis 캐시]    -> [각 샤드: Primary + Replica]\n#   - 샤드 키는 불변값 user_id 사용 (재배치 비용 최소화)\n#   - 크로스 샤드 조인은 피하고 필요한 데이터는 비정규화/복제\nSHARD_COUNT = 4\n\ndef shard_for(user_id: int) -> int:\n    # 단순 모듈로 샤딩 (실무는 일관성 해시로 리샤딩 비용 완화)\n    return user_id % SHARD_COUNT\n\ndef dsn_for_user(user_id: int) -> str:\n    return f\"postgresql://shard{shard_for(user_id)}:5432/app\"\n\n# 확장 사다리 요약:\n#   1) 수직 확장 -> 2) 읽기 Replica -> 3) 캐시 -> 4) 파티셔닝 -> 5) 샤딩\n#   가용성: 각 샤드도 Primary+Replica 이중화, 장애 시 승격(failover)\nif __name__ == \"__main__\":\n    print([shard_for(u) for u in (1, 2, 3, 4, 5)])  # -> [1, 2, 3, 0, 1]"}]},{"lv":5,"em":"📉","title":"월 500만 사용자 서비스 리팩토링","desc":"느려진 서비스를 추측이 아니라 측정으로 고치는 순서 — 병목 특정 → 우선순위 → 단계적 개선","skills":["backend","sysd","performance"],"phases":[{"t":"현황 측정 계획","type":"note","goal":"고치기 전에 <b>무엇이 느린지</b>부터 정하세요.\n어떤 지표를 어디서 볼 것인지, 무엇을 '정상'으로 볼 것인지 적어보세요.","ph":"예: p95 응답시간 / 엔드포인트별 · APM 트레이스 · DB 슬로우쿼리 · 목표: 결제 API p95 800ms 이하"},{"t":"어디부터 볼 것인가","type":"decide","goal":"전체 API p95가 300ms에서 2.4초로 악화됐습니다. 배포는 없었고 트래픽은 20% 늘었습니다.","sit":"가장 먼저 무엇을 하겠습니까?","opts":[{"label":"트레이스로 요청 시간이 어느 구간(앱·DB·외부호출)에서 쓰이는지 분해한다","fx":{"debugging":6,"performance":4},"fb":"✅ 측정이 먼저입니다. 시간이 어디서 쓰이는지 모르면 어떤 개선도 도박입니다.","best":true},{"label":"서버 대수를 2배로 늘린다","fx":{"system_design":-2,"performance":1},"fb":"❌ 병목이 DB 락이면 인스턴스를 늘려도 경합만 커집니다. 돈만 쓰고 악화될 수 있습니다.","best":false},{"label":"가장 오래된 코드를 리팩토링하기 시작한다","fx":{"coding":-2},"fb":"❌ '오래됨'과 '느림'은 다릅니다. 측정 없는 리팩토링은 위험만 늘립니다.","best":false},{"label":"캐시를 전면 도입한다","fx":{"performance":1},"fb":"⚠️ 효과가 있을 수도 있지만, 무엇을 캐시할지 모르는 상태의 전면 도입은 정합성 문제만 추가합니다.","best":false}]},{"t":"병목 지표 계산","type":"build","goal":"엔드포인트별 요청 로그에서 p95 응답시간과 총 소요시간(호출수 × 평균)을 구해, <b>개선 효과가 큰 순서</b>로 정렬하는 함수를 만드세요.","hint":"가장 느린 엔드포인트가 아니라 '느림 × 호출수'가 큰 엔드포인트가 우선순위입니다.","acc":"rank_bottlenecks가 총 소요시간 내림차순 리스트를 반환한다","sol":"def rank_bottlenecks(logs):\n    \"\"\"logs: [{'ep': str, 'ms': float}, ...]\n    반환: [{'ep', 'count', 'avg_ms', 'p95_ms', 'total_ms'}] — total_ms 내림차순\n    \"\"\"\n    by = {}\n    for r in logs:\n        by.setdefault(r['ep'], []).append(r['ms'])\n\n    out = []\n    for ep, xs in by.items():\n        xs.sort()\n        n = len(xs)\n        # p95: 하위 95% 지점 (n이 작아도 안전하게 인덱스 클램프)\n        idx = min(n - 1, int(n * 0.95))\n        out.append({\n            'ep': ep,\n            'count': n,\n            'avg_ms': sum(xs) / n,\n            'p95_ms': xs[idx],\n            'total_ms': sum(xs),      # 개선 효과의 크기 = 누적 시간\n        })\n    out.sort(key=lambda d: d['total_ms'], reverse=True)\n    return out","lang":"python"},{"t":"무엇을 먼저 고칠 것인가","type":"decide","goal":"측정 결과: 주문 목록 API가 전체 누적 시간의 62%를 차지하고, 트레이스상 시간의 대부분이 DB에서 쓰입니다. 실행 계획을 보니 목록 조회 뒤 각 주문마다 사용자 정보를 다시 조회하고 있었습니다.","sit":"어떤 개선을 먼저 하겠습니까?","opts":[{"label":"N+1 쿼리를 조인 또는 일괄 조회로 바꾼다","fx":{"database":6,"performance":4},"fb":"✅ 원인을 직접 제거하는 개선입니다. 호출 수가 O(n)에서 O(1)로 줄어 효과가 즉시·확실합니다.","best":true},{"label":"목록 결과를 통째로 캐시한다","fx":{"performance":1},"fb":"⚠️ 증상은 가려지지만 원인(N+1)은 남고, 주문은 자주 바뀌어 무효화가 어렵습니다.","best":false},{"label":"DB 인스턴스 사양을 올린다","fx":{"performance":1,"system_design":-1},"fb":"⚠️ 비용으로 시간을 사는 임시책입니다. N+1은 데이터가 늘면 다시 한계를 만듭니다.","best":false},{"label":"읽기 복제본을 추가한다","fx":{"system_design":1},"fb":"⚠️ 읽기 부하 분산에는 도움이 되지만, 쿼리 하나가 N번 나가는 구조 자체는 그대로입니다.","best":false}]},{"t":"N+1 제거 구현","type":"build","goal":"주문 목록에 사용자 이름을 붙일 때 <b>사용자당 한 번씩 조회하지 않도록</b> 일괄 조회로 바꾸세요.","hint":"필요한 user_id를 먼저 모아 중복을 제거하고, 한 번의 조회로 딕셔너리를 만든 뒤 매핑하세요.","acc":"attach_users가 조회 함수를 정확히 1회만 호출하고 이름이 채워진 주문 목록을 반환한다","sol":"def attach_users(orders, fetch_users_by_ids):\n    \"\"\"orders: [{'id','user_id',...}]\n    fetch_users_by_ids(ids) -> [{'id','name'}]  (한 번에 조회)\n    \"\"\"\n    if not orders:\n        return []\n\n    # 1) 필요한 id만 중복 제거해서 모은다\n    ids = list({o['user_id'] for o in orders})\n\n    # 2) 단 한 번의 조회 (N+1 제거의 핵심)\n    users = {u['id']: u['name'] for u in fetch_users_by_ids(ids)}\n\n    # 3) 메모리에서 매핑 — 없는 사용자도 안전하게 처리\n    return [dict(o, user_name=users.get(o['user_id'])) for o in orders]","lang":"python"},{"t":"개선을 어떻게 내보낼 것인가","type":"decide","goal":"수정을 마쳤습니다. 이 서비스는 월 500만 사용자가 쓰고 있고, 잘못되면 주문 조회 전체가 영향을 받습니다.","sit":"배포 전략을 고르세요.","opts":[{"label":"소수 트래픽에만 먼저 흘리고 지표를 비교한 뒤 점진 확대한다","fx":{"system_design":5,"leadership":3},"fb":"✅ 카나리로 실제 트래픽에서 검증하고, 문제가 있으면 영향 범위가 작을 때 되돌립니다.","best":true},{"label":"한 번에 전체 배포한다 — 테스트를 통과했으니 괜찮다","fx":{"system_design":-2},"fb":"❌ 스테이징은 실제 데이터 분포와 트래픽을 재현하지 못합니다. 되돌릴 준비 없는 전면 배포는 도박입니다.","best":false},{"label":"트래픽이 가장 적은 새벽에 전체 배포한다","fx":{"performance":1},"fb":"⚠️ 영향은 줄지만 검증 없이 전면 전환하는 건 같습니다. 문제를 늦게 발견하게 될 수도 있습니다.","best":false}]},{"t":"개선 효과 검증","type":"build","goal":"배포 전후 응답시간 표본으로 <b>개선율</b>과 목표 달성 여부를 판정하는 함수를 만드세요.","hint":"평균만 보면 꼬리 지연을 놓칩니다. p95를 함께 보세요.","acc":"compare가 before/after의 p95와 개선율, 목표 달성 여부를 반환한다","sol":"def _p95(xs):\n    xs = sorted(xs)\n    return xs[min(len(xs) - 1, int(len(xs) * 0.95))]\n\ndef compare(before_ms, after_ms, target_p95):\n    b, a = _p95(before_ms), _p95(after_ms)\n    improved = (b - a) / b * 100 if b else 0.0\n    return {\n        'p95_before': b,\n        'p95_after': a,\n        'improved_pct': round(improved, 1),\n        'meets_target': a <= target_p95,   # 목표는 배포 전에 정해둔 값\n    }","lang":"python"},{"t":"다음 병목으로","type":"decide","goal":"주문 목록 p95가 2.4초에서 420ms로 떨어졌습니다. 이제 두 번째 병목이 전체의 21%를 차지합니다.","sit":"어디까지 최적화하겠습니까?","opts":[{"label":"미리 정한 목표를 만족하면 멈추고, 남은 병목은 기록만 해둔다","fx":{"leadership":5,"system_design":3},"fb":"✅ 최적화는 끝이 없습니다. 목표를 기준으로 멈추고 남은 것은 문서로 남기는 것이 시니어의 판단입니다.","best":true},{"label":"모든 엔드포인트가 100ms 이하가 될 때까지 계속 개선한다","fx":{"performance":-1,"leadership":-2},"fb":"❌ 수익이 체감하는 지점을 넘어서면 비용이 효익을 넘습니다. 그 시간에 다른 가치를 만드는 편이 낫습니다.","best":false},{"label":"이참에 아키텍처를 전면 재설계한다","fx":{"system_design":-2},"fb":"❌ 측정으로 해결되고 있는 상황에서 전면 재설계는 위험만 키웁니다.","best":false}]},{"t":"회고","type":"note","goal":"이번 리팩토링에서 <b>측정이 바꾼 판단</b>을 3줄로 적어보세요.\n처음에 의심했던 원인과 실제 원인이 어떻게 달랐는지도 남기세요.","ph":"처음 의심 / 실제 원인 / 다음엔 어떤 지표를 먼저 볼 것인가"}]},{"lv":5,"em":"🧩","title":"마이크로서비스 전환 여부 판단","desc":"쪼갤 것인가 말 것인가 — 유행이 아니라 근거로 결정하고, 쪼갠다면 어디를 먼저 자를지 정한다","skills":["sysd","backend","leadership"],"phases":[{"t":"현재 고통 정의","type":"note","goal":"'모놀리스라서 힘들다'가 아니라 <b>구체적으로 무엇이 문제인지</b> 적으세요.\n배포 빈도, 빌드 시간, 팀 간 충돌, 장애 전파 범위 중 실제로 겪는 것을 숫자로.","ph":"예: 배포 주 1회(대기 3일) · 빌드 22분 · 팀 4개가 같은 저장소 · 한 기능 장애가 전체 다운"},{"t":"전환의 진짜 이유","type":"decide","goal":"경영진이 '요즘 다 마이크로서비스로 간다'며 전환을 지시했습니다. 팀은 8명, 서비스는 월 50만 사용자입니다.","sit":"어떻게 대응하겠습니까?","opts":[{"label":"현재 겪는 문제를 지표로 제시하고, 전환이 그 문제를 실제로 푸는지 근거로 논의한다","fx":{"leadership":6,"communication":5,"system_design":3},"fb":"✅ 아키텍처는 조직과 문제에서 나옵니다. 근거 없이 따르는 것도, 근거 없이 거부하는 것도 엔지니어링이 아닙니다.","best":true},{"label":"지시대로 즉시 전면 분리에 착수한다","fx":{"system_design":-3,"leadership":-2},"fb":"❌ 8명 팀에 분산 시스템의 운영 부담(네트워크 실패·분산 추적·데이터 정합성)을 얹으면 속도가 더 느려집니다.","best":false},{"label":"기술적으로 나쁘다고 단호히 거절한다","fx":{"communication":-2},"fb":"❌ 결론은 옳을 수 있으나 근거 없는 거절은 신뢰를 잃습니다. 데이터로 말해야 합니다.","best":false},{"label":"일단 신규 기능만 별도 서비스로 만들어 본다","fx":{"system_design":2},"fb":"⚠️ 나쁘지 않은 실험이지만, 먼저 '무슨 문제를 푸는가'에 합의하지 않으면 서비스만 늘어납니다.","best":false}]},{"t":"판단 근거 계산","type":"build","goal":"전환 여부를 <b>점수로 판단</b>하는 함수를 만드세요. 팀 규모·배포 충돌·장애 전파·도메인 경계 명확성·운영 역량을 반영합니다.","hint":"운영 역량(관측성·CI/CD·온콜)이 없으면 분리는 오히려 손해입니다 — 감점 요인으로 넣으세요.","acc":"should_split이 점수와 권고(split/keep/prepare)를 반환한다","sol":"def should_split(m):\n    \"\"\"m: {\n      'teams': int,              # 같은 코드베이스를 만지는 팀 수\n      'deploy_conflicts': int,   # 월 배포 충돌/대기 횟수\n      'blast_radius': float,     # 한 기능 장애가 전체에 영향 주는 비율 0~1\n      'clear_boundaries': bool,  # 도메인 경계가 이미 뚜렷한가\n      'ops_maturity': float,     # 관측성·CI/CD·온콜 성숙도 0~1\n    }\"\"\"\n    score = 0\n    if m['teams'] >= 3: score += 2          # 조직이 갈라지면 배포도 갈라져야 한다\n    if m['deploy_conflicts'] >= 4: score += 2\n    if m['blast_radius'] >= 0.5: score += 2\n    if m['clear_boundaries']: score += 2     # 경계가 없으면 자를 선이 없다\n\n    # 운영 역량이 낮으면 분리는 비용만 늘린다 (핵심 감점)\n    if m['ops_maturity'] < 0.5: score -= 3\n\n    if score >= 6:\n        rec = 'split'      # 근거가 충분 — 단, 한 번에 하나씩\n    elif score >= 3:\n        rec = 'prepare'    # 모듈 경계부터 정리하고 역량을 먼저 갖춘다\n    else:\n        rec = 'keep'       # 모놀리스 유지가 합리적\n    return {'score': score, 'recommendation': rec}","lang":"python"},{"t":"자른다면 어디부터","type":"decide","goal":"근거 검토 결과 '준비 후 부분 분리'로 합의했습니다. 후보는 결제, 알림, 사용자 프로필입니다.","sit":"무엇을 먼저 분리하겠습니까?","opts":[{"label":"알림 — 비동기이고 다른 도메인과 데이터 결합이 약하다","fx":{"system_design":6},"fb":"✅ 결합이 약하고 실패해도 핵심 거래를 막지 않는 것부터 자릅니다. 실패 비용이 작은 곳에서 역량을 쌓습니다.","best":true},{"label":"결제 — 가장 중요하니 먼저 안정화한다","fx":{"system_design":-2,"security":-1},"fb":"❌ 트랜잭션 정합성이 가장 까다로운 영역을 첫 분리 대상으로 삼으면 분산 트랜잭션 문제를 처음부터 마주합니다.","best":false},{"label":"사용자 프로필 — 모든 서비스가 참조하니 공통화한다","fx":{"system_design":-1},"fb":"⚠️ 모두가 참조하는 것을 떼면 모든 호출이 네트워크를 타게 되어 지연과 장애 지점이 늘어납니다.","best":false}]},{"t":"데이터 경계 결정","type":"decide","goal":"알림 서비스를 분리합니다. 알림은 주문 상태와 사용자 이메일을 필요로 합니다.","sit":"데이터를 어떻게 다루겠습니까?","opts":[{"label":"이벤트로 필요한 정보를 받아 자체 저장소에 보관한다","fx":{"system_design":6,"database":3},"fb":"✅ 서비스가 자기 데이터를 소유해야 독립 배포·독립 장애가 성립합니다. 결과적 일관성을 감수하는 대신 결합이 끊깁니다.","best":true},{"label":"알림 서비스가 주문 DB를 직접 조회한다","fx":{"system_design":-3,"database":-2},"fb":"❌ 공유 DB는 분리의 이점을 없앱니다. 스키마 변경이 두 서비스를 동시에 깨뜨립니다.","best":false},{"label":"필요할 때마다 주문 서비스 API를 동기 호출한다","fx":{"system_design":1},"fb":"⚠️ 공유 DB보다는 낫지만, 주문 서비스가 죽으면 알림도 멈추고 지연이 더해집니다.","best":false}]},{"t":"서비스 간 통신 구현","type":"build","goal":"이벤트를 받아 알림을 보낼 때 <b>중복 수신에도 한 번만 발송</b>되도록 처리하세요. 메시지 큐는 보통 at-least-once입니다.","hint":"이벤트 ID를 처리 기록에 남기고, 이미 있으면 건너뜁니다(멱등 처리).","acc":"handle_event가 같은 event_id를 여러 번 받아도 발송을 1회만 수행한다","sol":"def make_handler(send_fn):\n    processed = set()          # 실제로는 DB의 유니크 키/Redis SETNX\n\n    def handle_event(event):\n        \"\"\"event: {'id': str, 'to': str, 'text': str}\n        at-least-once 전달을 가정 — 같은 이벤트가 다시 올 수 있다.\n        \"\"\"\n        eid = event['id']\n        if eid in processed:\n            return {'sent': False, 'reason': 'duplicate'}\n\n        send_fn(event['to'], event['text'])\n        processed.add(eid)     # 발송 성공 후 기록 → 재시도 시 중복 방지\n        return {'sent': True}\n\n    return handle_event","lang":"python"},{"t":"되돌릴 수 있는가","type":"decide","goal":"분리한 알림 서비스를 실제 트래픽에 붙이려 합니다.","sit":"전환을 어떻게 하겠습니까?","opts":[{"label":"기존 경로를 유지한 채 새 서비스로 병행 발송해 결과를 비교한 뒤 전환한다","fx":{"system_design":5,"debugging":3},"fb":"✅ 실제 트래픽으로 검증하면서 언제든 되돌릴 수 있습니다. 비교 결과가 곧 전환 근거가 됩니다.","best":true},{"label":"기존 코드를 지우고 새 서비스로 한 번에 전환한다","fx":{"system_design":-2},"fb":"❌ 되돌릴 길을 먼저 지우는 전환입니다. 문제가 생기면 복구가 아니라 재개발이 됩니다.","best":false},{"label":"새 서비스로만 보내되 실패하면 로그만 남긴다","fx":{"debugging":-1},"fb":"⚠️ 조용한 실패로 알림 누락을 늦게 발견하게 됩니다.","best":false}]},{"t":"결정 기록","type":"note","goal":"이 결정을 <b>ADR(아키텍처 결정 기록)</b> 형식으로 남기세요.\n맥락 / 결정 / 근거 / 감수한 트레이드오프 / 재검토 시점 순으로 적습니다.","ph":"맥락: ... / 결정: 알림만 분리 / 근거: 결합도·실패비용 / 트레이드오프: 결과적 일관성 / 재검토: 6개월 뒤"},{"t":"회고","type":"note","goal":"'전환한다/안 한다'보다 <b>어떤 근거로 정했는가</b>가 더 중요합니다.\n이번 판단에서 가장 결정적이었던 지표 하나와, 6개월 뒤 무엇이 달라지면 결정을 뒤집을지 적으세요.","ph":"결정적 지표 / 뒤집을 조건 / 예상보다 컸던 비용"}]},{"lv":5,"em":"💰","title":"인프라 비용 40% 절감 설계","desc":"성능을 깎지 않고 비용만 줄이는 순서 — 측정 → 낭비 제거 → 구조 조정, 그리고 절감의 지속 가능성","skills":["sysd","performance","devops"],"phases":[{"t":"비용 구조 파악","type":"note","goal":"어디에 돈이 쓰이는지 <b>비중 순으로</b> 적어보세요.\n컴퓨트·DB·스토리지·네트워크(egress)·관측성 도구를 나눠서 봅니다.","ph":"예: 컴퓨트 48% · DB 27% · 스토리지 11% · egress 9% · 로그/모니터링 5%"},{"t":"어디부터 손댈 것인가","type":"decide","goal":"월 인프라 비용이 4천만원이고, 목표는 40% 절감입니다. 서비스 지연은 지금 수준을 유지해야 합니다.","sit":"첫 단계로 무엇을 하겠습니까?","opts":[{"label":"비용을 항목별로 쪼개 상위 항목의 실제 사용률을 먼저 측정한다","fx":{"performance":5,"system_design":4},"fb":"✅ 큰 항목의 낭비부터 찾는 것이 정석입니다. 사용률을 모르면 무엇이 낭비인지 알 수 없습니다.","best":true},{"label":"모든 인스턴스 사양을 일괄로 한 단계 낮춘다","fx":{"performance":-3},"fb":"❌ 여유가 없던 서비스가 먼저 무너집니다. 절감이 아니라 장애를 만드는 방법입니다.","best":false},{"label":"가장 비싼 관리형 서비스를 직접 운영으로 전환한다","fx":{"system_design":-1},"fb":"⚠️ 청구서는 줄지만 운영 인건비와 장애 위험이 늘어 총비용은 오히려 늘 수 있습니다.","best":false},{"label":"로그와 모니터링을 줄인다","fx":{"debugging":-3},"fb":"❌ 비중이 가장 작은 항목을 깎으면서 장애 대응 능력을 잃습니다. 최악의 교환입니다.","best":false}]},{"t":"낭비 찾기","type":"build","goal":"인스턴스별 사용률 데이터에서 <b>과다 프로비저닝</b>을 찾아 절감 가능액을 계산하세요.","hint":"피크 사용률에 안전 여유를 두고 필요한 사양을 역산합니다. 피크가 낮은 것만 후보입니다.","acc":"find_waste가 축소 후보와 월 절감 예상액을 반환한다","sol":"def find_waste(instances, headroom=0.4, min_saving=1):\n    \"\"\"instances: [{'name','vcpu','peak_cpu'(0~1),'monthly_cost'}]\n    headroom: 피크 위에 남겨둘 여유 비율 (0.4 = 40% 여유)\n    \"\"\"\n    out = []\n    for i in instances:\n        # 피크를 감당하면서 여유까지 둔 '필요 vCPU'\n        needed = i['peak_cpu'] * i['vcpu'] * (1 + headroom)\n        # 실제 사양은 1 vCPU 단위로 올림\n        target = max(1, -(-needed // 1))\n        if target >= i['vcpu']:\n            continue                      # 줄일 여지 없음\n        # 비용이 vCPU에 비례한다고 가정\n        saving = i['monthly_cost'] * (1 - target / i['vcpu'])\n        if saving >= min_saving:\n            out.append({\n                'name': i['name'],\n                'from_vcpu': i['vcpu'],\n                'to_vcpu': int(target),\n                'monthly_saving': round(saving, 2),\n            })\n    out.sort(key=lambda d: d['monthly_saving'], reverse=True)\n    return {'candidates': out,\n            'total_saving': round(sum(d['monthly_saving'] for d in out), 2)}","lang":"python"},{"t":"스토리지 정책 결정","type":"decide","goal":"스토리지 비용의 대부분은 2년치 원본 로그입니다. 실제 조회는 대부분 최근 2주에 집중되고, 규제상 1년 보관이 필요합니다.","sit":"어떻게 하겠습니까?","opts":[{"label":"최근은 빠른 스토리지, 오래된 것은 저렴한 보관 계층으로 옮기고 1년 후 삭제한다","fx":{"system_design":5,"performance":3},"fb":"✅ 접근 패턴에 계층을 맞추는 표준 해법입니다. 규제 요건은 지키면서 비용만 줄입니다.","best":true},{"label":"전부 삭제하고 앞으로 2주만 보관한다","fx":{"security":-3},"fb":"❌ 규제 위반입니다. 비용보다 훨씬 큰 위험을 만듭니다.","best":false},{"label":"압축률을 높여 그대로 둔다","fx":{"performance":1},"fb":"⚠️ 일부 줄지만 접근 빈도가 다른 데이터를 같은 비싼 계층에 두는 구조는 그대로입니다.","best":false}]},{"t":"절감 계획 검증","type":"build","goal":"여러 절감 항목을 합쳐 <b>목표 40%에 도달하는지</b>와 각 항목의 위험도를 함께 보여주는 계획표를 만드세요.","hint":"위험이 낮고 절감이 큰 항목부터 정렬하면 실행 순서가 됩니다.","acc":"plan이 누적 절감률과 목표 달성 여부를 반환한다","sol":"def plan(total_cost, items, target_pct=40):\n    \"\"\"items: [{'name','saving','risk'}]  risk: 'low'|'mid'|'high'\n    \"\"\"\n    order = {'low': 0, 'mid': 1, 'high': 2}\n    # 위험이 낮고 절감이 큰 것부터 실행\n    ranked = sorted(items, key=lambda d: (order[d['risk']], -d['saving']))\n\n    cum, rows = 0.0, []\n    for it in ranked:\n        cum += it['saving']\n        rows.append({**it,\n                     'cumulative': round(cum, 2),\n                     'cumulative_pct': round(cum / total_cost * 100, 1)})\n\n    pct = cum / total_cost * 100\n    return {\n        'rows': rows,\n        'total_saving': round(cum, 2),\n        'saving_pct': round(pct, 1),\n        'meets_target': pct >= target_pct,\n        # 저위험만으로 목표에 닿는지 — 닿으면 고위험 항목은 손대지 않아도 된다\n        'low_risk_only_pct': round(\n            sum(i['saving'] for i in items if i['risk'] == 'low') / total_cost * 100, 1),\n    }","lang":"python"},{"t":"절감이 성능을 해치지 않았는가","type":"decide","goal":"절감안을 적용한 뒤 일부 API의 p95가 소폭 올랐습니다. 아직 SLO 안에는 있습니다.","sit":"어떻게 판단하겠습니까?","opts":[{"label":"SLO 여유가 얼마나 남았는지 확인하고, 여유가 충분하면 유지하되 경보 기준을 조정한다","fx":{"performance":5,"system_design":4},"fb":"✅ SLO는 이런 판단을 위해 존재합니다. 여유를 소진했는지 보고 결정하며, 감시는 강화합니다.","best":true},{"label":"조금이라도 느려졌으니 절감을 전부 되돌린다","fx":{"performance":-1},"fb":"⚠️ SLO 안이라면 과잉 반응입니다. 목표 없이 '느려짐'만 보면 어떤 최적화도 못 합니다.","best":false},{"label":"SLO 안이니 신경 쓰지 않는다","fx":{"debugging":-2},"fb":"❌ 여유를 얼마나 썼는지 모른 채 두면 다음 트래픽 증가에서 한꺼번에 터집니다.","best":false}]},{"t":"절감 유지 장치","type":"decide","goal":"6개월 뒤 비용이 다시 원래대로 돌아오는 일이 흔합니다.","sit":"절감을 유지하려면 무엇이 필요할까요?","opts":[{"label":"비용을 지표로 상시 노출하고 예산 초과 시 경보가 울리게 만든다","fx":{"system_design":5,"leadership":3},"fb":"✅ 한 번의 캠페인이 아니라 지속되는 피드백 루프를 만드는 것이 핵심입니다.","best":true},{"label":"분기마다 사람이 수동으로 점검한다","fx":{"leadership":1},"fb":"⚠️ 없는 것보단 낫지만 잊히기 쉽고 발견이 늦습니다.","best":false},{"label":"비용이 오르면 그때 다시 절감 프로젝트를 한다","fx":{"leadership":-2},"fb":"❌ 같은 일을 반복하게 됩니다. 구조가 아니라 이벤트로 관리하는 방식입니다.","best":false}]},{"t":"회고","type":"note","goal":"절감액보다 중요한 것은 <b>무엇을 포기했는가</b>입니다.\n감수한 트레이드오프와, 다시 한다면 손대지 않을 항목을 적으세요.","ph":"절감액 / 감수한 것 / 건드리지 말았어야 했던 것 / 유지 장치"}]},{"lv":5,"em":"🔀","title":"무중단 데이터 마이그레이션","desc":"서비스를 멈추지 않고 저장소를 바꾸는 절차 — 이중 쓰기 · 백필 · 검증 · 컷오버 · 롤백","skills":["backend","database","sysd"],"phases":[{"t":"마이그레이션 계획","type":"note","goal":"무엇을 어디로 옮기는지, <b>되돌릴 방법</b>과 함께 적으세요.\n각 단계에서 문제가 생기면 어떻게 이전 상태로 돌아갈지가 계획의 핵심입니다.","ph":"대상 테이블 / 새 저장소 / 각 단계 롤백 방법 / 검증 기준 / 컷오버 조건"},{"t":"전환 방식 선택","type":"decide","goal":"주문 테이블(3억 행)을 새 저장소로 옮겨야 합니다. 서비스는 24시간 운영되며 중단 허용 시간은 0입니다.","sit":"어떤 방식으로 옮기겠습니까?","opts":[{"label":"양쪽에 함께 쓰면서(이중 쓰기) 과거 데이터를 백필하고, 검증 후 읽기를 전환한다","fx":{"system_design":6,"database":4},"fb":"✅ 언제든 되돌릴 수 있고 중단이 없습니다. 검증 단계에서 두 저장소를 비교할 수도 있습니다.","best":true},{"label":"점검 공지 후 서비스를 멈추고 한 번에 옮긴다","fx":{"system_design":-2},"fb":"❌ 3억 행은 시간이 오래 걸리고, 실패 시 되돌리는 데 또 그만큼 걸립니다. 중단 0 요건에도 어긋납니다.","best":false},{"label":"새 저장소에만 쓰고 조회는 두 곳을 합쳐 보여준다","fx":{"database":1},"fb":"⚠️ 중단은 없지만 조회 로직이 복잡해지고, 과거 데이터가 영원히 옛 저장소에 남습니다.","best":false}]},{"t":"이중 쓰기 구현","type":"build","goal":"쓰기를 두 저장소에 반영하되, <b>새 저장소 실패가 서비스를 멈추지 않도록</b> 만드세요.","hint":"기존 저장소가 여전히 정답(source of truth)입니다. 새 저장소 실패는 기록해두고 나중에 복구합니다.","acc":"dual_write가 새 저장소 실패 시에도 기존 쓰기를 성공시키고 실패를 기록한다","sol":"def make_dual_write(write_old, write_new, record_failure):\n    def dual_write(record):\n        # 1) 기존 저장소가 아직 정답 — 실패하면 그대로 예외를 올린다\n        write_old(record)\n\n        # 2) 새 저장소는 '아직 보조' — 실패해도 사용자 요청을 깨뜨리지 않는다\n        try:\n            write_new(record)\n            return {'old': True, 'new': True}\n        except Exception as e:\n            # 조용히 삼키지 않는다: 나중에 재처리할 수 있게 남긴다\n            record_failure({'id': record['id'], 'error': str(e)})\n            return {'old': True, 'new': False}\n\n    return dual_write","lang":"python"},{"t":"백필 전략","type":"decide","goal":"과거 3억 행을 새 저장소로 채워야 합니다. 운영 DB는 계속 트래픽을 받고 있습니다.","sit":"어떻게 백필하겠습니까?","opts":[{"label":"작은 배치로 나눠 속도를 조절하며 복사하고, 부하 지표를 보며 조절한다","fx":{"database":6,"performance":4},"fb":"✅ 운영 영향을 통제할 수 있고, 중단·재개가 자유롭습니다. 실패해도 그 배치만 다시 하면 됩니다.","best":true},{"label":"한 번의 쿼리로 전부 복사한다","fx":{"database":-3,"performance":-2},"fb":"❌ 긴 트랜잭션과 락으로 운영 쿼리가 밀리고, 중간 실패 시 처음부터 다시 해야 합니다.","best":false},{"label":"최대 속도로 병렬 복사해 빨리 끝낸다","fx":{"performance":-2},"fb":"❌ 백필이 운영 트래픽의 자원을 빼앗아 사용자 지연을 만듭니다. 빠른 게 목적이 아닙니다.","best":false}]},{"t":"백필 배치 구현","type":"build","goal":"키 범위를 나눠 <b>재시작 가능한</b> 백필을 만드세요. 중단됐다 재개해도 중복·누락이 없어야 합니다.","hint":"마지막으로 처리한 id를 커서로 저장하고, 그 다음부터 이어서 처리합니다(키셋 방식).","acc":"backfill이 커서를 갱신하며 배치 단위로 진행하고, 같은 커서에서 재개해도 중복 처리하지 않는다","sol":"def backfill(fetch_after, copy_batch, save_cursor, start_after=0,\n             batch_size=1000, max_batches=None):\n    \"\"\"fetch_after(last_id, n) -> [{'id',...}]  (id 오름차순)\n    OFFSET 대신 키셋(cursor) 방식 — 뒤로 갈수록 느려지지 않는다.\n    \"\"\"\n    last_id = start_after\n    total = 0\n    batches = 0\n\n    while True:\n        rows = fetch_after(last_id, batch_size)\n        if not rows:\n            break                     # 더 없으면 완료\n\n        copy_batch(rows)\n        last_id = rows[-1]['id']\n        save_cursor(last_id)          # 여기서 죽어도 다음에 이어서 재개\n        total += len(rows)\n\n        batches += 1\n        if max_batches and batches >= max_batches:\n            break                     # 부하를 보며 나눠 돌릴 수 있게\n\n    return {'copied': total, 'cursor': last_id}","lang":"python"},{"t":"정합성 검증","type":"build","goal":"두 저장소가 <b>실제로 같은지</b> 표본으로 비교하고 불일치를 보고하세요.","hint":"건수만 같다고 같은 게 아닙니다. 표본의 필드 값까지 비교하세요.","acc":"verify가 건수 차이와 불일치 레코드 목록을 반환한다","sol":"def verify(old_rows, new_rows, fields):\n    old = {r['id']: r for r in old_rows}\n    new = {r['id']: r for r in new_rows}\n\n    missing = sorted(set(old) - set(new))   # 새 저장소에 없음\n    extra   = sorted(set(new) - set(old))   # 새 저장소에만 있음\n\n    mismatched = []\n    for rid in set(old) & set(new):\n        diff = {f: (old[rid].get(f), new[rid].get(f))\n                for f in fields if old[rid].get(f) != new[rid].get(f)}\n        if diff:\n            mismatched.append({'id': rid, 'diff': diff})\n\n    return {\n        'count_old': len(old),\n        'count_new': len(new),\n        'missing': missing,\n        'extra': extra,\n        'mismatched': mismatched,\n        'ok': not (missing or extra or mismatched),\n    }","lang":"python"},{"t":"컷오버 판단","type":"decide","goal":"백필이 끝났고 표본 검증에서 불일치가 0.02% 나왔습니다. 원인은 아직 모릅니다.","sit":"읽기를 새 저장소로 전환하겠습니까?","opts":[{"label":"불일치 원인을 먼저 규명한다 — 작은 비율이라도 원인을 모르면 전환하지 않는다","fx":{"debugging":6,"database":4},"fb":"✅ 0.02%도 3억 행이면 6만 건입니다. 원인 불명 상태의 전환은 나중에 더 큰 사고로 돌아옵니다.","best":true},{"label":"비율이 낮으니 전환하고 이후에 맞춘다","fx":{"database":-3},"fb":"❌ 전환 후에는 어느 쪽이 옳은지 판단하기 어려워집니다. 되돌리기도 훨씬 복잡해집니다.","best":false},{"label":"불일치 건만 삭제하고 전환한다","fx":{"database":-3,"security":-1},"fb":"❌ 데이터 손실입니다. 원인을 덮는 가장 나쁜 선택입니다.","best":false}]},{"t":"롤백 준비","type":"decide","goal":"원인을 찾아 고쳤고 재검증도 통과했습니다. 이제 읽기를 전환합니다.","sit":"전환 직후를 어떻게 운영하겠습니까?","opts":[{"label":"이중 쓰기를 당분간 유지하고 읽기만 전환해, 문제 시 읽기를 즉시 되돌린다","fx":{"system_design":6},"fb":"✅ 롤백이 설정 변경 한 번으로 끝납니다. 이중 쓰기 제거는 안정화가 확인된 뒤에 합니다.","best":true},{"label":"전환과 동시에 기존 저장소 쓰기를 중단한다","fx":{"system_design":-3},"fb":"❌ 되돌릴 수단을 스스로 없앱니다. 문제가 생기면 그 사이 데이터가 옛 저장소에 없습니다.","best":false},{"label":"기존 저장소를 바로 삭제해 비용을 아낀다","fx":{"system_design":-3,"security":-2},"fb":"❌ 가장 위험한 선택입니다. 안정화 전 삭제는 복구 불가능한 상태를 만듭니다.","best":false}]},{"t":"회고","type":"note","goal":"이번 마이그레이션에서 <b>롤백 계획이 실제로 필요했던 순간</b>이 있었는지 적어보세요.\n검증에서 놓칠 뻔한 것과, 다음엔 어떤 검증을 먼저 넣을지도 남기세요.","ph":"필요했던 롤백 / 놓칠 뻔한 검증 / 다음엔 먼저 볼 것"}]}],"fullstack":[{"lv":1,"em":"💬","title":"실시간 채팅 서비스","desc":"WebSocket으로 여러 사용자가 즉시 메시지를 주고받는 채팅 서버를 만든다.","skills":["javascript","backend"],"phases":[{"t":"채팅 서비스 요구사항 정리","type":"note","goal":"실시간 채팅의 핵심 요구사항을 <b>기능/비기능</b>으로 나눠 적어보자.\n메시지 지연, 동시접속, 순서 보장을 함께 고려하라.","ph":"예: 메시지 왕복 200ms 이내, 동시접속 1천명, 순서 보장..."},{"t":"실시간 통신 방식 선택","type":"decide","goal":"브라우저와 서버가 실시간으로 메시지를 주고받아야 한다.","sit":"어떤 통신 방식을 채택할까?","opts":[{"label":"WebSocket 양방향 지속 연결","fx":{"system_design":5},"fb":"✅ 지속 연결로 저지연 양방향 통신에 가장 적합하다.","best":true},{"label":"1초마다 HTTP 폴링","fx":{"performance":-2},"fb":"❌ 불필요한 요청이 폭증하고 지연도 크다.","best":false},{"label":"이메일 알림으로 대체","fx":{"system_design":-3},"fb":"❌ 실시간 요구사항을 전혀 만족하지 못한다.","best":false}]},{"t":"WebSocket 서버 기본 구현","type":"build","goal":"ws 라이브러리로 연결을 수락하고 메시지를 수신하는 서버를 만들자.","hint":"connection 이벤트에서 소켓별 message, close 핸들러를 등록한다.","acc":"클라이언트가 접속하면 서버 로그가 찍히고 보낸 메시지가 수신된다.","sol":"const { WebSocketServer } = require('ws');\nconst wss = new WebSocketServer({ port: 8080 });\n\nwss.on('connection', (socket, req) => {\n  const ip = req.socket.remoteAddress;\n  console.log('접속:', ip);\n\n  socket.on('message', (data) => {\n    const text = data.toString();\n    console.log('수신:', text);\n  });\n\n  socket.on('close', () => {\n    console.log('연결 종료:', ip);\n  });\n});","lang":"javascript"},{"t":"전체 브로드캐스트 구현","type":"build","goal":"한 명이 보낸 메시지를 접속 중인 모든 클라이언트에게 전달하자.","hint":"wss.clients 집합을 순회하며 readyState가 OPEN인 소켓에만 보낸다.","acc":"두 브라우저 탭에서 한 쪽 메시지가 다른 쪽에 즉시 표시된다.","sol":"const { WebSocketServer, WebSocket } = require('ws');\nconst wss = new WebSocketServer({ port: 8080 });\n\nfunction broadcast(payload) {\n  const msg = JSON.stringify(payload);\n  for (const client of wss.clients) {\n    if (client.readyState === WebSocket.OPEN) {\n      client.send(msg);\n    }\n  }\n}\n\nwss.on('connection', (socket) => {\n  socket.on('message', (data) => {\n    broadcast({ text: data.toString(), ts: Date.now() });\n  });\n});","lang":"javascript"},{"t":"동시접속 부하 테스트 계획","type":"note","goal":"동시접속과 메시지 처리량을 <b>어떻게 검증</b>할지 시나리오를 적어보자.","ph":"예: 가상 유저 500명, 초당 메시지 100건, 지연 분포 측정..."},{"t":"초기 배포 구성 결정","type":"decide","goal":"채팅 서버를 프로덕션에 처음 올린다.","sit":"초기 배포 구성을 어떻게 잡을까?","opts":[{"label":"리버스 프록시 뒤 단일 노드로 시작하고 지표 관측","fx":{"system_design":4},"fb":"✅ 작게 시작해 지표를 보며 확장하는 합리적 선택.","best":true},{"label":"처음부터 10대 클러스터 구성","fx":{"performance":-2},"fb":"⚠️ 세션 공유 설계 없이 늘리면 복잡도만 커진다.","best":false},{"label":"로컬 PC를 그대로 외부에 노출","fx":{"security":-3},"fb":"❌ 보안과 가용성이 모두 위험하다.","best":false}]},{"t":"장애 1: 동시접속 급증","type":"decide","goal":"홍보 이후 동시접속이 예상의 5배로 급증하고 CPU가 100%에 근접한다.","sit":"첫 대응으로 무엇을 할까?","opts":[{"label":"수직 확장으로 급한 불을 끄고 원인 분석을 병행","fx":{"system_design":5},"fb":"✅ 가용성을 지키며 근본 원인을 파악하는 균형 대응.","best":true},{"label":"트래픽이 빠지길 기다리며 방치","fx":{"system_design":-3},"fb":"❌ 방치하면 서버가 다운되어 전면 장애로 번진다.","best":false},{"label":"부하를 줄이려 모든 로그를 끈다","fx":{"debugging":-2},"fb":"⚠️ 관측성을 잃어 다음 단계 원인 분석이 불가능해진다.","best":false}]},{"t":"장애 2: 메모리 누수로 연결 끊김","type":"decide","goal":"수직 확장 후에도 몇 시간마다 메모리가 계속 증가하다 서버가 재시작되고, 그때마다 전체 연결이 끊긴다.","sit":"연결이 끊기는 원인을 어떻게 좁힐까?","opts":[{"label":"힙 스냅샷을 떠서 해제되지 않는 소켓 참조를 추적","fx":{"debugging":5},"fb":"✅ 끊긴 소켓을 컬렉션에서 제거하지 않은 누수를 발견한다.","best":true},{"label":"메모리가 차면 주기적으로 강제 재시작","fx":{"performance":-3},"fb":"❌ 근본 원인을 덮어 사용자 연결이 계속 끊긴다.","best":false},{"label":"메모리 한도를 무한대로 올린다","fx":{"system_design":-2},"fb":"⚠️ 누수는 그대로라 더 큰 규모의 붕괴로 이어진다.","best":false}]},{"t":"장애 3: 재발 방지책 선택","type":"decide","goal":"누수는 잡았지만 단일 노드 재시작 시 여전히 전체 사용자가 끊기는 구조다.","sit":"재발을 막을 근본 대책은?","opts":[{"label":"여러 노드로 분산하고 하트비트로 죽은 연결 정리, 무중단 배포 도입","fx":{"system_design":5},"fb":"✅ 단일 장애점을 없애고 좀비 연결도 주기적으로 정리한다.","best":true},{"label":"재시작 알림 메일만 보낸다","fx":{"communication":-2},"fb":"❌ 구조적 문제를 그대로 두어 장애가 반복된다.","best":false},{"label":"사용자에게 새로고침을 안내한다","fx":{"system_design":-3},"fb":"❌ 책임을 사용자에게 전가하는 임시방편.","best":false}]},{"t":"포스트모템 작성","type":"note","goal":"이번 장애의 <b>타임라인/근본원인/조치/재발방지</b>를 정리하자.\n동시접속 급증부터 메모리 누수, 전체 연결 끊김까지의 연쇄를 서술하라.","ph":"예: 14:00 급증 → 15:30 메모리 경보 → 16:10 재시작 반복..."}]},{"lv":2,"em":"📊","title":"분석 대시보드 SaaS","desc":"대량 이벤트를 집계해 지표를 보여주는 React 기반 분석 대시보드를 만든다.","skills":["react","backend","sql"],"phases":[{"t":"분석 대시보드 요구사항 정의","type":"note","goal":"어떤 지표를 <b>누가 어떤 주기</b>로 보는지 정리하자.\n실시간성과 집계 비용의 트레이드오프를 고려하라.","ph":"예: 일별 활성 사용자, 매출 추이, 갱신 주기 5분..."},{"t":"집계 방식 결정","type":"decide","goal":"수백만 건의 이벤트에서 대시보드 지표를 계산해야 한다.","sit":"지표 집계를 어떻게 처리할까?","opts":[{"label":"원시 이벤트를 주기적으로 사전 집계 테이블에 적재","fx":{"database":5},"fb":"✅ 조회 시 부하를 낮추고 응답을 빠르게 유지한다.","best":true},{"label":"요청마다 원시 테이블을 풀스캔 집계","fx":{"performance":-3},"fb":"❌ 조회가 느리고 DB 부하가 폭증한다.","best":false},{"label":"모든 지표를 앱 메모리에 상주","fx":{"system_design":-2},"fb":"⚠️ 데이터가 커지면 메모리 초과와 정합성 문제가 생긴다.","best":false}]},{"t":"일별 활성 사용자 집계 쿼리","type":"build","goal":"이벤트 로그에서 날짜별 고유 사용자 수를 집계하는 SQL을 작성하자.","hint":"date_trunc로 일 단위로 묶고 count(distinct user_id)를 쓴다.","acc":"날짜별로 한 행씩, 중복 없는 사용자 수가 나온다.","sol":"WITH recent AS (\n  SELECT\n    user_id,\n    date_trunc('day', occurred_at) AS day\n  FROM events\n  WHERE occurred_at >= now() - interval '30 days'\n    AND event_type = 'active'\n)\nSELECT\n  day,\n  count(DISTINCT user_id) AS dau\nFROM recent\nGROUP BY day\nORDER BY day;","lang":"sql"},{"t":"추이 차트 컴포넌트","type":"build","goal":"집계 API 응답을 받아 선형 추이를 렌더하는 React 컴포넌트를 만들자.","hint":"useEffect에서 fetch하고 로딩/에러/데이터 상태를 나눠 처리한다.","acc":"마운트 시 데이터를 불러오고 로딩 표시 후 차트가 그려진다.","sol":"import { useEffect, useState } from 'react';\nimport { LineChart, Line, XAxis, YAxis, Tooltip } from 'recharts';\n\nexport function TrendChart({ metric }) {\n  const [data, setData] = useState([]);\n  const [status, setStatus] = useState('loading');\n\n  useEffect(() => {\n    fetch(`/api/metrics/${metric}`)\n      .then((r) => r.json())\n      .then((d) => { setData(d); setStatus('done'); })\n      .catch(() => setStatus('error'));\n  }, [metric]);\n\n  if (status === 'loading') return <p>불러오는 중...</p>;\n  if (status === 'error') return <p>불러오기 실패</p>;\n\n  return (\n    <LineChart width={640} height={280} data={data}>\n      <XAxis dataKey=\"day\" />\n      <YAxis />\n      <Tooltip />\n      <Line type=\"monotone\" dataKey=\"value\" />\n    </LineChart>\n  );\n}","lang":"javascript"},{"t":"지표 정합성 검증 계획","type":"note","goal":"집계 결과가 <b>원시 데이터와 일치</b>하는지 검증할 방법을 적어보자.","ph":"예: 표본 날짜 수동 카운트와 비교, 경계값 테스트..."},{"t":"집계 잡 스케줄링 결정","type":"decide","goal":"사전 집계 잡을 언제 어떻게 돌릴지 정한다.","sit":"집계 배치를 어떤 방식으로 운영할까?","opts":[{"label":"증분 집계를 5분 주기 스케줄러로 실행","fx":{"system_design":4},"fb":"✅ 새 데이터만 반영해 비용과 신선도를 함께 잡는다.","best":true},{"label":"매번 전체 기간을 재집계","fx":{"performance":-3},"fb":"❌ 데이터가 쌓일수록 배치 시간이 폭증한다.","best":false},{"label":"사용자가 버튼을 누를 때만 집계","fx":{"communication":-2},"fb":"⚠️ 첫 조회가 매우 느리고 부하가 몰린다.","best":false}]},{"t":"장애 1: 대시보드 응답 지연","type":"decide","goal":"신규 고객 온보딩 후 대시보드 로딩이 10초 이상 걸린다는 항의가 접수됐다.","sit":"무엇부터 확인할까?","opts":[{"label":"느린 쿼리 로그와 APM으로 병목 지점을 특정","fx":{"debugging":5},"fb":"✅ 위젯별 쿼리 수가 비정상적으로 많음을 발견한다.","best":true},{"label":"프론트 로딩 스피너를 더 예쁘게 바꾼다","fx":{"communication":-3},"fb":"❌ 체감만 건드릴 뿐 근본 지연은 그대로다.","best":false},{"label":"서버를 무작정 재시작한다","fx":{"system_design":-2},"fb":"⚠️ 잠깐 나아지나 곧 재발하고 원인은 미궁에 빠진다.","best":false}]},{"t":"장애 2: N+1 쿼리 폭발","type":"decide","goal":"위젯마다 사용자별로 쿼리를 반복 실행해 한 화면이 수백 개 쿼리를 날리고 있었다. DB 커넥션이 고갈된다.","sit":"쿼리 폭발을 어떻게 줄일까?","opts":[{"label":"루프 안 개별 조회를 조인이나 일괄 조회로 묶기","fx":{"database":5},"fb":"✅ 쿼리 수를 수백에서 한 자리로 줄여 부하를 해소한다.","best":true},{"label":"커넥션 풀 크기만 크게 늘린다","fx":{"performance":-3},"fb":"❌ DB로 부하를 떠넘겨 더 큰 장애를 부른다.","best":false},{"label":"타임아웃을 늘려 버틴다","fx":{"system_design":-2},"fb":"⚠️ 지연을 감출 뿐 커넥션 고갈은 계속된다.","best":false}]},{"t":"장애 3: 재발 방지와 캐싱","type":"decide","goal":"쿼리는 줄였지만 인기 지표에 조회가 몰리면 DB가 여전히 출렁인다.","sit":"반복 조회 부하를 어떻게 완화할까?","opts":[{"label":"집계 결과를 TTL 캐시에 두고 무효화 정책 수립","fx":{"performance":5},"fb":"✅ 반복 조회를 캐시로 흡수하고 신선도도 관리한다.","best":true},{"label":"모든 응답을 무기한 캐시","fx":{"database":-3},"fb":"❌ 오래된 지표가 노출되어 신뢰를 잃는다.","best":false},{"label":"캐시 없이 읽기 복제본만 추가","fx":{"system_design":-1},"fb":"⚠️ 비용만 늘고 핫 지표 부하는 그대로다.","best":false}]},{"t":"포스트모템 작성","type":"note","goal":"<b>지연 → N+1 → 커넥션 고갈</b>로 이어진 연쇄와 조치를 정리하자.\n재발 방지의 캐시 무효화 전략도 기록하라.","ph":"예: 근본원인, 감지 지표, 개선 항목..."}]},{"lv":3,"em":"📅","title":"예약 시스템(중복 예약 방지)","desc":"동시 요청에서도 같은 슬롯이 한 번만 예약되도록 정합성을 지키는 예약 서비스를 만든다.","skills":["backend","sql","system_design"],"phases":[{"t":"예약 도메인 요구사항 정리","type":"note","goal":"같은 자원에 대한 <b>중복 예약 금지</b> 규칙과 동시성 시나리오를 적어보자.\n취소/변경 시 슬롯 반환도 고려하라.","ph":"예: 같은 좌석 같은 시간대 1건만, 결제 실패 시 자동 해제..."},{"t":"중복 예약 방지 전략","type":"decide","goal":"여러 사용자가 동시에 같은 슬롯을 예약 시도한다.","sit":"중복을 어떻게 원천 차단할까?","opts":[{"label":"DB 유니크 제약과 트랜잭션으로 원자적 예약","fx":{"database":5},"fb":"✅ 경쟁 상황에서도 DB가 단일 진실로 중복을 막는다.","best":true},{"label":"예약 전 select로 존재 여부만 확인","fx":{"database":-3},"fb":"❌ 확인과 삽입 사이 경쟁으로 중복이 뚫린다.","best":false},{"label":"애플리케이션 전역 변수로 잠금","fx":{"system_design":-2},"fb":"⚠️ 다중 인스턴스에서 공유되지 않아 무력하다.","best":false}]},{"t":"예약 유니크 제약 설계","type":"build","goal":"자원과 시간대 조합에 유니크 제약을 건 예약 테이블을 만들자.","hint":"resource_id와 slot_start에 복합 유니크 인덱스를 둔다. 취소는 상태로 관리하되 활성 예약만 유니크하도록 부분 인덱스를 쓴다.","acc":"같은 자원과 시간대에 활성 예약을 두 번 삽입하면 두 번째가 실패한다.","sol":"CREATE TABLE reservations (\n  id          bigserial   PRIMARY KEY,\n  resource_id bigint      NOT NULL,\n  slot_start  timestamptz NOT NULL,\n  user_id     bigint      NOT NULL,\n  status      text        NOT NULL DEFAULT 'active',\n  created_at  timestamptz NOT NULL DEFAULT now()\n);\n\n-- 활성 예약만 자원+시간대 중복 금지\nCREATE UNIQUE INDEX uniq_active_slot\n  ON reservations (resource_id, slot_start)\n  WHERE status = 'active';","lang":"sql"},{"t":"원자적 예약 API","type":"build","goal":"트랜잭션 안에서 삽입을 시도하고 유니크 위반을 잡아 처리하는 예약 함수를 작성하자.","hint":"insert가 유니크 위반 에러(코드 23505)를 던지면 이미 예약됨으로 응답한다.","acc":"동시에 두 요청이 와도 한 건만 성공하고 나머지는 충돌로 응답한다.","sol":"async function reserve(pool, { resourceId, slotStart, userId }) {\n  const client = await pool.connect();\n  try {\n    await client.query('BEGIN');\n    const sql = `\n      INSERT INTO reservations (resource_id, slot_start, user_id)\n      VALUES ($1, $2, $3)\n      RETURNING id`;\n    const res = await client.query(sql, [resourceId, slotStart, userId]);\n    await client.query('COMMIT');\n    return { ok: true, id: res.rows[0].id };\n  } catch (err) {\n    await client.query('ROLLBACK');\n    if (err.code === '23505') {\n      return { ok: false, reason: 'already_booked' };\n    }\n    throw err;\n  } finally {\n    client.release();\n  }\n}","lang":"javascript"},{"t":"동시성 경쟁 테스트 계획","type":"note","goal":"동일 슬롯에 <b>동시 요청</b>을 퍼부어 정확히 1건만 성공하는지 검증 계획을 적어보자.","ph":"예: 병렬 100요청, 성공 1건 실패 99건 기대, 슬롯 정합성 확인..."},{"t":"예약 확정 흐름 결정","type":"decide","goal":"예약과 외부 결제를 함께 처리해야 한다.","sit":"결제와 예약 정합성을 어떻게 맞출까?","opts":[{"label":"슬롯 선점 후 결제, 실패 시 보상 트랜잭션으로 해제","fx":{"system_design":5},"fb":"✅ 슬롯을 잠시 잡고 실패하면 되돌려 정합성을 지킨다.","best":true},{"label":"결제 성공 콜백에서만 예약 삽입","fx":{"performance":-2},"fb":"⚠️ 콜백 지연 동안 다른 사용자가 먼저 채가 UX가 나빠진다.","best":false},{"label":"결제와 무관하게 무조건 예약 확정","fx":{"database":-3},"fb":"❌ 미결제 예약이 슬롯을 점유해 매출과 정합성을 해친다.","best":false}]},{"t":"장애 1: 프로모션 예약 폭주","type":"decide","goal":"한정 이벤트로 인기 슬롯에 수천 요청이 동시에 몰렸다. 응답이 급격히 느려진다.","sit":"폭주 대응을 어떻게 시작할까?","opts":[{"label":"대기열과 속도 제한으로 유입을 고르게 흡수","fx":{"system_design":5},"fb":"✅ 순간 폭주를 완충해 시스템을 보호한다.","best":true},{"label":"그냥 서버를 여러 대로 늘린다","fx":{"performance":-2},"fb":"⚠️ 같은 핫 슬롯에 대한 락 경합은 오히려 심해진다.","best":false},{"label":"이벤트를 조용히 중단한다","fx":{"communication":-3},"fb":"❌ 사업 목표를 포기하고 신뢰도 잃는다.","best":false}]},{"t":"장애 2: 락 경합과 데드락","type":"decide","goal":"핫 슬롯에 트랜잭션이 몰려 락 대기가 길어지고 일부는 데드락으로 롤백된다.","sit":"락 경합을 어떻게 완화할까?","opts":[{"label":"일관된 순서로 락을 잡고 트랜잭션 범위를 최소화","fx":{"database":5},"fb":"✅ 락 순서를 통일해 데드락을 줄이고 보유 시간을 단축한다.","best":true},{"label":"트랜잭션 격리 수준을 최하로 낮춘다","fx":{"security":-3},"fb":"❌ 정합성이 깨져 다음 단계의 중복 예약을 유발한다.","best":false},{"label":"데드락이 나면 무한 재시도","fx":{"performance":-2},"fb":"⚠️ 경합이 증폭되어 폭주가 더 악화된다.","best":false}]},{"t":"장애 3: 중복 예약 발생 대응","type":"decide","goal":"완화 과정에서 잠깐 격리 수준을 낮춘 구간에 같은 슬롯 이중 확정이 소수 발생했다. 고객 항의가 들어온다.","sit":"이미 발생한 중복을 어떻게 처리할까?","opts":[{"label":"선예약 기준으로 확정하고 후발은 보상/대체 안내 후 데이터 정정","fx":{"communication":5},"fb":"✅ 명확한 규칙으로 고객 불편을 최소화하며 데이터를 바로잡는다.","best":true},{"label":"먼저 항의한 사람에게만 유지","fx":{"communication":-3},"fb":"❌ 기준이 자의적이라 형평성 논란을 키운다.","best":false},{"label":"중복된 예약을 모두 취소한다","fx":{"system_design":-2},"fb":"⚠️ 정상 사용자까지 피해를 입어 불만이 커진다.","best":false}]},{"t":"장애 4: 재발 방지 설계","type":"decide","goal":"격리 수준을 낮추지 않고도 폭주를 견딜 근본 구조가 필요하다.","sit":"재발 방지의 핵심은?","opts":[{"label":"유니크 제약을 진실의 원천으로 유지하고 위반은 정상 흐름으로 처리, 대기열로 부하 평탄화","fx":{"system_design":6},"fb":"✅ 정합성을 절대 양보하지 않는 원칙과 완충 구조를 함께 세운다.","best":true},{"label":"다시 문제되면 격리 수준을 또 낮춘다","fx":{"database":-4},"fb":"❌ 동일 사고를 구조적으로 재발시키는 최악의 선택.","best":false},{"label":"중복 감지 배치를 야간에만 돌린다","fx":{"debugging":-2},"fb":"⚠️ 사후 탐지라 실시간 이중 확정은 막지 못한다.","best":false}]},{"t":"포스트모템 작성","type":"note","goal":"<b>폭주 → 락 경합 → 격리 완화 → 중복 예약</b> 연쇄를 타임라인으로 정리하자.\n정합성 원칙을 지키는 재발 방지책을 명시하라.","ph":"예: 근본원인=격리 수준 임의 하향, 조치=대기열 도입..."}]},{"lv":4,"em":"🔔","title":"대규모 알림 시스템","desc":"큐 기반으로 대량 이벤트를 받아 멱등하게 알림을 전송하는 시스템을 만든다.","skills":["backend","system_design","devops"],"phases":[{"t":"알림 시스템 요구사항 정리","type":"note","goal":"채널(푸시/이메일/SMS)별 <b>전송 보장 수준</b>과 처리량 목표를 적어보자.\n중복 발송 방지와 재시도 정책도 고려하라.","ph":"예: 최소 1회 전송, 피크 초당 5만 건, 중복 억제..."},{"t":"발송 파이프라인 설계","type":"decide","goal":"이벤트 발생과 실제 알림 전송을 연결해야 한다.","sit":"발송을 어떤 구조로 처리할까?","opts":[{"label":"메시지 큐를 두고 컨슈머가 비동기로 발송","fx":{"system_design":5},"fb":"✅ 생산과 소비를 분리해 폭주를 완충하고 확장한다.","best":true},{"label":"API 요청 안에서 동기로 즉시 발송","fx":{"performance":-3},"fb":"❌ 외부 채널 지연이 그대로 사용자 요청을 막는다.","best":false},{"label":"크론으로 1시간마다 일괄 발송","fx":{"system_design":-2},"fb":"⚠️ 실시간 요구를 못 맞추고 배치가 비대해진다.","best":false}]},{"t":"이벤트 발행 프로듀서","type":"build","goal":"도메인 이벤트를 알림 큐에 발행하는 프로듀서를 작성하자.","hint":"이벤트에 멱등 키(dedupKey)를 실어 발행한다.","acc":"이벤트가 발생하면 큐에 메시지가 쌓이고 멱등 키가 포함된다.","sol":"const { randomUUID } = require('crypto');\n\nasync function publishNotification(queue, event) {\n  const dedupKey = `${event.type}:${event.userId}:${event.entityId}`;\n  const message = {\n    id: randomUUID(),\n    dedupKey,\n    channel: event.channel,\n    payload: event.payload,\n    createdAt: Date.now(),\n  };\n  await queue.send(JSON.stringify(message), { key: dedupKey });\n  return message.id;\n}","lang":"javascript"},{"t":"멱등 컨슈머 구현","type":"build","goal":"같은 이벤트를 두 번 받아도 한 번만 발송하는 컨슈머를 작성하자.","hint":"dedup 키를 저장소에 원자적으로 기록(SET NX)해 이미 처리됐으면 건너뛴다.","acc":"동일 키 메시지를 두 번 소비해도 실제 발송은 1회만 일어난다.","sol":"async function handleMessage(redis, sender, raw) {\n  const msg = JSON.parse(raw);\n  // 멱등: 최초 1회만 SET 성공 (24시간 유지)\n  const first = await redis.set(\n    `sent:${msg.dedupKey}`, '1', 'EX', 86400, 'NX'\n  );\n  if (first === null) {\n    return { status: 'skipped_duplicate' };\n  }\n  try {\n    await sender.deliver(msg.channel, msg.payload);\n    return { status: 'delivered' };\n  } catch (err) {\n    // 발송 실패 시 다음 재시도가 처리하도록 멱등 키 해제\n    await redis.del(`sent:${msg.dedupKey}`);\n    throw err;\n  }\n}","lang":"javascript"},{"t":"부하와 중복 시나리오 테스트 계획","type":"note","goal":"재시도로 <b>중복 전달</b>이 발생해도 사용자에게는 1회만 가는지 검증 계획을 적어보자.","ph":"예: 동일 이벤트 3회 주입, 실제 발송 1회 확인, 재시도 폭풍 재현..."},{"t":"컨슈머 스케일링 정책 결정","type":"decide","goal":"트래픽 변동이 큰 발송 워크로드를 운영한다.","sit":"컨슈머를 어떻게 확장할까?","opts":[{"label":"큐 적체 길이 기반 오토스케일링","fx":{"system_design":4},"fb":"✅ 백로그 신호로 소비 능력을 수요에 맞춰 늘린다.","best":true},{"label":"CPU 사용률만 보고 스케일","fx":{"performance":-2},"fb":"⚠️ I/O 대기형 발송에선 적체를 제때 잡지 못한다.","best":false},{"label":"고정 대수로만 운영","fx":{"system_design":-3},"fb":"❌ 피크에 적체가 무한정 쌓인다.","best":false}]},{"t":"장애 1: 이벤트 폭증과 큐 적체","type":"decide","goal":"마케팅 대량 발송으로 이벤트가 평소의 20배로 쏟아지고 큐 적체가 급증한다.","sit":"적체 초기 대응은?","opts":[{"label":"오토스케일로 컨슈머를 늘리고 우선순위 큐로 중요 알림 먼저 처리","fx":{"system_design":5},"fb":"✅ 소비 능력을 키우고 중요 알림의 지연을 막는다.","best":true},{"label":"프로듀서를 즉시 전면 차단","fx":{"communication":-3},"fb":"❌ 정상 알림까지 끊겨 더 큰 혼란을 부른다.","best":false},{"label":"큐 메시지를 임의로 폐기","fx":{"system_design":-3},"fb":"❌ 알림 유실로 사용자 피해가 발생한다.","best":false}]},{"t":"장애 2: 컨슈머 지연 심화","type":"decide","goal":"외부 푸시 게이트웨이 응답이 느려지며 컨슈머가 한 건씩 오래 붙잡혀 처리량이 급락한다.","sit":"컨슈머 지연을 어떻게 풀까?","opts":[{"label":"타임아웃과 서킷브레이커, 재시도 백오프로 느린 채널을 격리","fx":{"system_design":5},"fb":"✅ 느린 외부 채널이 전체를 마비시키지 않도록 차단한다.","best":true},{"label":"타임아웃 없이 무한 대기","fx":{"performance":-3},"fb":"❌ 컨슈머가 묶여 적체가 폭증하고 재시도가 쌓인다.","best":false},{"label":"실패분을 즉시 무제한 재시도","fx":{"system_design":-2},"fb":"⚠️ 재시도 폭풍으로 게이트웨이를 더 밀어붙인다.","best":false}]},{"t":"장애 3: 중복 발송 폭발","type":"decide","goal":"지연과 재시도가 겹치며 멱등 키 기록 전에 재처리가 일어나 같은 알림이 여러 번 발송됐다. 사용자 항의가 쏟아진다.","sit":"중복 발송을 어떻게 멈출까?","opts":[{"label":"발송 직전 원자적 멱등 체크를 강제하고 이미 발송분은 억제","fx":{"system_design":6},"fb":"✅ 발송의 최종 관문에서 원자적으로 중복을 차단한다.","best":true},{"label":"사용자에게 사과 메일을 또 보낸다","fx":{"communication":-3},"fb":"❌ 알림 폭탄에 알림을 더해 불만을 키운다.","best":false},{"label":"중복은 어쩔 수 없다며 방치","fx":{"leadership":-3},"fb":"❌ 신뢰 하락을 방치하는 무책임한 대응.","best":false}]},{"t":"장애 4: 재발 방지 체계","type":"decide","goal":"폭주와 지연, 중복이 다시 겹쳐도 안전하도록 구조를 다잡아야 한다.","sit":"재발 방지의 핵심 조치는?","opts":[{"label":"멱등 키 저장을 발송과 원자적으로 묶고 백프레셔, 서킷브레이커, DLQ를 표준화","fx":{"system_design":6},"fb":"✅ 완충과 격리, 정확히 1회에 가까운 처리를 구조로 보장한다.","best":true},{"label":"컨슈머 수만 상시 최대로 고정","fx":{"performance":-3},"fb":"❌ 비용만 늘고 지연과 중복의 근본 원인은 남는다.","best":false},{"label":"장애 시마다 수동으로 큐를 비운다","fx":{"system_design":-2},"fb":"⚠️ 사람 개입에 의존해 야간과 주말에 취약하다.","best":false}]},{"t":"포스트모템 작성","type":"note","goal":"<b>폭증 → 적체 → 컨슈머 지연 → 중복 발송</b>의 연쇄와 조치를 정리하자.\n멱등성과 백프레셔로 재발을 막는 방안을 기록하라.","ph":"예: 감지 지표=적체 길이·발송 지연, 액션 아이템..."}]},{"lv":5,"em":"🌍","title":"글로벌 소셜 피드","desc":"편향된 팔로워 분포와 글로벌 지연을 견디는 대규모 소셜 홈 타임라인을 설계한다.","skills":["backend","sql","system_design"],"phases":[{"t":"소셜 피드 요구사항 정리","type":"note","goal":"홈 타임라인의 <b>지연/정합성/규모</b> 목표를 적어보자.\n팔로워 분포의 편향(셀럽 문제)을 고려하라.","ph":"예: 타임라인 200ms 이내, 최종적 일관성 허용, 팔로워 수 편차 큼..."},{"t":"타임라인 생성 전략 결정","type":"decide","goal":"사용자가 팔로우한 사람들의 게시물을 홈 피드로 모아야 한다.","sit":"타임라인을 어떻게 구성할까?","opts":[{"label":"일반 사용자는 쓰기 시 팬아웃, 셀럽은 읽기 시 병합하는 하이브리드","fx":{"system_design":6},"fb":"✅ 대다수는 빠른 읽기, 셀럽 폭발은 읽기 병합으로 완충하는 균형.","best":true},{"label":"모든 게시물을 항상 쓰기 시 전체 팬아웃","fx":{"performance":-3},"fb":"❌ 셀럽 1건이 수백만 쓰기를 유발해 폭발한다.","best":false},{"label":"매 조회마다 팔로이 전체를 실시간 조인","fx":{"database":-2},"fb":"⚠️ 팔로우가 많으면 조회가 무거워 확장이 어렵다.","best":false}]},{"t":"읽기 경로 타임라인 쿼리","type":"build","goal":"특정 사용자가 팔로우한 대상들의 최근 게시물을 시간순으로 가져오는 SQL을 작성하자.","hint":"follows와 posts를 조인하고 created_at 인덱스로 정렬하며 커서 페이지네이션을 쓴다.","acc":"지정 커서 이전의 최신 게시물 N건이 시간 역순으로 나온다.","sol":"-- $1: 조회 사용자, $2: 커서(마지막으로 본 게시물 시각)\nSELECT\n  p.id,\n  p.author_id,\n  p.body,\n  p.created_at\nFROM follows f\nJOIN posts p\n  ON p.author_id = f.followee_id\nWHERE f.follower_id = $1\n  AND p.created_at < $2\nORDER BY p.created_at DESC\nLIMIT 50;","lang":"sql"},{"t":"쓰기 시 팬아웃 서비스","type":"build","goal":"게시물 작성 시 팔로워 타임라인에 삽입하되, 팔로워가 많으면 팬아웃을 건너뛰는 로직을 작성하자.","hint":"팔로워 수가 임계치를 넘으면 팬아웃하지 않고 셀럽으로 표시해 읽기 병합에 맡긴다.","acc":"일반 사용자는 팔로워 피드에 삽입되고, 셀럽은 팬아웃을 생략한다.","sol":"const CELEB_THRESHOLD = 100000;\n\nasync function fanOutOnWrite(db, post) {\n  const { rows } = await db.query(\n    'SELECT count(*)::int AS n FROM follows WHERE followee_id = $1',\n    [post.authorId]\n  );\n  const followerCount = rows[0].n;\n\n  if (followerCount > CELEB_THRESHOLD) {\n    await db.query(\n      'UPDATE users SET is_celebrity = true WHERE id = $1',\n      [post.authorId]\n    );\n    return { fannedOut: false, reason: 'celebrity' };\n  }\n\n  await db.query(\n    `INSERT INTO timelines (owner_id, post_id, created_at)\n     SELECT follower_id, $1, $2 FROM follows WHERE followee_id = $3`,\n    [post.id, post.createdAt, post.authorId]\n  );\n  return { fannedOut: true, followerCount };\n}","lang":"javascript"},{"t":"편향 분포 부하 테스트 계획","type":"note","goal":"<b>셀럽 게시</b> 시 시스템이 어떻게 반응하는지 검증 계획을 적어보자.","ph":"예: 팔로워 500만 계정 게시, 쓰기 증폭과 복제 지연 측정..."},{"t":"글로벌 지연 최적화 결정","type":"decide","goal":"여러 대륙의 사용자가 같은 피드를 본다.","sit":"글로벌 읽기 지연을 어떻게 낮출까?","opts":[{"label":"지역별 읽기 복제본과 엣지 캐시로 근접 서빙","fx":{"system_design":5},"fb":"✅ 사용자 근처에서 읽어 지연을 크게 낮춘다.","best":true},{"label":"단일 리전에서 전 세계에 직접 서빙","fx":{"performance":-3},"fb":"❌ 원거리 사용자의 지연이 매우 커진다.","best":false},{"label":"모든 지역에 쓰기까지 동기로 복제","fx":{"system_design":-2},"fb":"⚠️ 쓰기 지연과 비용이 급증한다.","best":false}]},{"t":"장애 1: 셀럽 게시 팬아웃 폭발","type":"decide","goal":"임계치 설정 오류로 팔로워 800만 계정이 쓰기 팬아웃 경로를 타 수백만 삽입이 한꺼번에 발생했다.","sit":"폭주 삽입을 어떻게 막을까?","opts":[{"label":"즉시 셀럽 임계치를 적용해 팬아웃 중단, 읽기 병합으로 전환","fx":{"system_design":5},"fb":"✅ 쓰기 증폭을 끊고 읽기 경로로 부하를 옮긴다.","best":true},{"label":"쓰기 워커만 계속 늘린다","fx":{"performance":-3},"fb":"❌ 근본 증폭은 그대로라 DB 쓰기 부하가 폭발한다.","best":false},{"label":"해당 게시물을 삭제해버린다","fx":{"communication":-3},"fb":"❌ 사용자 콘텐츠를 임의 삭제해 신뢰를 잃는다.","best":false}]},{"t":"장애 2: 쓰기 지연과 복제 지체","type":"decide","goal":"대량 삽입으로 프라이머리 쓰기가 밀리고 읽기 복제본 지연이 수십 초로 벌어졌다.","sit":"복제 지연을 어떻게 다룰까?","opts":[{"label":"비필수 쓰기를 백그라운드 큐로 흘리고 지연 모니터링과 읽기 라우팅 조정","fx":{"system_design":5},"fb":"✅ 쓰기 부하를 평탄화하고 신선도 요구에 맞게 읽기를 라우팅한다.","best":true},{"label":"모든 읽기를 프라이머리로 몰아준다","fx":{"performance":-3},"fb":"❌ 프라이머리가 과부하되어 전면 장애로 번진다.","best":false},{"label":"복제 지연 경보를 꺼버린다","fx":{"debugging":-2},"fb":"⚠️ 관측성을 잃어 다음 정합성 문제를 놓친다.","best":false}]},{"t":"장애 3: 피드 정합성과 캐시 스탬피드","type":"decide","goal":"복제 지연 중 캐시가 만료되며 같은 키에 요청이 몰려 재계산이 폭주하고, 일부 사용자는 뒤죽박죽 피드를 본다.","sit":"정합성과 스탬피드를 어떻게 잡을까?","opts":[{"label":"캐시 재계산에 단일 비행 잠금과 stale-while-revalidate 적용","fx":{"performance":6},"fb":"✅ 중복 재계산을 막고 낡은 값을 잠깐 제공하며 갱신한다.","best":true},{"label":"캐시 TTL을 0으로 낮춘다","fx":{"system_design":-3},"fb":"❌ 매 요청이 재계산되어 스탬피드가 상시화된다.","best":false},{"label":"정합성은 포기하고 아무 값이나 반환","fx":{"database":-3},"fb":"❌ 사용자 신뢰를 무너뜨리는 선택.","best":false}]},{"t":"장애 4: 재발 방지 아키텍처","type":"decide","goal":"임계치 오류와 복제 지연, 캐시 스탬피드가 다시 겹치지 않도록 구조를 정비해야 한다.","sit":"재발 방지의 핵심은?","opts":[{"label":"하이브리드 팬아웃 임계치를 검증·자동화하고 백프레셔, 읽기 병합, 캐시 보호를 표준화","fx":{"system_design":6},"fb":"✅ 편향 분포를 전제로 한 방어를 구조에 내재화한다.","best":true},{"label":"다음에 문제되면 캐시를 다시 끈다","fx":{"performance":-4},"fb":"❌ 동일 스탬피드를 재발시키는 최악의 선택.","best":false},{"label":"셀럽 계정을 서비스에서 제외한다","fx":{"leadership":-3},"fb":"❌ 핵심 사용자를 배제하는 비현실적 대응.","best":false}]},{"t":"포스트모템 작성","type":"note","goal":"<b>팬아웃 폭발 → 쓰기·복제 지연 → 캐시 스탬피드</b> 연쇄를 정리하자.\n하이브리드 팬아웃과 캐시 보호로 재발을 막는 방안을 기록하라.","ph":"예: 근본원인=임계치 설정 오류, 액션 아이템..."}]},{"lv":1,"em":"🎨","title":"랜딩 페이지","desc":"시맨틱 HTML + CSS로 반응형 랜딩페이지를 앱에서 직접 만들고 미리보기","skills":["web"],"phases":[{"t":"요구사항 정의","type":"note","goal":"이 랜딩페이지가 <b>누구에게 무엇을</b> 전달할지와 꼭 넣을 3개 섹션을 적어보세요. 좋은 개발은 코드가 아니라 문제 정의에서 시작합니다.","ph":"예) 대상: 동네 카페 사장 · 목표: 예약 유도 · 섹션: 히어로/메뉴/예약CTA"},{"t":"개발 (마크업·레이아웃)","type":"web","goal":"아래 코드를 편집해 <b>▶ 실행</b>으로 미리보고, <b>✓ 채점</b>을 눌러 통과시키세요. header·큰 제목(h1)·행동유도 button이 있고 <b>flex/grid</b> 레이아웃을 써야 합니다.","hint":"header/section 시맨틱 태그와 display:flex를 활용하세요.","starter":"<!doctype html>\n<html><head><style>\n  body{font-family:sans-serif;margin:0}\n  header{display:flex;justify-content:space-between;align-items:center;padding:16px 24px;background:#111;color:#fff}\n  .hero{display:flex;flex-direction:column;align-items:center;gap:14px;padding:56px 24px;text-align:center;background:#f5f5f7}\n  .btn{background:#5b6cff;color:#fff;border:none;padding:12px 22px;border-radius:10px;font-size:16px}\n</style></head>\n<body>\n  <header><strong>MyCafe</strong><nav>메뉴 · 예약</nav></header>\n  <section class=\"hero\">\n    <h1>도심 속 조용한 커피</h1>\n    <p>여기에 소개 문구를 바꿔보세요.</p>\n    <button class=\"btn\">예약하기</button>\n  </section>\n</body></html>","checks":[{"k":"dom","sel":"header","desc":"header 태그가 있다"},{"k":"dom","sel":"h1","desc":"큰 제목(h1)이 있다"},{"k":"dom","sel":"button,.btn","desc":"행동 유도 버튼(CTA)이 있다"},{"k":"src","has":["flex","grid"],"desc":"flex 또는 grid 레이아웃을 사용했다"}]},{"t":"접근성 개선","type":"web","goal":"이미지에 <b>alt</b>를 넣고 시맨틱 구조를 유지하세요. 접근성은 나중이 아니라 처음부터 챙기는 겁니다.","hint":"img 태그에 alt=\"설명\"을 추가하세요.","starter":"<!doctype html>\n<html><head><style>body{font-family:sans-serif}main{max-width:720px;margin:auto;padding:24px}</style></head>\n<body>\n  <main>\n    <h1>우리 카페 이야기</h1>\n    <!-- 이 이미지에 alt를 넣어 접근성을 높이세요 -->\n    <img src=\"cafe.jpg\" width=\"200\">\n    <p>편안한 공간에서 스페셜티 커피를 즐기세요.</p>\n  </main>\n</body></html>","checks":[{"k":"src","has":"alt=","desc":"이미지에 alt 속성이 있다"},{"k":"dom","sel":"main","desc":"시맨틱 영역(main)이 있다"}]},{"t":"회고 (Retro)","type":"note","goal":"무엇을 배웠고, 다시 만든다면 무엇을 다르게 할지 3줄로 적어보세요.","ph":"배운 점 / 아쉬운 점 / 다음엔..."}]},{"lv":2,"em":"✅","title":"Todo 앱 (바닐라 JS)","desc":"DOM·이벤트·localStorage로 상태를 관리하는 앱을 직접 실행하며 완성","skills":["javascript","web"],"phases":[{"t":"요구사항 정의","type":"note","goal":"Todo 앱의 핵심 기능 목록과 상태(무엇을 저장할지)를 적어보세요.","ph":"추가/삭제/완료토글/새로고침 후 유지..."},{"t":"설계 결정: 상태 저장 방식","type":"decide","goal":"새로고침해도 할 일이 남아야 합니다. 어디에 저장할까요?","sit":"할 일 데이터를 어디에 보관할지 결정하세요.","opts":[{"label":"localStorage에 JSON으로 저장한다","fx":{"coding":4,"system_design":3},"fb":"✅ 서버 없이 브라우저에 영속 저장돼 새로고침에도 유지됩니다. 이 규모엔 가장 단순·적절.","best":true},{"label":"자바스크립트 변수(메모리)에만 담는다","fx":{"coding":-1},"fb":"❌ 새로고침하면 사라집니다. 요구사항(유지)을 못 지킵니다.","best":false},{"label":"당장 백엔드 서버 + DB를 만든다","fx":{"system_design":-1},"fb":"⚠️ 이 규모엔 과합니다. 오버엔지니어링은 비용만 키웁니다.","best":false}]},{"t":"개발 (추가·표시)","type":"web","goal":"아래 스켈레톤을 완성하세요. 입력창·추가버튼·목록(ul)이 있고, <b>addEventListener</b>로 항목을 추가하며 <b>localStorage</b>에 저장해야 합니다. ▶ 실행으로 직접 눌러보고 ✓ 채점하세요.","hint":"form submit 또는 button click에 addEventListener, 렌더 후 localStorage.setItem으로 저장.","starter":"<!doctype html>\n<html><head><style>\n  body{font-family:sans-serif;max-width:420px;margin:24px auto}\n  li{padding:6px 0}\n</style></head>\n<body>\n  <h1>할 일</h1>\n  <input id=\"field\" placeholder=\"할 일 입력\">\n  <button id=\"add\">추가</button>\n  <ul id=\"list\"></ul>\n<script>\n  const list=document.getElementById('list');\n  let todos=JSON.parse(localStorage.getItem('todos')||'[]');\n  function render(){ list.innerHTML=''; todos.forEach(t=>{ const li=document.createElement('li'); li.textContent=t; list.appendChild(li); }); localStorage.setItem('todos', JSON.stringify(todos)); }\n  document.getElementById('add').addEventListener('click', ()=>{\n    const v=document.getElementById('field').value.trim();\n    if(!v) return;\n    todos.push(v); document.getElementById('field').value='';\n    render();\n  });\n  render();\n</script>\n</body></html>","checks":[{"k":"dom","sel":"input","desc":"입력창이 있다"},{"k":"dom","sel":"button","desc":"추가 버튼이 있다"},{"k":"dom","sel":"ul,ol","desc":"목록 컨테이너(ul)가 있다"},{"k":"src","has":"addeventlistener","desc":"이벤트 리스너를 등록했다"},{"k":"src","has":"localstorage","desc":"localStorage로 저장한다"}]},{"t":"개선: 완료 토글·필터","type":"web","goal":"항목을 클릭하면 완료 표시(취소선)되도록 개선하세요. 상태에 완료여부를 넣고 <b>completed</b> 개념을 다뤄보세요.","hint":"각 todo를 {text, done} 객체로 바꾸고, 클릭 시 done을 토글해 스타일을 바꾸세요.","starter":"<!doctype html>\n<html><head><style>\n  body{font-family:sans-serif;max-width:420px;margin:24px auto}\n  li{padding:6px 0;cursor:pointer}\n  li.done{text-decoration:line-through;color:#999}\n</style></head>\n<body>\n  <h1>할 일</h1>\n  <ul id=\"list\"></ul>\n<script>\n  // {text, done} 구조로 바꾸고 클릭으로 done을 토글하세요\n  const todos=[{text:'우유 사기',done:false},{text:'운동',done:true}];\n  const list=document.getElementById('list');\n  todos.forEach((t,i)=>{ const li=document.createElement('li'); li.textContent=t.text; if(t.done) li.classList.add('done'); li.addEventListener('click',()=>{ t.done=!t.done; li.classList.toggle('done'); }); list.appendChild(li); });\n</script>\n</body></html>","checks":[{"k":"src","has":"done","desc":"완료 여부(done) 상태를 다룬다"},{"k":"src","has":["toggle","classlist"],"desc":"완료 표시를 토글한다"},{"k":"count","sel":"li","min":1,"desc":"목록 항목이 렌더된다"}]},{"t":"회고","type":"note","goal":"이벤트 위임, 상태-뷰 동기화에서 배운 점을 적어보세요.","ph":"..."}]},{"lv":3,"em":"⚛️","title":"데이터 대시보드","desc":"데이터 배열로 카드/차트를 렌더하는 대시보드를 앱에서 구현","skills":["javascript","web"],"phases":[{"t":"요구사항 정의","type":"note","goal":"어떤 지표를 누구에게 보여줄 대시보드인가요? 핵심 지표 3개를 정하세요.","ph":"매출·활성사용자·전환율..."},{"t":"아키텍처: 컴포넌트 분리","type":"decide","goal":"화면을 어떻게 구성할까요?","sit":"카드 6개와 목록을 그리는 화면의 구조 결정.","opts":[{"label":"데이터 배열 → 재사용 렌더 함수로 카드를 반복 생성한다","fx":{"coding":5,"system_design":3},"fb":"✅ 데이터 주도 렌더. 항목이 늘어도 코드가 안 늘고 유지보수가 쉽습니다.","best":true},{"label":"카드 6개를 HTML에 하나씩 하드코딩한다","fx":{"coding":-1},"fb":"❌ 데이터가 바뀌면 전부 수정해야 합니다. 반복 렌더로 뽑아야 합니다.","best":false},{"label":"거대한 함수 하나에 모든 렌더를 몰아넣는다","fx":{"coding":-1},"fb":"⚠️ 동작은 하지만 책임이 뒤섞여 변경이 어려워집니다.","best":false}]},{"t":"개발 (데이터 렌더)","type":"web","goal":"metrics 배열을 순회해 카드를 <b>동적으로</b> 생성하세요. 카드가 최소 3개 렌더되고 grid 레이아웃을 써야 합니다.","hint":"metrics.map 또는 forEach로 카드 DOM을 만들어 grid 컨테이너에 append.","starter":"<!doctype html>\n<html><head><style>\n  body{font-family:sans-serif;margin:20px}\n  #grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}\n  .card{padding:16px;border:1px solid #ddd;border-radius:12px}\n  .v{font-size:24px;font-weight:800}\n</style></head>\n<body>\n  <h1>대시보드</h1>\n  <div id=\"grid\"></div>\n<script>\n  const metrics=[{name:'매출',v:'₩12.4M'},{name:'활성 사용자',v:'8,210'},{name:'전환율',v:'3.2%'}];\n  const grid=document.getElementById('grid');\n  metrics.forEach(m=>{ const c=document.createElement('div'); c.className='card'; c.innerHTML='<div>'+m.name+'</div><div class=\"v\">'+m.v+'</div>'; grid.appendChild(c); });\n</script>\n</body></html>","checks":[{"k":"count","sel":".card,article,.metric","min":3,"desc":"카드가 3개 이상 렌더된다"},{"k":"src","has":["foreach","map"],"desc":"데이터를 순회해 동적 생성한다"},{"k":"src","has":"grid","desc":"grid 레이아웃을 사용한다"}]},{"t":"성능: 리렌더 최소화","type":"decide","goal":"실시간으로 값이 자주 갱신됩니다. 어떻게 그릴까요?","sit":"1초마다 지표가 바뀌는 대시보드의 렌더 전략.","opts":[{"label":"바뀐 값의 텍스트만 갱신한다(부분 업데이트)","fx":{"performance":5,"coding":3},"fb":"✅ 전체 DOM을 다시 그리지 않아 깜빡임·비용이 줄어듭니다.","best":true},{"label":"매 틱마다 전체 grid.innerHTML을 새로 만든다","fx":{"performance":-2},"fb":"❌ 잦은 전체 리렌더는 느리고 포커스·스크롤도 튑니다.","best":false},{"label":"갱신 주기를 무시하고 새로고침을 안내한다","fx":{"system_design":-1},"fb":"⚠️ 실시간 요구를 포기하는 셈입니다.","best":false}]},{"t":"회고","type":"note","goal":"데이터 주도 렌더와 성능 트레이드오프에서 배운 점을 적어보세요.","ph":"..."}]},{"lv":4,"em":"🔌","title":"풀스택 CRUD 서비스","desc":"요구사항→API 설계→스키마→개발→배포→장애→개선→회고 전 과정","skills":["backend","sql","react"],"phases":[{"t":"요구사항 정의","type":"note","goal":"만들 CRUD 서비스의 리소스와 사용자 스토리를 적어보세요. (예: 게시글 작성/조회/수정/삭제)","ph":"리소스: posts · 스토리: 사용자는 글을 쓰고 목록을 본다..."},{"t":"API 설계","type":"decide","goal":"목록 조회 API의 페이지네이션 방식은?","sit":"수백만 건이 쌓일 목록의 페이징 전략.","opts":[{"label":"키셋(cursor) 페이지네이션 — 마지막 id 이후를 조회","fx":{"system_design":5,"database":4},"fb":"✅ 깊은 페이지에서도 OFFSET 스캔 비용이 없어 일정하게 빠릅니다.","best":true},{"label":"OFFSET/LIMIT로 페이지 번호 방식","fx":{"database":-1},"fb":"⚠️ 뒤 페이지로 갈수록 OFFSET이 커져 느려집니다. 대규모엔 부적합.","best":false},{"label":"한 번에 전부 내려주고 프론트에서 자른다","fx":{"system_design":-3},"fb":"❌ 데이터가 커지면 응답·메모리가 폭발합니다.","best":false}]},{"t":"DB 스키마 설계","type":"build","goal":"posts 테이블을 설계하세요. 기본키, 작성시각, 인덱스를 고려합니다.","hint":"자주 조회하는 컬럼(예: created_at)에 인덱스. 키셋 페이징을 위한 정렬 키를 생각하세요.","acc":"PK·필수 컬럼·created_at·조회용 인덱스가 있으면 완료.","lang":"sql","sol":"CREATE TABLE posts (\n  id          BIGSERIAL PRIMARY KEY,\n  title       TEXT NOT NULL,\n  body        TEXT NOT NULL,\n  author_id   BIGINT NOT NULL REFERENCES users(id),\n  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n-- 키셋 페이지네이션(최신순)을 위한 인덱스\nCREATE INDEX idx_posts_created_id ON posts (created_at DESC, id DESC);\n\n-- 조회: 마지막으로 본 (created_at,id) 이후 20건\nSELECT id, title, created_at FROM posts\nWHERE (created_at, id) < ($1, $2)\nORDER BY created_at DESC, id DESC\nLIMIT 20;"},{"t":"개발 (API 핸들러)","type":"build","goal":"목록·생성 엔드포인트를 구현하세요. 입력 검증과 표준 에러 응답을 포함합니다.","hint":"FastAPI면 pydantic 모델로 검증, 커서는 쿼리 파라미터로 받으세요.","acc":"생성 시 검증, 목록 시 키셋 커서 처리가 되면 완료.","lang":"python","sol":"from fastapi import FastAPI, HTTPException, Query\nfrom pydantic import BaseModel, constr\n\napp = FastAPI()\n\nclass PostIn(BaseModel):\n    title: constr(min_length=1, max_length=200)\n    body: constr(min_length=1)\n\n@app.post('/posts', status_code=201)\ndef create_post(p: PostIn):\n    # pydantic이 이미 검증함 -> 저장 후 생성물 반환\n    return repo.insert(p.title, p.body)\n\n@app.get('/posts')\ndef list_posts(cursor_ts: str | None = None, cursor_id: int | None = None,\n               limit: int = Query(20, le=100)):\n    # 키셋 페이지네이션: 마지막으로 본 (ts,id) 이후를 조회\n    rows = repo.list_after(cursor_ts, cursor_id, limit)\n    next_cur = (rows[-1]['created_at'], rows[-1]['id']) if rows else None\n    return {'items': rows, 'next': next_cur}"},{"t":"배포","type":"note","goal":"이 서비스를 어떻게 배포·롤백할지 절차를 적어보세요. 마이그레이션은 어떻게 안전하게?","ph":"확장-수축 마이그레이션 · 헬스체크 · 롤백 기준..."},{"t":"장애 발생","type":"decide","goal":"배포 직후 목록 API의 p95가 3초로 튀었습니다.","sit":"방금 추가한 정렬/필터 쿼리가 인덱스를 안 타는 듯합니다. 무엇부터?","opts":[{"label":"EXPLAIN으로 실행계획을 보고 인덱스 사용 여부부터 확인한다","fx":{"debugging":5,"database":4},"fb":"✅ 추측 말고 실행계획으로 원인(Seq Scan 등)을 특정합니다.","best":true},{"label":"서버를 증설한다","fx":{"system_design":-1},"fb":"❌ 쿼리가 인덱스를 안 타면 증설은 돈만 씁니다.","best":false},{"label":"타임아웃을 늘려 에러만 감춘다","fx":{"performance":-2},"fb":"❌ 증상만 가리고 더 느려집니다.","best":false}]},{"t":"Postmortem","type":"note","goal":"장애의 근본 원인, 타임라인, 재발 방지책을 비난 없이(blameless) 정리하세요.","ph":"원인 / 영향 / 타임라인 / 재발방지..."}]},{"lv":5,"em":"🚀","title":"확장·배포·운영","desc":"성장하는 서비스의 아키텍처·배포·모니터링·장애·회고 의사결정 캠페인","skills":["devops","backend","sql"],"phases":[{"t":"요구사항·목표","type":"note","goal":"트래픽이 10배로 늘 예정입니다. 지켜야 할 SLO(가용성·지연)와 제약(예산·팀)을 적어보세요.","ph":"SLO: 가용성 99.9%, p95 < 300ms · 예산 제한..."},{"t":"아키텍처 결정","type":"decide","goal":"읽기 트래픽이 폭증합니다. 첫 카드는?","sit":"DB가 읽기로 CPU 한계. 예산·시간 제한.","opts":[{"label":"느린 쿼리 개선 + 캐시/읽기 복제로 읽기를 분산한다","fx":{"system_design":5,"database":4,"performance":3},"fb":"✅ 값싸고 되돌리기 쉬운 카드부터. 대부분의 읽기 병목은 여기서 풀립니다.","best":true},{"label":"곧바로 샤딩으로 쪼갠다","fx":{"system_design":-2},"fb":"⚠️ 운영 복잡도가 가장 큰 카드입니다. 마지막에.","best":false},{"label":"DB를 다른 제품으로 교체한다","fx":{"database":-2},"fb":"❌ 가장 위험·고비용이고 원인도 불명확합니다.","best":false}]},{"t":"CI/CD 파이프라인","type":"note","goal":"빌드→테스트→배포 파이프라인의 게이트(무엇을 통과해야 배포되는가)를 설계해 적어보세요.","ph":"단위·통합 테스트 통과 · 린트 · 취약점 스캔 · 스테이징 검증..."},{"t":"무중단 배포 결정","type":"decide","goal":"위험한 변경을 어떻게 내보낼까요?","sit":"결제 경로를 바꾸는 배포. 실패 시 영향이 큽니다.","opts":[{"label":"카나리 배포로 소량 트래픽에 먼저 태우고 지표를 보며 확대","fx":{"system_design":5,"leadership":2},"fb":"✅ 문제를 조기에 소규모로 잡아 전면 장애를 피합니다.","best":true},{"label":"한 번에 전체 배포한다","fx":{"system_design":-2},"fb":"❌ 문제가 있으면 전 사용자에 즉시 영향이 갑니다.","best":false},{"label":"금요일 밤에 몰래 배포한다","fx":{"leadership":-3},"fb":"❌ 관측·대응 인력이 없는 시간대 배포는 사고를 키웁니다.","best":false}]},{"t":"모니터링","type":"note","goal":"무엇을 계측하고 어떤 알림을 걸지 정하세요. (골든 시그널: 지연·트래픽·에러·포화)","ph":"p95 지연, 5xx 비율, 큐 길이, 리소스 포화 · 알림 임계치..."},{"t":"장애 대응","type":"decide","goal":"카나리에서 5xx가 튀었습니다.","sit":"새 버전 카나리군의 에러율만 급등.","opts":[{"label":"카나리를 즉시 롤백해 영향을 멈추고 로그로 원인 분석","fx":{"system_design":5,"leadership":4},"fb":"✅ 영향 차단이 근본원인 규명보다 먼저. 카나리라 피해도 작습니다.","best":true},{"label":"그대로 전체 배포를 강행한다","fx":{"leadership":-4},"fb":"❌ 확인된 회귀를 전 사용자에 퍼뜨립니다.","best":false},{"label":"알림을 끄고 지켜본다","fx":{"debugging":-3},"fb":"❌ 눈을 가리는 선택입니다.","best":false}]},{"t":"Postmortem·개선","type":"note","goal":"blameless postmortem을 작성하고, 다음 분기 신뢰성 개선 항목 3개를 도출하세요.","ph":"원인/영향/타임라인/액션아이템..."}]}]});
